/// A `vocab_heal_ledger` row: the full pre-image of rows an auto-heal mutated,
/// so the fix is reversible.
#[derive(Debug, Clone)]
pub struct VocabLedgerEntry {
    pub id: String,
    pub kind: String,
    pub old_value: String,
    pub new_value: String,
    pub pre_image: String,
    pub created_at: i64,
}

impl MemoryDB {
    /// Record a vocab auto-heal's full pre-image so the mutation can be undone.
    /// Every affected row id already lives inside `pre_image_json`; the ledger
    /// has no separate `affected` column.
    pub async fn insert_vocab_ledger_entry(
        &self,
        kind: &str,
        old_value: &str,
        new_value: &str,
        pre_image_json: &str,
    ) -> Result<String, WenlanError> {
        let id = format!("vheal-{}", uuid::Uuid::new_v4());
        let now = chrono::Utc::now().timestamp();
        let conn = self.conn.lock().await;
        conn.execute(
            "INSERT INTO vocab_heal_ledger (id, kind, old_value, new_value, pre_image, created_at) VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
            libsql::params![id.clone(), kind, old_value, new_value, pre_image_json, now],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("insert_vocab_ledger: {e}")))?;
        Ok(id)
    }

    /// Look up a vocab ledger entry by id, for reading back the pre-image on undo.
    pub async fn get_vocab_ledger_entry(
        &self,
        id: &str,
    ) -> Result<Option<VocabLedgerEntry>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT id, kind, old_value, new_value, pre_image, created_at FROM vocab_heal_ledger WHERE id = ?1",
                libsql::params![id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_vocab_ledger: {e}")))?;
        match rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            Some(row) => Ok(Some(VocabLedgerEntry {
                id: row
                    .get(0)
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?,
                kind: row
                    .get(1)
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?,
                old_value: row
                    .get(2)
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?,
                new_value: row
                    .get(3)
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?,
                pre_image: row
                    .get(4)
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?,
                created_at: row
                    .get(5)
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?,
            })),
            None => Ok(None),
        }
    }

    /// Fold every relation of `old_type` into `canonical`, collision-aware.
    ///
    /// Rewrites each `relations` row of `old_type` to `canonical`. On a
    /// `(from, to, canonical)` collision, merges the loser's provenance into the
    /// survivor (higher confidence wins; COALESCE explanation/source_memory_id)
    /// then deletes the loser — never a blind delete. Every folded row's
    /// pre-image is recorded to the ledger so the whole fold is reversible.
    /// Returns the number of rows folded.
    pub async fn fold_relation_type(
        &self,
        old_type: &str,
        canonical: &str,
    ) -> Result<usize, WenlanError> {
        // Self-fold would collide every row with itself and DELETE it: guard first.
        if old_type == canonical {
            return Ok(0);
        }
        let conn = self.conn.lock().await;
        conn.execute("BEGIN", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("fold begin: {e}")))?;

        // Run the snapshot + mutation loop in an inner block so any early Err
        // routes through ROLLBACK below instead of leaking an open transaction
        // on the shared connection (mirrors the migration-50 pattern).
        let result: Result<usize, WenlanError> = async {
            // Snapshot every row of old_type (the pre-image, for the ledger + undo).
            let mut rows = conn
                .query(
                    "SELECT id, from_entity, to_entity, confidence, explanation, source_memory_id, source_agent, created_at FROM relations WHERE relation_type = ?1",
                    libsql::params![old_type],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("fold snapshot: {e}")))?;
            let mut pre_image: Vec<serde_json::Value> = Vec::new();
            #[allow(clippy::type_complexity)]
            let mut ids: Vec<(
                String,
                String,
                String,
                Option<f64>,
                Option<String>,
                Option<String>,
            )> = Vec::new();
            while let Some(r) = rows
                .next()
                .await
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            {
                let id: String = r.get(0).unwrap_or_default();
                let from: String = r.get(1).unwrap_or_default();
                let to: String = r.get(2).unwrap_or_default();
                let conf: Option<f64> = r.get(3).ok();
                let expl: Option<String> = r.get(4).ok();
                let smid: Option<String> = r.get(5).ok();
                let sagent: Option<String> = r.get(6).ok();
                let created: Option<i64> = r.get(7).ok();
                pre_image.push(serde_json::json!({
                    "id": id, "from_entity": from, "to_entity": to, "relation_type": old_type,
                    "confidence": conf, "explanation": expl, "source_memory_id": smid,
                    "source_agent": sagent, "created_at": created,
                }));
                ids.push((id, from, to, conf, expl, smid));
            }
            drop(rows);

            let mut folded = 0usize;
            for (id, from, to, conf, expl, smid) in &ids {
                // Does a canonical edge already exist for this pair?
                let mut ex = conn
                    .query(
                        "SELECT id, confidence, explanation, source_memory_id, source_agent, created_at FROM relations WHERE from_entity = ?1 AND to_entity = ?2 AND relation_type = ?3",
                        libsql::params![from.clone(), to.clone(), canonical.to_string()],
                    )
                    .await
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
                if let Some(sr) = ex
                    .next()
                    .await
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?
                {
                    let s_id: String = sr.get(0).unwrap_or_default();
                    let s_conf: Option<f64> = sr.get(1).ok();
                    let s_expl: Option<String> = sr.get(2).ok();
                    let s_smid: Option<String> = sr.get(3).ok();
                    let s_sagent: Option<String> = sr.get(4).ok();
                    let s_created: Option<i64> = sr.get(5).ok();
                    drop(ex);
                    // The survivor is mutated too (its provenance is COALESCE-merged
                    // below), so per spec §2.5 ledger its full pre-image BEFORE the
                    // UPDATE, same shape as the loser's, so undo can restore it.
                    pre_image.push(serde_json::json!({
                        "id": s_id, "from_entity": from, "to_entity": to, "relation_type": canonical,
                        "confidence": s_conf, "explanation": s_expl, "source_memory_id": s_smid,
                        "source_agent": s_sagent, "created_at": s_created,
                    }));
                    // Merge provenance into the survivor: higher confidence wins; fill nulls.
                    let merged_conf = match (s_conf, conf) {
                        (Some(a), Some(b)) => Some(a.max(*b)),
                        (a, b) => a.or(*b),
                    };
                    let merged_expl = s_expl.or_else(|| expl.clone());
                    let merged_smid = s_smid.or_else(|| smid.clone());
                    conn.execute(
                        "UPDATE relations SET confidence = ?1, explanation = ?2, source_memory_id = ?3 WHERE from_entity = ?4 AND to_entity = ?5 AND relation_type = ?6",
                        libsql::params![
                            merged_conf.map(libsql::Value::Real).unwrap_or(libsql::Value::Null),
                            merged_expl.map(libsql::Value::Text).unwrap_or(libsql::Value::Null),
                            merged_smid.map(libsql::Value::Text).unwrap_or(libsql::Value::Null),
                            from.clone(), to.clone(), canonical.to_string()],
                    )
                    .await
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
                    // Delete the loser (its pre-image is already captured above).
                    conn.execute(
                        "DELETE FROM relations WHERE id = ?1",
                        libsql::params![id.clone()],
                    )
                    .await
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
                } else {
                    drop(ex);
                    conn.execute(
                        "UPDATE relations SET relation_type = ?1 WHERE id = ?2",
                        libsql::params![canonical.to_string(), id.clone()],
                    )
                    .await
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
                }
                folded += 1;
            }

            if !pre_image.is_empty() {
                let pre_json =
                    serde_json::to_string(&pre_image).unwrap_or_else(|_| "[]".into());
                let ledger_id = format!("vheal-{}", uuid::Uuid::new_v4());
                let now = chrono::Utc::now().timestamp();
                conn.execute(
                    "INSERT INTO vocab_heal_ledger (id, kind, old_value, new_value, pre_image, created_at) VALUES (?1, 'relation', ?2, ?3, ?4, ?5)",
                    libsql::params![ledger_id, old_type, canonical, pre_json, now],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("insert_vocab_ledger: {e}")))?;
            }

            Ok(folded)
        }
        .await;

        match result {
            Ok(folded) => {
                conn.execute("COMMIT", ())
                    .await
                    .map_err(|e| WenlanError::VectorDb(format!("fold commit: {e}")))?;
                Ok(folded)
            }
            Err(e) => {
                let _ = conn.execute("ROLLBACK", ()).await;
                Err(e)
            }
        }
    }

    /// All canonical entity types (lowercase), for safe-transform matching.
    pub async fn entity_canonicals(&self) -> Result<Vec<String>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT canonical FROM entity_type_vocabulary ORDER BY canonical",
                (),
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("entity_canonicals: {e}")))?;
        let mut out = Vec::new();
        while let Some(r) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            out.push(r.get::<String>(0).unwrap_or_default());
        }
        Ok(out)
    }

    /// Fold every entity of `old_type` into `canonical`. Plain rewrite: unlike
    /// relations, there's no unique constraint on `entities.entity_type`, so no
    /// collision handling is needed. Every folded row's pre-image is recorded
    /// to the ledger so the fold is reversible. Returns the number of rows folded.
    pub async fn fold_entity_type(
        &self,
        old_type: &str,
        canonical: &str,
    ) -> Result<usize, WenlanError> {
        // Snapshot the affected ids, rewrite them, and ledger the pre-image inside
        // ONE transaction so the UPDATE and the ledger write are atomic (mirrors
        // fold_relation_type's begin/commit/rollback). The ledger INSERT is inlined
        // on the held `conn` rather than routed through `insert_vocab_ledger_entry`,
        // which would re-lock the non-reentrant conn Mutex and self-deadlock.
        let conn = self.conn.lock().await;
        conn.execute("BEGIN", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("fold_entity begin: {e}")))?;

        let result: Result<usize, WenlanError> = async {
            let mut rows = conn
                .query(
                    "SELECT id FROM entities WHERE entity_type = ?1",
                    libsql::params![old_type],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
            let mut ids = Vec::new();
            while let Some(r) = rows
                .next()
                .await
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            {
                ids.push(r.get::<String>(0).unwrap_or_default());
            }
            drop(rows);
            if ids.is_empty() {
                return Ok(0);
            }
            let pre: Vec<serde_json::Value> = ids
                .iter()
                .map(|id| serde_json::json!({"id": id, "entity_type": old_type}))
                .collect();
            let pre_json = serde_json::to_string(&pre).unwrap_or_else(|_| "[]".into());

            conn.execute(
                "UPDATE entities SET entity_type = ?1 WHERE entity_type = ?2",
                libsql::params![canonical.to_string(), old_type.to_string()],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("fold_entity_type: {e}")))?;

            // Mirror the fold into the entity shadows (M3 PR-1 item C). This
            // fold only touches `entity_type`, so a set-based UPDATE of every
            // `kind='entity'` page still carrying `old_type` is exact parity
            // with the entities UPDATE above -- and self-heals any drift --
            // without needing to iterate the captured id list.
            let now_iso = chrono::Utc::now().to_rfc3339();
            conn.execute(
                "UPDATE pages SET entity_type = ?1, last_modified = ?2 \
                 WHERE kind = 'entity' AND entity_type = ?3",
                libsql::params![canonical.to_string(), now_iso, old_type.to_string()],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("fold_entity_type shadow: {e}")))?;

            let ledger_id = format!("vheal-{}", uuid::Uuid::new_v4());
            let now = chrono::Utc::now().timestamp();
            conn.execute(
                "INSERT INTO vocab_heal_ledger (id, kind, old_value, new_value, pre_image, created_at) VALUES (?1, 'entity', ?2, ?3, ?4, ?5)",
                libsql::params![ledger_id, old_type, canonical, pre_json, now],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("insert_vocab_ledger: {e}")))?;

            Ok(ids.len())
        }
        .await;

        match result {
            Ok(n) => {
                conn.execute("COMMIT", ())
                    .await
                    .map_err(|e| WenlanError::VectorDb(format!("fold_entity commit: {e}")))?;
                Ok(n)
            }
            Err(e) => {
                let _ = conn.execute("ROLLBACK", ()).await;
                Err(e)
            }
        }
    }
}

/// Embedding dimension — must match the model (BGE-Base-EN-v1.5-Q = 768).
pub const EMBEDDING_DIM: usize = 768;

/// Current DB schema version (highest `PRAGMA user_version` applied by `migrate()`).
/// Bump this whenever a new migration lands. Used as an eval cache invalidation key.
pub const SCHEMA_VERSION: u32 = 97;

/// Reserved id AND name of the uncategorized-page sentinel space (M1 honest
/// columns). Uncategorized pages store this value in `pages.space`/`workspace`
/// (both NOT NULL) instead of NULL; `row_to_page` folds it back to `None` on
/// the wire. It is minted by migration 80 as a spaces row whose `id` AND `name`
/// are both this UUID string — the name is the UUID (not the word "unfiled") so
/// a user's own space literally named "unfiled" can never collide with the
/// sentinel on the name-unique constraint. `create_space`/`update_space` reject
/// this exact string as a user-supplied name, keeping the reservation closed.
pub(crate) const UNFILED_SPACE_ID: &str = "00000000-0000-4000-8000-000000000001";

/// A retry receipt to commit alongside a mutation.
///
/// Borrowed rather than owned so a caller can hand one to the write without
/// cloning the response it already built.
#[derive(Debug, Clone, Copy)]
pub struct OperationReceipt<'a> {
    pub caller_id: &'a str,
    pub operation_id: &'a str,
    /// Digest of the request that produced `response`. A later call with the
    /// same `(caller_id, operation_id)` but a different digest is a different
    /// operation wearing a used id — a conflict, not a retry.
    pub request_digest: &'a str,
    /// Serialized response to hand back verbatim on a replay.
    pub response: &'a str,
}

/// A retry receipt as stored, returned when a caller replays an operation id.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StoredReceipt {
    pub request_digest: String,
    pub response: String,
    pub created_at: i64,
}

/// Test-only fault injection: abort a page write after the row, the history
/// row, and the receipt are all staged, but before COMMIT. That window is the
/// only place the "a receipt cannot outlive a rolled-back write" claim is
/// observable — a refused CAS returns long before the receipt is written, so
/// no ordinary test can tell an in-transaction receipt from an after-COMMIT
/// one. One-shot, and keyed to a page id so an armed fault cannot be consumed
/// by whatever else the test binary is writing in parallel.
#[cfg(test)]
pub(crate) static FAIL_BEFORE_COMMIT: std::sync::Mutex<Option<String>> =
    std::sync::Mutex::new(None);

#[cfg(test)]
fn take_fail_before_commit(page_id: &str) -> bool {
    let mut armed = FAIL_BEFORE_COMMIT.lock().unwrap();
    if armed.as_deref() == Some(page_id) {
        *armed = None;
        return true;
    }
    false
}

#[cfg(not(test))]
#[inline(always)]
fn take_fail_before_commit(_page_id: &str) -> bool {
    false
}

/// One recorded version of a page, as stored in `page_history`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PageHistoryEntry {
    pub version: i64,
    pub content: String,
    pub source_memory_ids: Vec<String>,
    pub edited_by: String,
    pub created_at: i64,
}

/// Shared embedder reference. Pass to [`MemoryDB::new_with_shared_embedder`] to
/// reuse a single embedder across many `MemoryDB` instances. Created via
/// [`MemoryDB::create_shared_embedder`]. Letting downstream callers spell out
/// this type without depending on `fastembed` directly.
pub type SharedEmbedder = Arc<std::sync::Mutex<TextEmbedding>>;

/// Process-wide lock that serializes FastEmbed (BGE) embedder initialization.
///
/// `TextEmbedding::try_new()` performs filesystem I/O against `~/.fastembed_cache`
/// via the `hf-hub` crate. Concurrent first-time inits race on that cache and
/// one of them fails with `Failed to retrieve model_optimized.onnx` (verified
/// against PR #23 CI: same process, same module, two parallel `MemoryDB::new`
/// calls — one fails, the next succeeds 1.4 s later). Holding this mutex
/// during `try_new` makes inits sequential within a process. Once the model
/// is on disk, subsequent inits are fast (model load, no download), so the
/// serialization cost is bounded.
///
/// This mutex is process-local. `cargo nextest` runs each test in a forked
/// process, so it cannot serialize cross-process races on the shared cache.
/// See [`acquire_embedder_init_file_lock`] for the cross-process companion.
static EMBEDDER_INIT_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

/// Acquire an OS-level exclusive file lock to serialize FastEmbed init across
/// processes.
///
/// `EMBEDDER_INIT_LOCK` only serializes within a single process. Under
/// `cargo nextest`, every test runs in its own forked process and they share
/// the same FastEmbed cache directory (`dirs::data_dir()/wenlan/memorydb/
/// fastembed_cache` on Linux when no per-DB cache or `WENLAN_TEST_FASTEMBED_CACHE`
/// override is set). Parallel test processes racing on that cache reproduce
/// the `Failed to retrieve model_optimized.onnx` symptom, surfacing as
/// post-merge main CI failures on a different test each run. This file lock
/// makes the OS serialize the inits at the filesystem layer; the returned
/// `File` releases the lock when it goes out of scope.
///
/// Returns `None` if path resolution or `OpenOptions` fails. In that case the
/// caller proceeds with only the process-local mutex (prior behavior).
fn acquire_embedder_init_file_lock(cache_dir: Option<&std::path::Path>) -> Option<std::fs::File> {
    let lock_dir = cache_dir
        .map(|p| p.to_path_buf())
        .or_else(|| dirs::data_dir().map(|d| d.join("wenlan/memorydb")))?;
    std::fs::create_dir_all(&lock_dir).ok()?;
    let lock_path = lock_dir.join(".embedder_init.lock");
    let file = std::fs::OpenOptions::new()
        .create(true)
        .write(true)
        .truncate(false)
        .open(&lock_path)
        .ok()?;
    file.lock().ok()?;
    Some(file)
}

/// Construct a FastEmbed text model behind the shared process + filesystem
/// locks. Every `TextEmbedding` initializer in this crate must use this seam:
/// nextest runs tests in separate processes, so a process-local singleton does
/// not protect a cold shared model cache.
#[allow(clippy::disallowed_methods)]
pub(crate) fn init_text_embedding(options: InitOptions) -> anyhow::Result<TextEmbedding> {
    // fastembed 5.13.1 gives HF_HOME precedence over options.cache_dir in
    // pull_from_hf(). Derive the lock domain from the same inputs here so a
    // caller cannot accidentally lock one directory while hf-hub mutates
    // another.
    let effective_cache_dir = std::env::var_os("HF_HOME")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| options.cache_dir.clone());
    let _file_lock = acquire_embedder_init_file_lock(Some(&effective_cache_dir));
    let _guard = EMBEDDER_INIT_LOCK.lock().unwrap_or_else(|p| p.into_inner());
    TextEmbedding::try_new(options)
}

/// Known-client registry — maps canonical technical IDs (what clients send in
/// `x-agent-name`) to human-friendly display names (what users see in UI).
///
/// **This is an OPEN registry, not an enum.** Unknown agents fall through to
/// their raw canonical ID. The registry exists only to make well-known MCP
/// clients display nicely out of the box — users don't have to manually
/// register `openai-mcp` to see it labeled `ChatGPT`.
///
/// User-set overrides (via `agent_connections.display_name`) always win over
/// entries here — see `row_to_agent`.
///
/// Keep this sorted by canonical ID.
pub const KNOWN_CLIENTS: &[(&str, &str)] = &[
    ("chatgpt", "ChatGPT"),
    ("claude-code", "Claude Code"),
    ("claude-desktop", "Claude Desktop"),
    ("codex", "Codex"),
    ("continue", "Continue"),
    ("cursor", "Cursor"),
    ("gemini-cli", "Gemini CLI"),
    ("obsidian", "Obsidian"),
    ("openai-mcp", "ChatGPT"),
    ("raycast", "Raycast"),
    ("vscode", "VS Code"),
    ("windsurf", "Windsurf"),
    ("zed", "Zed"),
];

/// Look up the friendly display name for a known canonical agent ID.
pub fn known_client_display_name(canonical: &str) -> Option<&'static str> {
    KNOWN_CLIENTS
        .iter()
        .find(|(k, _)| *k == canonical)
        .map(|(_, v)| *v)
}

/// Normalize an agent name into its canonical technical form.
///
/// - Trims whitespace.
/// - Lowercases.
/// - Collapses spaces, underscores, and dots into hyphens.
/// - Collapses runs of hyphens.
///
/// Idempotent: `canonicalize_agent_id(canonicalize_agent_id(x)) == canonicalize_agent_id(x)`.
///
/// Examples:
/// - `"Claude Code"` → `"claude-code"`
/// - `"CLAUDE_CODE"` → `"claude-code"`
/// - `"openai.mcp"`  → `"openai-mcp"`
pub fn canonicalize_agent_id(s: &str) -> String {
    let trimmed = s.trim().to_lowercase();
    let mut out = String::with_capacity(trimmed.len());
    let mut prev_dash = false;
    for ch in trimmed.chars() {
        let is_sep = ch == ' ' || ch == '_' || ch == '.' || ch == '-';
        if is_sep {
            if !prev_dash && !out.is_empty() {
                out.push('-');
                prev_dash = true;
            }
        } else {
            out.push(ch);
            prev_dash = false;
        }
    }
    // Trim trailing hyphen if any.
    while out.ends_with('-') {
        out.pop();
    }
    out
}

#[cfg(test)]
mod agent_id_tests {
    use super::*;

    #[test]
    fn canonicalize_handles_case_and_separators() {
        assert_eq!(canonicalize_agent_id("Claude Code"), "claude-code");
        assert_eq!(canonicalize_agent_id("CLAUDE_CODE"), "claude-code");
        assert_eq!(canonicalize_agent_id("claude.code"), "claude-code");
        assert_eq!(canonicalize_agent_id("  Claude   Code  "), "claude-code");
        assert_eq!(canonicalize_agent_id("claude-code"), "claude-code");
    }

    #[test]
    fn canonicalize_is_idempotent() {
        let once = canonicalize_agent_id("Open AI MCP");
        assert_eq!(canonicalize_agent_id(&once), once);
    }

    #[test]
    fn known_clients_are_canonical() {
        for (id, _) in KNOWN_CLIENTS {
            assert_eq!(
                *id,
                canonicalize_agent_id(id),
                "KNOWN_CLIENTS entry {id} is not canonical"
            );
        }
    }

    #[test]
    fn known_clients_lookup() {
        assert_eq!(known_client_display_name("openai-mcp"), Some("ChatGPT"));
        assert_eq!(
            known_client_display_name("claude-code"),
            Some("Claude Code")
        );
        assert_eq!(known_client_display_name("unknown-tool"), None);
    }
}

/// Resolve the directory FastEmbed should load the ONNX model from.
///
/// Resolution order (first hit wins):
///   1. The per-DB cache `<db_path>/fastembed_cache` when that directory
///      exists and is non-empty. This is what the running daemon uses
///      at the platform data directory (resolved via `dirs::data_local_dir()` per OS)
///      under `wenlan/memorydb/fastembed_cache`.
///   2. `WENLAN_TEST_FASTEMBED_CACHE` env var (escape hatch for CI).
///   3. `dirs::data_dir().join("wenlan/memorydb/fastembed_cache")` —
///      matches the production daemon's conventional path on the same
///      host, so tests that use a tempdir DB still pick up the already-
///      downloaded model instead of re-fetching from HuggingFace.
///   4. `None` — let FastEmbed use its own default (`~/.fastembed_cache/`)
///      and download the model if it isn't there. Fine for a dev box
///      with internet, fails noisily on hosts where the HuggingFace TLS
///      bundle misbehaves (see the `OSStatus -26276` symptom from
///      2026-04-16 that blocked ~240 tests from `test_db()`).
pub fn resolve_fastembed_cache_dir(db_path: &std::path::Path) -> Option<std::path::PathBuf> {
    // 1. Per-DB cache — production daemon populates this.
    let per_db = db_path.join("fastembed_cache");
    if per_db.exists()
        && std::fs::read_dir(&per_db)
            .map(|mut it| it.next().is_some())
            .unwrap_or(false)
    {
        return Some(per_db);
    }

    // 2. Explicit env override.
    if let Ok(env_cache) = std::env::var("WENLAN_TEST_FASTEMBED_CACHE") {
        let p = std::path::PathBuf::from(env_cache);
        if p.exists() {
            return Some(p);
        }
    }

    // 3. Shared host cache — matches the daemon's conventional path even
    //    when the caller supplied a tempdir.
    if let Some(shared) = dirs::data_dir().map(|d| d.join("wenlan/memorydb/fastembed_cache")) {
        if shared.exists()
            && std::fs::read_dir(&shared)
                .map(|mut it| it.next().is_some())
                .unwrap_or(false)
        {
            return Some(shared);
        }
    }

    None
}

/// Build the chunking engine for a DB at `db_path`, preferring token-aware
/// sizing (the BGE tokenizer loaded from the resolved FastEmbed cache) so no
/// embedded chunk exceeds the model's 512-token limit. Falls back to
/// character-based sizing when the tokenizer isn't on disk (e.g. FastEmbed's
/// default `~/.fastembed_cache` with no per-DB/shared cache resolved).
fn build_chunker(db_path: &Path) -> ChunkingEngine {
    resolve_fastembed_cache_dir(db_path)
        .as_deref()
        .and_then(crate::chunker::load_bge_tokenizer)
        .map(ChunkingEngine::with_tokenizer)
        .unwrap_or_default()
}

/// How many candidates to fetch from base retrieval before cross-encoder rerank.
///
/// Cross-encoder reorders within the candidate set but cannot promote anything
/// outside it. A narrow pool starves the reranker; a wider one gives it more
/// raw material at the cost of additional vector+FTS work. Mem0's `memory-decay`
/// path uses `top_k * 3` floored at 50.
///
/// Defaults preserve the pre-2026-05-25 behavior (`max(limit, 10)`) so non-eval
/// callers see no surprise change. The eval harness flips env to sweep.
///
/// * `multiplier_raw` — `RERANK_POOL_MULTIPLIER` env value (default 1, rejected if 0)
/// * `floor_raw`      — `RERANK_POOL_FLOOR` env value (default 10)
///
/// The final pool is `max(limit * multiplier, floor, limit)` with overflow guard.
pub fn compute_rerank_fetch_pool(
    limit: usize,
    multiplier_raw: Option<&str>,
    floor_raw: Option<&str>,
) -> usize {
    let multiplier: usize = multiplier_raw
        .and_then(|s| s.parse().ok())
        .filter(|&n: &usize| n >= 1)
        .unwrap_or(1);
    let floor: usize = floor_raw.and_then(|s| s.parse().ok()).unwrap_or(10);
    limit.saturating_mul(multiplier).max(floor).max(limit)
}

/// Handler-layer cross-encoder rerank for the LIGHT paths (quick `/api/search`,
/// context `/api/context`). Reorders `results` by the cross-encoder and
/// returns the top `limit`.
///
/// Deliberately a STANDALONE step, NOT folded into `search_memory`, so internal
/// callers (`search_corrections_by_topic`, `verify_page`) that call `search_memory`
/// directly never get — or pay for — CE. The daemon handler fetches a widened pool
/// via plain `search_memory`, then calls this. On reranker error / empty output the
/// input order is preserved. The sync CE runs off the async runtime via
/// `spawn_blocking`. No score blend (that is a deep-path opt-in); the CE score
/// replaces the prior score directly.
pub async fn rerank_results_light(
    reranker: Arc<dyn crate::reranker::Reranker>,
    query: &str,
    mut results: Vec<SearchResult>,
    limit: usize,
) -> Vec<SearchResult> {
    if results.len() > 1 {
        let candidates: Vec<(String, String)> = results
            .iter()
            .map(|r| (r.id.clone(), r.content.chars().take(512).collect()))
            .collect();
        let query_owned = query.to_string();
        match tokio::task::spawn_blocking(move || reranker.rerank(&query_owned, &candidates)).await
        {
            Ok(Ok(scored)) if !scored.is_empty() => {
                let ce_map: HashMap<String, f32> = scored.into_iter().collect();
                for r in &mut results {
                    if let Some(&s) = ce_map.get(&r.id) {
                        r.score = s;
                    }
                }
                results.sort_by(|a, b| {
                    b.score
                        .partial_cmp(&a.score)
                        .unwrap_or(std::cmp::Ordering::Equal)
                        .then_with(|| a.source_id.cmp(&b.source_id))
                });
            }
            Ok(Ok(_)) => {} // empty rerank output -> keep original order
            Ok(Err(e)) => {
                log::warn!("[reranker-light] rerank err: {e}; keeping original order")
            }
            Err(e) => log::warn!("[reranker-light] join failed: {e}; keeping original order"),
        }
    }
    results.truncate(limit);
    results
}

/// True iff `WENLAN_ENABLE_PAGE_CHANNEL` is set to a truthy value
/// (`1`, `true`, or `yes`, case-insensitive). The page-channel is OPT-IN:
/// unset or a falsey value (`0`/`false`/`no`/"") leaves it disabled.
///
/// Used by [`MemoryDB::search_memory_cross_rerank`] to gate the page-channel
/// branch and by the eval harness (locomo + longmemeval) to tag baseline
/// JSON artifacts with their page-ON/OFF variant. All five call sites MUST
/// share this helper so an `WENLAN_ENABLE_PAGE_CHANNEL` setting can't
/// disagree between production and eval (which would make baseline filenames
/// lie about their contents — see AGENTS.md Eval Citation Discipline).
///
/// Truthy-only parse (not `is_ok()`): operators enable the channel by setting
/// the var to a truthy value; any other value or unset = disabled.
pub fn page_channel_enabled() -> bool {
    std::env::var("WENLAN_ENABLE_PAGE_CHANNEL")
        .ok()
        .map(|v| matches!(v.trim().to_ascii_lowercase().as_str(), "1" | "true" | "yes"))
        .unwrap_or(false)
}

/// True iff `WENLAN_ENABLE_EVICTION` is set to a truthy value (`1`, `true`, or
/// `yes`, case-insensitive). When enabled, the refinery's `evict` phase flips
/// stale, low-`effective_confidence`, non-immune memories to
/// `supersede_mode='evicted'` (recoverable, never hard-deleted). `'evicted'` is
/// a distinct marker from the pre-existing `'archive'` (migration 10 stamps all
/// `decision` rows `'archive'` while keeping them visible), so eviction never
/// collides with decisions.
///
/// Default OFF: unset or any falsey value leaves the write/refinery path
/// byte-identical (unbounded append, nothing archived by policy — preserving
/// the "no memory count cap" contract). Truthy-only parse, verbatim copy of
/// [`page_channel_enabled`]. T21 Stage 1.
pub fn eviction_enabled() -> bool {
    std::env::var("WENLAN_ENABLE_EVICTION")
        .ok()
        .map(|v| matches!(v.trim().to_ascii_lowercase().as_str(), "1" | "true" | "yes"))
        .unwrap_or(false)
}

/// True iff `WENLAN_ENABLE_GLOBAL_PRELUDE` is set to a truthy value
/// (`1`, `true`, or `yes`, case-insensitive). T18 hierarchical global-context
/// prelude is OPT-IN, default OFF (ship-dark): unset or a falsey value
/// (`0`/`false`/`no`/"") leaves both the refinery build path and
/// [`MemoryDB::search_memory_cross_rerank`] byte-identical to pre-T18 (no
/// summary build, no `source="summary"` rows prepended, no extra read query).
///
/// When enabled, the refinery's `SummaryRollup` phase builds per-bucket +
/// root `summary_nodes`, and the read path prepends them as a corpus-overview
/// prelude (excluded from the reranker candidate pool and from positions
/// `[0, limit)` of the gold-id window). All call sites (build-phase guard,
/// read gate, production `## Corpus Overview` section, any future eval tag)
/// MUST share this helper so the env var cannot disagree between production and
/// eval (which would make baseline filenames lie). Mirrors [`page_channel_enabled`].
pub fn global_prelude_enabled() -> bool {
    std::env::var("WENLAN_ENABLE_GLOBAL_PRELUDE")
        .ok()
        .map(|v| matches!(v.trim().to_ascii_lowercase().as_str(), "1" | "true" | "yes"))
        .unwrap_or(false)
}

/// Expansion temperature for the legacy `search_memory_expanded` paraphrase
/// call. `WENLAN_EXPAND_TEMP` overrides the historical 0.3 default (used by the
/// Track-2 temperature-isolation A/B). Non-finite / negative / unparseable falls
/// back to 0.3.
pub fn expand_temperature() -> f32 {
    std::env::var("WENLAN_EXPAND_TEMP")
        .ok()
        .and_then(|v| v.trim().parse::<f32>().ok())
        .filter(|t| t.is_finite() && *t >= 0.0)
        .unwrap_or(0.3)
}

/// Outcome of one `evict_stale` run. T21 Stage 1 only ever archives
/// (`deleted` is always 0); `skipped_disabled` is true when the env flag is off.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EvictionReport {
    /// Number of memories flipped to `supersede_mode='evicted'`.
    pub archived: usize,
    /// Number of memories hard-deleted. Always 0 in Stage 1 (archive-not-delete).
    pub deleted: usize,
    /// True when `WENLAN_ENABLE_EVICTION` was off, so nothing ran.
    pub skipped_disabled: bool,
}

/// A row considered for eviction. Built from the candidate SELECT and fed to the
/// pure [`select_evictions`] policy function.
#[derive(Debug, Clone)]
pub struct EvictCandidate {
    pub source_id: String,
    pub effective_confidence: f64,
    /// Raw `last_accessed` cell as stored (ISO datetime string OR epoch string).
    /// Parsed via [`crate::decay::days_since`], mirroring `decay_update_confidence`.
    pub last_accessed: Option<String>,
    pub memory_type: Option<String>,
    /// Per-space grouping key (`domain` column). `None` rows never hit the cap.
    pub space: Option<String>,
}

/// Pure eviction policy: given candidate rows and config, return the set of
/// `source_id`s to archive. Separated from the DB mutation so the selection
/// logic is unit-testable in isolation (candidate set in -> evict set out).
///
/// A row is archived when EITHER:
///   1. it passes both independent gates — `effective_confidence` strictly below
///      `evict_confidence_floor` AND `last_accessed` at least `min_age_days` old
///      (age computed in Rust to dodge the TEXT/INTEGER affinity of the
///      `last_accessed` column), OR
///   2. its space is over `per_space_cap` and it is in the lowest-confidence
///      overflow for that space (additive selection, independent of the floor).
///
/// Protected-tier rows (identity/preference/goal) are never selected; confirmed
/// and pinned rows are excluded upstream in the SELECT. Age/floor gates hold
/// independently: a fresh low-confidence row survives, an old high-confidence
/// row survives.
pub fn select_evictions(
    candidates: &[EvictCandidate],
    cfg: &crate::tuning::EvictionConfig,
    now_epoch: i64,
) -> Vec<String> {
    use std::collections::BTreeSet;

    // Protected-tier memories are immune regardless of age/confidence/cap.
    let eligible: Vec<&EvictCandidate> = candidates
        .iter()
        .filter(|c| {
            crate::sources::stability_tier(c.memory_type.as_deref())
                != crate::sources::StabilityTier::Protected
        })
        .collect();

    let mut selected: BTreeSet<String> = BTreeSet::new();

    // Gate 1 — independent floor + age gates.
    for c in &eligible {
        let old_enough = crate::decay::days_since(c.last_accessed.as_deref(), now_epoch)
            >= cfg.min_age_days as f64;
        let low_value = c.effective_confidence < cfg.evict_confidence_floor;
        if old_enough && low_value {
            selected.insert(c.source_id.clone());
        }
    }

    // Gate 2 — per-space cap overflow (lowest effective_confidence first).
    // Age-gated: only rows at least `min_age_days` old are cap-eligible, so a
    // fresh high-confidence row is NEVER evicted purely for crowding regardless
    // of space pressure. Fresh rows are excluded from the cap population
    // entirely — only stale rows can be capped.
    if let Some(cap) = cfg.per_space_cap {
        let mut by_space: std::collections::HashMap<&str, Vec<&EvictCandidate>> =
            std::collections::HashMap::new();
        for c in &eligible {
            let old_enough = crate::decay::days_since(c.last_accessed.as_deref(), now_epoch)
                >= cfg.min_age_days as f64;
            if !old_enough {
                continue;
            }
            if let Some(space) = c.space.as_deref() {
                by_space.entry(space).or_default().push(c);
            }
        }
        for (_space, mut rows) in by_space {
            if rows.len() > cap {
                // Sort ascending by effective_confidence; lowest are archived.
                rows.sort_by(|a, b| {
                    a.effective_confidence
                        .partial_cmp(&b.effective_confidence)
                        .unwrap_or(std::cmp::Ordering::Equal)
                });
                let overflow = rows.len() - cap;
                for c in rows.into_iter().take(overflow) {
                    selected.insert(c.source_id.clone());
                }
            }
        }
    }

    selected.into_iter().collect()
}

/// True iff `WENLAN_ENABLE_DUAL_POOL_RESOLVE` is set to a truthy value
/// (`1`, `true`, or `yes`, case-insensitive). When enabled, `handle_store_memory`
/// resolves each incoming memory against two candidate pools (near-duplicates +
/// possibly-contradicting same-entity/domain rows) in a single LLM call and acts
/// on the result: invalidations soft-suppress the older side (bidirectional
/// temporal expiry), duplicates file a consolidation proposal.
///
/// Default OFF: unset or any falsey value (`0`/`false`/`no`/`""`) leaves the
/// write path byte-identical (no extra vector query, no LLM call, no mutation).
/// Truthy-only parse, mirrors [`page_channel_enabled`].
pub fn dual_pool_resolve_enabled() -> bool {
    std::env::var("WENLAN_ENABLE_DUAL_POOL_RESOLVE")
        .ok()
        .map(|v| matches!(v.trim().to_ascii_lowercase().as_str(), "1" | "true" | "yes"))
        .unwrap_or(false)
}

/// True iff `WENLAN_ENABLE_REFLECTION_DEBOUNCE` is set to a truthy value
/// (`1`, `true`, or `yes`, case-insensitive). When enabled, `handle_store_memory`
/// routes its deferred post-ingest enrichment through a per-agent debouncer
/// (`wenlan_server::reflection_debounce::ReflectionDebouncer`) so a burst of
/// rapid same-agent stores coalesces to a single reflection of the last write
/// instead of N overlapping enrichment tasks.
///
/// Default OFF: unset or any falsey value (`0`/`false`/`no`/`""`) leaves the
/// write path byte-identical — the existing detached `tokio::spawn` runs
/// verbatim with `cancel = None`, no debouncer consulted. Truthy-only parse,
/// mirrors [`page_channel_enabled`].
pub fn reflection_debounce_enabled() -> bool {
    std::env::var("WENLAN_ENABLE_REFLECTION_DEBOUNCE")
        .ok()
        .map(|v| matches!(v.trim().to_ascii_lowercase().as_str(), "1" | "true" | "yes"))
        .unwrap_or(false)
}

/// True iff `WENLAN_ENABLE_TEMPORAL_GROUNDING` is set to a truthy value
/// (`1`, `true`, or `yes`, case-insensitive). When enabled, `upsert_documents`
/// deterministically rewrites relative date phrases in memory prose to include
/// absolute dates, anchored to the memory's `last_modified` (observation date),
/// **before** embedding and INSERT. This makes the embedder and FTS index see
/// grounded text so temporal queries can match literal dates.
///
/// Default OFF: unset or any falsey value (`0`/`false`/`no`/`""`) leaves the
/// write path byte-identical to pre-T11. Truthy-only parse, mirrors
/// [`page_channel_enabled`].
pub fn temporal_grounding_enabled() -> bool {
    std::env::var("WENLAN_ENABLE_TEMPORAL_GROUNDING")
        .ok()
        .map(|v| matches!(v.trim().to_ascii_lowercase().as_str(), "1" | "true" | "yes"))
        .unwrap_or(false)
}

/// True iff `WENLAN_ENABLE_EPISODE_CHANNEL` is set to a truthy value
/// (`1`, `true`, or `yes`, case-insensitive). The episode-channel is OPT-IN
/// (master write+read switch): unset or a falsey value (`0`/`false`/`no`/"")
/// leaves it disabled, so behaviour is byte-identical to pre-T2.
///
/// When enabled, `upsert_documents` co-writes a verbatim "episode" row beside
/// each distilled `source='memory'` fact, and
/// [`MemoryDB::search_memory_cross_rerank`] injects those episodes as a 5th RRF
/// stream. The eval harness reads this same helper so an
/// `WENLAN_ENABLE_EPISODE_CHANNEL` setting can't disagree between production and
/// eval (which would make baseline filenames lie). Mirrors
/// [`page_channel_enabled`] (truthy-only parse).
pub fn episode_channel_enabled() -> bool {
    std::env::var("WENLAN_ENABLE_EPISODE_CHANNEL")
        .ok()
        .map(|v| matches!(v.trim().to_ascii_lowercase().as_str(), "1" | "true" | "yes"))
        .unwrap_or(false)
}

/// True iff `WENLAN_ENABLE_ENTITY_MINHASH` is set to a truthy value
/// (`1`, `true`, or `yes`, case-insensitive). The deterministic MinHash/LSH
/// entity near-dedup cascade (T16) is OPT-IN: unset or a falsey value
/// (`0`/`false`/`no`/"") leaves entity resolution byte-identical to the
/// pre-T16 4-step cascade (alias -> exact-name -> vector -> create).
///
/// When enabled, `post_write::create_entity` and `importer::resolve_entity_bulk`
/// insert a "Step 2.5" between the exact-name and vector steps: high-entropy
/// names are char-shingled, MinHash-signed, LSH-banded, and confirmed with an
/// exact Jaccard >= 0.9 against same-type band collisions. Mirrors
/// [`page_channel_enabled`] (truthy-only parse) so production and any future
/// eval wiring can't disagree on the flag.
pub fn entity_minhash_enabled() -> bool {
    std::env::var("WENLAN_ENABLE_ENTITY_MINHASH")
        .ok()
        .map(|v| matches!(v.trim().to_ascii_lowercase().as_str(), "1" | "true" | "yes"))
        .unwrap_or(false)
}

/// Minimum verbatim word count for an episode co-write. Short turns ("ok",
/// "loves rust") carry no retrieval signal that the distilled fact doesn't
/// already cover, so they're skipped to keep the corpus-doubling cost bounded.
/// Override with `WENLAN_EPISODE_WORD_GATE` (default 8). Mirrors the
/// env-override pattern used by the page/session limits.
pub(crate) fn episode_word_gate() -> usize {
    std::env::var("WENLAN_EPISODE_WORD_GATE")
        .ok()
        .and_then(|s| s.trim().parse().ok())
        .unwrap_or(8)
}

/// Outcome of [`derive_episode`]: the deterministic id, the redacted verbatim
/// text (used as both the stored `content` and the embed input), and its word
/// count.
pub(crate) struct EpisodeDerivation {
    pub episode_id: String,
    pub verbatim: String,
    pub word_count: i64,
}

/// The canonical verbatim-episode derivation shared by the write-path co-write
/// in [`MemoryDB::upsert_documents`] and the additive
/// [`MemoryDB::backfill_episodes`] seed pass. Centralising the four drift-prone
/// decisions — verbatim selection (`source_text` over `content`), PII redaction,
/// the word gate, and the deterministic `sha256("episode:{source_id}:0")[..16]`
/// id — keeps the two paths from disagreeing (AGENTS.md training-serving skew,
/// Google Rules of ML #32). Returns `None` when the redacted verbatim turn is
/// below `word_gate` words (short turns carry no signal the distilled fact
/// lacks). The seed path never sets `source_text`, so `content` is the verbatim
/// in both the co-write and the backfill — a backfilled seed is byte-identical
/// to a fresh `WENLAN_ENABLE_EPISODE_CHANNEL=1` ingest.
pub(crate) fn derive_episode(
    source_id: &str,
    source_text: Option<&str>,
    content: &str,
    word_gate: usize,
) -> Option<EpisodeDerivation> {
    let verbatim = redact_pii(source_text.unwrap_or(content));
    let word_count = verbatim.split_whitespace().count();
    if word_count < word_gate {
        return None;
    }
    let mut hasher = Sha256::new();
    hasher.update(format!("episode:{source_id}:0").as_bytes());
    let hash = format!("{:x}", hasher.finalize());
    Some(EpisodeDerivation {
        episode_id: hash[..16].to_string(),
        verbatim,
        word_count: word_count as i64,
    })
}

fn derive_memory_child_fields(
    content: &str,
    structured_fields: Option<&str>,
) -> Vec<(String, String)> {
    let mut fields = Vec::new();
    let content = redact_pii(content);
    if !content.trim().is_empty() {
        fields.push(("narrative".to_string(), content));
    }
    if let Some(structured_fields) = structured_fields {
        for child in crate::schema::split_structured_fields_to_facts(structured_fields) {
            let field = child
                .split_once(": ")
                .map(|(key, _)| key.to_string())
                .unwrap_or_else(|| "field".to_string());
            fields.push((field, child));
        }
    }
    fields
}

fn child_vector_id(parent_id: &str, field: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(parent_id.as_bytes());
    hasher.update(b"|");
    hasher.update(field.as_bytes());
    let hash = format!("{:x}", hasher.finalize());
    hash[..16].to_string()
}

