        let conn = self.conn.lock().await;
        let mut rows = conn
            .query("SELECT DISTINCT tag FROM document_tags ORDER BY tag", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("list_all_tags: {e}")))?;
