    /// Fetch multiple memories by source_id in a single query.
    /// Returns only the source_ids that exist; missing ids are silently omitted.
    /// Preserves input order.
    pub async fn get_memories_by_source_ids(
        &self,
        source_ids: &[String],
    ) -> Result<Vec<MemoryItem>, WenlanError> {
        if source_ids.is_empty() {
            return Ok(vec![]);
        }
        let placeholders = source_ids
            .iter()
            .enumerate()
            .map(|(i, _)| format!("?{}", i + 1))
            .collect::<Vec<_>>()
            .join(",");
        let sql = format!(
            "SELECT source_id, title,
                GROUP_CONCAT(content, '\n') as content,
                MAX(summary) as summary,
                MAX(memory_type) as memory_type,
                MAX(space) as space,
                MAX(source_agent) as source_agent,
                MAX(confidence) as confidence,
                MAX(confirmed) as confirmed,
                MAX(stability) as stability,
                MAX(pinned) as pinned,
                MAX(supersedes) as supersedes,
                MAX(last_modified) as last_modified,
                COUNT(*) as chunk_count,
                MAX(entity_id) as entity_id,
                MAX(quality) as quality,
                MAX(is_recap) as is_recap,
                (SELECT CASE
                    WHEN COUNT(es.source_id) = 0 THEN 'raw'
                    WHEN SUM(CASE WHEN es.status = 'failed' OR es.status = 'abandoned' THEN 1 ELSE 0 END) = 0 THEN 'enriched'
                    WHEN SUM(CASE WHEN es.status IN ('ok','skipped') THEN 1 ELSE 0 END) = 0 THEN 'enrichment_failed'
                    ELSE 'enrichment_partial'
                END FROM enrichment_steps es WHERE es.source_id = memories.source_id) AS enrichment_status,
                MAX(supersede_mode) as supersede_mode,
                MAX(structured_fields) as structured_fields,
                MAX(retrieval_cue) as retrieval_cue,
                SUM(access_count) as access_count,
                MAX(source_text) as source_text,
                MAX(version) as version,
                MAX(changelog) as changelog
             FROM memories
             WHERE pending_revision = 0
               AND source != 'episode'
               AND source_id IN ({placeholders})
             GROUP BY source_id"
        );
        let conn = self.conn.lock().await;
        let params: Vec<libsql::Value> = source_ids
            .iter()
            .map(|id| libsql::Value::Text(id.clone()))
            .collect();
        let mut rows = conn
            .query(&sql, libsql::params_from_iter(params))
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_memories_by_source_ids: {e}")))?;

        // Build a map keyed by source_id, then re-order to match input order.
        let mut map: std::collections::HashMap<String, MemoryItem> =
            std::collections::HashMap::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            let item = MemoryItem {
                source_id: row.get::<String>(0).unwrap_or_default(),
                title: row.get::<String>(1).unwrap_or_default(),
                content: row.get::<String>(2).unwrap_or_default(),
                summary: row.get::<Option<String>>(3).unwrap_or(None),
                memory_type: row.get::<Option<String>>(4).unwrap_or(None),
                space: row.get::<Option<String>>(5).unwrap_or(None),
                source_agent: row.get::<Option<String>>(6).unwrap_or(None),
                confidence: row.get::<Option<f64>>(7).unwrap_or(None).map(|v| v as f32),
                confirmed: row.get::<i64>(8).unwrap_or(0) != 0,
                stability: row.get::<Option<String>>(9).unwrap_or(None),
                pinned: row.get::<i64>(10).unwrap_or(0) != 0,
                supersedes: row.get::<Option<String>>(11).unwrap_or(None),
                last_modified: row.get::<i64>(12).unwrap_or(0),
                chunk_count: row.get::<u64>(13).unwrap_or(0),
                entity_id: row.get::<Option<String>>(14).unwrap_or(None),
                quality: row.get::<Option<String>>(15).unwrap_or(None),
                is_recap: row.get::<i64>(16).unwrap_or(0) != 0,
                enrichment_status: row.get::<String>(17).unwrap_or_else(|_| "raw".to_string()),
                supersede_mode: row.get::<String>(18).unwrap_or_else(|_| "hide".to_string()),
                structured_fields: row.get::<Option<String>>(19).unwrap_or(None),
                retrieval_cue: row.get::<Option<String>>(20).unwrap_or(None),
                access_count: row.get::<u64>(21).unwrap_or(0),
                source_text: row.get::<Option<String>>(22).unwrap_or(None),
                version: row.get::<i64>(23).unwrap_or(1),
                changelog: row.get::<Option<String>>(24).unwrap_or(None),
                pending_revision: false,
                merged_from: None,
            };
            map.insert(item.source_id.clone(), item);
        }
        // Return in input order, skipping missing ids.
        let items = source_ids.iter().filter_map(|id| map.remove(id)).collect();
        Ok(items)
    }

    pub async fn get_memory_detail_scoped(
        &self,
        source_id: &str,
        scope: &ReadScope,
    ) -> Result<Option<MemoryItem>, WenlanError> {
        let mut items = self
            .get_memories_by_source_ids_scoped(&[source_id.to_string()], scope)
            .await?;
        Ok(items.pop())
    }

    pub async fn get_memories_by_source_ids_scoped(
        &self,
        source_ids: &[String],
        scope: &ReadScope,
    ) -> Result<Vec<MemoryItem>, WenlanError> {
        if source_ids.is_empty() {
            return Ok(vec![]);
        }
        let placeholders = std::iter::repeat_n("?", source_ids.len())
            .collect::<Vec<_>>()
            .join(",");
        let mut conditions = vec![
            "pending_revision = 0".to_string(),
            "source = 'memory'".to_string(),
            format!("source_id IN ({placeholders})"),
        ];
        let mut values = source_ids
            .iter()
            .cloned()
            .map(libsql::Value::Text)
            .collect::<Vec<_>>();
        push_read_scope_filter_folded(scope, "space", &mut conditions, &mut values);
        let sql = format!(
            "SELECT source_id, title,
                GROUP_CONCAT(content, '\n') as content,
                MAX(summary) as summary,
                MAX(memory_type) as memory_type,
                MAX(space) as space,
                MAX(source_agent) as source_agent,
                MAX(confidence) as confidence,
                MAX(confirmed) as confirmed,
                MAX(stability) as stability,
                MAX(pinned) as pinned,
                MAX(supersedes) as supersedes,
                MAX(last_modified) as last_modified,
                COUNT(*) as chunk_count,
                MAX(entity_id) as entity_id,
                MAX(quality) as quality,
                MAX(is_recap) as is_recap,
                (SELECT CASE
                    WHEN COUNT(es.source_id) = 0 THEN 'raw'
                    WHEN SUM(CASE WHEN es.status = 'failed' OR es.status = 'abandoned' THEN 1 ELSE 0 END) = 0 THEN 'enriched'
                    WHEN SUM(CASE WHEN es.status IN ('ok','skipped') THEN 1 ELSE 0 END) = 0 THEN 'enrichment_failed'
                    ELSE 'enrichment_partial'
                END FROM enrichment_steps es WHERE es.source_id = memories.source_id) AS enrichment_status,
                MAX(supersede_mode) as supersede_mode,
                MAX(structured_fields) as structured_fields,
                MAX(retrieval_cue) as retrieval_cue,
                SUM(access_count) as access_count,
                MAX(source_text) as source_text,
                MAX(version) as version,
                MAX(changelog) as changelog
             FROM memories
             WHERE {}
             GROUP BY source_id",
            conditions.join(" AND ")
        );
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(&sql, libsql::params_from_iter(values))
            .await
            .map_err(|e| {
                WenlanError::VectorDb(format!("get_memories_by_source_ids_scoped: {e}"))
            })?;

        let mut map = std::collections::HashMap::<String, MemoryItem>::new();
        while let Some(row) = rows.next().await.map_err(|e| {
            WenlanError::VectorDb(format!("get_memories_by_source_ids_scoped row: {e}"))
        })? {
            let item = MemoryItem {
                source_id: row.get::<String>(0).unwrap_or_default(),
                title: row.get::<String>(1).unwrap_or_default(),
                content: row.get::<String>(2).unwrap_or_default(),
                summary: row.get::<Option<String>>(3).unwrap_or(None),
                memory_type: row.get::<Option<String>>(4).unwrap_or(None),
                space: row.get::<Option<String>>(5).unwrap_or(None),
                source_agent: row.get::<Option<String>>(6).unwrap_or(None),
                confidence: row.get::<Option<f64>>(7).unwrap_or(None).map(|v| v as f32),
                confirmed: row.get::<i64>(8).unwrap_or(0) != 0,
                stability: row.get::<Option<String>>(9).unwrap_or(None),
                pinned: row.get::<i64>(10).unwrap_or(0) != 0,
                supersedes: row.get::<Option<String>>(11).unwrap_or(None),
                last_modified: row.get::<i64>(12).unwrap_or(0),
                chunk_count: row.get::<u64>(13).unwrap_or(0),
                entity_id: row.get::<Option<String>>(14).unwrap_or(None),
                quality: row.get::<Option<String>>(15).unwrap_or(None),
                is_recap: row.get::<i64>(16).unwrap_or(0) != 0,
                enrichment_status: row.get::<String>(17).unwrap_or_else(|_| "raw".to_string()),
                supersede_mode: row.get::<String>(18).unwrap_or_else(|_| "hide".to_string()),
                structured_fields: row.get::<Option<String>>(19).unwrap_or(None),
                retrieval_cue: row.get::<Option<String>>(20).unwrap_or(None),
                access_count: row.get::<u64>(21).unwrap_or(0),
                source_text: row.get::<Option<String>>(22).unwrap_or(None),
                version: row.get::<i64>(23).unwrap_or(1),
                changelog: row.get::<Option<String>>(24).unwrap_or(None),
                pending_revision: false,
                merged_from: None,
            };
            map.insert(item.source_id.clone(), item);
        }

        Ok(source_ids
            .iter()
            .filter_map(|id| map.get(id).cloned())
            .collect())
    }

    /// Load confirmed memories of a specific type, excluding superseded ones.
    /// Optionally filter by space when `space_filter` is `Some`.
    pub async fn load_memories_by_type(
        &self,
        memory_type: &str,
        limit: usize,
        space_filter: Option<&str>,
    ) -> Result<Vec<MemoryItem>, WenlanError> {
        let scope = legacy_read_scope(space_filter);
        self.load_memories_by_type_scoped(memory_type, limit, &scope)
            .await
    }

    pub async fn load_memories_by_type_scoped(
        &self,
        memory_type: &str,
        limit: usize,
        scope: &ReadScope,
    ) -> Result<Vec<MemoryItem>, WenlanError> {
        let conn = self.conn.lock().await;
        let hidden_by_superseder = superseder_not_exists(
            scope,
            "memories",
            "superseder.pending_revision = 0 AND superseder.source = 'memory'",
        );
        let supersedes_exclusion = format!("AND pending_revision = 0 AND {hidden_by_superseder}");

        let space_clause = match scope {
            ReadScope::Global => "",
            ReadScope::Space(_) => "AND space = ?3",
            ReadScope::Uncategorized => {
                "AND (space IS NULL OR space = '00000000-0000-4000-8000-000000000001')"
            }
        };

        let sql = format!(
            "SELECT source_id, MAX(title) as title,
                    GROUP_CONCAT(content, '\n') as content,
                    MAX(summary) as summary,
                    MAX(memory_type) as memory_type,
                    MAX(space) as space,
                    MAX(source_agent) as source_agent,
                    MAX(confidence) as confidence,
                    MAX(confirmed) as confirmed,
                    MAX(stability) as stability,
                    MAX(pinned) as pinned,
                    MAX(supersedes) as supersedes,
                    MAX(last_modified) as last_modified,
                    COUNT(*) as chunk_count,
                    MAX(entity_id) as entity_id,
                    MAX(quality) as quality,
                    MAX(is_recap) as is_recap,
                    (SELECT CASE
                        WHEN COUNT(es.source_id) = 0 THEN 'raw'
                        WHEN SUM(CASE WHEN es.status = 'failed' OR es.status = 'abandoned' THEN 1 ELSE 0 END) = 0 THEN 'enriched'
                        WHEN SUM(CASE WHEN es.status IN ('ok','skipped') THEN 1 ELSE 0 END) = 0 THEN 'enrichment_failed'
                        ELSE 'enrichment_partial'
                    END FROM enrichment_steps es WHERE es.source_id = memories.source_id) AS enrichment_status,
                    MAX(supersede_mode) as supersede_mode,
                    MAX(structured_fields) as structured_fields,
                    MAX(retrieval_cue) as retrieval_cue,
                    SUM(access_count) as access_count,
                    MAX(source_text) as source_text,
                    MAX(version) as version,
                    MAX(changelog) as changelog
             FROM memories
             WHERE source = 'memory' AND memory_type = ?1 AND confirmed != 0
             {} {}
             GROUP BY source_id
             ORDER BY last_modified DESC
             LIMIT ?2",
            supersedes_exclusion, space_clause
        );

        let mut rows = match scope {
            ReadScope::Global | ReadScope::Uncategorized => {
                conn.query(&sql, libsql::params![memory_type.to_string(), limit as i64])
                    .await
            }
            ReadScope::Space(space) => {
                conn.query(
                    &sql,
                    libsql::params![memory_type.to_string(), limit as i64, space.clone()],
                )
                .await
            }
        }
        .map_err(|e| WenlanError::VectorDb(format!("load_memories_by_type: {}", e)))?;

        let mut items = Vec::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            items.push(MemoryItem {
                source_id: row.get::<String>(0).unwrap_or_default(),
                title: row.get::<String>(1).unwrap_or_default(),
                content: row.get::<String>(2).unwrap_or_default(),
                summary: row.get::<Option<String>>(3).unwrap_or(None),
                memory_type: row.get::<Option<String>>(4).unwrap_or(None),
                space: row.get::<Option<String>>(5).unwrap_or(None),
                source_agent: row.get::<Option<String>>(6).unwrap_or(None),
                confidence: row.get::<Option<f64>>(7).unwrap_or(None).map(|v| v as f32),
                confirmed: row.get::<i64>(8).unwrap_or(0) != 0,
                stability: row.get::<Option<String>>(9).unwrap_or(None),
                pinned: row.get::<i64>(10).unwrap_or(0) != 0,
                supersedes: row.get::<Option<String>>(11).unwrap_or(None),
                last_modified: row.get::<i64>(12).unwrap_or(0),
                chunk_count: row.get::<u64>(13).unwrap_or(0),
                entity_id: row.get::<Option<String>>(14).unwrap_or(None),
                quality: row.get::<Option<String>>(15).unwrap_or(None),
                is_recap: row.get::<i64>(16).unwrap_or(0) != 0,
                enrichment_status: row.get::<String>(17).unwrap_or_else(|_| "raw".to_string()),
                supersede_mode: row.get::<String>(18).unwrap_or_else(|_| "hide".to_string()),
                structured_fields: row.get::<Option<String>>(19).unwrap_or(None),
                retrieval_cue: row.get::<Option<String>>(20).unwrap_or(None),
                access_count: row.get::<u64>(21).unwrap_or(0),
                source_text: row.get::<Option<String>>(22).unwrap_or(None),
                version: row.get::<i64>(23).unwrap_or(1),
                changelog: row.get::<Option<String>>(24).unwrap_or(None),
                pending_revision: false,
                merged_from: None,
            });
        }
        Ok(items)
    }

    /// Load decision memories for the timeline view.
    /// Filters to `source = 'memory' AND memory_type = 'decision' AND chunk_index = 0`.
    /// Returns full `MemoryItem` rows with `structured_fields` for expanded view.
    pub async fn load_decisions(
        &self,
        space: Option<&str>,
        limit: usize,
    ) -> Result<Vec<MemoryItem>, WenlanError> {
        let conn = self.conn.lock().await;
        let supersedes_exclusion = "AND pending_revision = 0 AND source_id NOT IN (SELECT supersedes FROM memories WHERE supersedes IS NOT NULL AND pending_revision = 0 AND source = 'memory' GROUP BY supersedes)";

        let space_clause = if space.is_some() {
            "AND space = ?2"
        } else {
            ""
        };

        let sql = format!(
            "SELECT source_id, MAX(title) as title,
                    GROUP_CONCAT(content, '\n') as content,
                    MAX(summary) as summary,
                    MAX(memory_type) as memory_type,
                    MAX(space) as space,
                    MAX(source_agent) as source_agent,
                    MAX(confidence) as confidence,
                    MAX(confirmed) as confirmed,
                    MAX(stability) as stability,
                    MAX(pinned) as pinned,
                    MAX(supersedes) as supersedes,
                    MAX(last_modified) as last_modified,
                    COUNT(*) as chunk_count,
                    MAX(entity_id) as entity_id,
                    MAX(quality) as quality,
                    MAX(is_recap) as is_recap,
                    (SELECT CASE
                        WHEN COUNT(es.source_id) = 0 THEN 'raw'
                        WHEN SUM(CASE WHEN es.status = 'failed' OR es.status = 'abandoned' THEN 1 ELSE 0 END) = 0 THEN 'enriched'
                        WHEN SUM(CASE WHEN es.status IN ('ok','skipped') THEN 1 ELSE 0 END) = 0 THEN 'enrichment_failed'
                        ELSE 'enrichment_partial'
                    END FROM enrichment_steps es WHERE es.source_id = memories.source_id) AS enrichment_status,
                    MAX(supersede_mode) as supersede_mode,
                    MAX(structured_fields) as structured_fields,
                    MAX(retrieval_cue) as retrieval_cue,
                    SUM(access_count) as access_count,
                    MAX(source_text) as source_text,
                    MAX(version) as version,
                    MAX(changelog) as changelog
             FROM memories
             WHERE source = 'memory' AND memory_type = 'decision' AND chunk_index = 0 AND confirmed != 0
             {} {}
             GROUP BY source_id
             ORDER BY last_modified DESC
             LIMIT ?1",
            supersedes_exclusion, space_clause
        );

        let mut rows = if let Some(d) = space {
            conn.query(&sql, libsql::params![limit as i64, d.to_string()])
                .await
        } else {
            conn.query(&sql, libsql::params![limit as i64]).await
        }
        .map_err(|e| WenlanError::VectorDb(format!("load_decisions: {}", e)))?;

        let mut items = Vec::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            items.push(MemoryItem {
                source_id: row.get::<String>(0).unwrap_or_default(),
                title: row.get::<String>(1).unwrap_or_default(),
                content: row.get::<String>(2).unwrap_or_default(),
                summary: row.get::<Option<String>>(3).unwrap_or(None),
                memory_type: row.get::<Option<String>>(4).unwrap_or(None),
                space: row.get::<Option<String>>(5).unwrap_or(None),
                source_agent: row.get::<Option<String>>(6).unwrap_or(None),
                confidence: row.get::<Option<f64>>(7).unwrap_or(None).map(|v| v as f32),
                confirmed: row.get::<i64>(8).unwrap_or(0) != 0,
                stability: row.get::<Option<String>>(9).unwrap_or(None),
                pinned: row.get::<i64>(10).unwrap_or(0) != 0,
                supersedes: row.get::<Option<String>>(11).unwrap_or(None),
                last_modified: row.get::<i64>(12).unwrap_or(0),
                chunk_count: row.get::<u64>(13).unwrap_or(0),
                entity_id: row.get::<Option<String>>(14).unwrap_or(None),
                quality: row.get::<Option<String>>(15).unwrap_or(None),
                is_recap: row.get::<i64>(16).unwrap_or(0) != 0,
                enrichment_status: row.get::<String>(17).unwrap_or_else(|_| "raw".to_string()),
                supersede_mode: row.get::<String>(18).unwrap_or_else(|_| "hide".to_string()),
                structured_fields: row.get::<Option<String>>(19).unwrap_or(None),
                retrieval_cue: row.get::<Option<String>>(20).unwrap_or(None),
                access_count: row.get::<u64>(21).unwrap_or(0),
                source_text: row.get::<Option<String>>(22).unwrap_or(None),
                version: row.get::<i64>(23).unwrap_or(1),
                changelog: row.get::<Option<String>>(24).unwrap_or(None),
                pending_revision: false,
                merged_from: None,
            });
        }
        Ok(items)
    }

    /// List distinct spaces that have decision memories.
    pub async fn list_decision_spaces(&self) -> Result<Vec<String>, WenlanError> {
        let conn = self.conn.lock().await;
        let sql = "SELECT DISTINCT space FROM memories WHERE source = 'memory' AND memory_type = 'decision' AND space IS NOT NULL ORDER BY space";
        let mut rows = conn
            .query(sql, libsql::params![])
            .await
            .map_err(|e| WenlanError::VectorDb(format!("list_decision_spaces: {}", e)))?;

        let mut spaces = Vec::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            if let Ok(d) = row.get::<String>(0) {
                spaces.push(d);
            }
        }
        Ok(spaces)
    }

    /// List documents matching structured filters, deduped by source_id.
    /// All filter values are passed as parameterized queries to prevent SQL injection.
    pub async fn list_filtered(
        &self,
        source: Option<&str>,
        memory_type: Option<&str>,
        space: Option<&str>,
        limit: usize,
    ) -> Result<Vec<IndexedFileInfo>, WenlanError> {
        self.list_filtered_confirmed(source, memory_type, space, None, limit)
            .await
    }

    pub async fn list_filtered_scoped(
        &self,
        source: Option<&str>,
        memory_type: Option<&str>,
        scope: &ReadScope,
        limit: usize,
    ) -> Result<Vec<IndexedFileInfo>, WenlanError> {
        self.list_filtered_confirmed_scoped(source, memory_type, scope, None, limit)
            .await
    }

    /// Like `list_filtered` but with an optional `confirmed` predicate.
    pub async fn list_filtered_confirmed(
        &self,
        source: Option<&str>,
        memory_type: Option<&str>,
        space: Option<&str>,
        confirmed: Option<bool>,
        limit: usize,
    ) -> Result<Vec<IndexedFileInfo>, WenlanError> {
        let scope = legacy_read_scope(space);
        self.list_filtered_confirmed_scoped(source, memory_type, &scope, confirmed, limit)
            .await
    }

    pub async fn list_filtered_confirmed_scoped(
        &self,
        source: Option<&str>,
        memory_type: Option<&str>,
        scope: &ReadScope,
        confirmed: Option<bool>,
        limit: usize,
    ) -> Result<Vec<IndexedFileInfo>, WenlanError> {
        let conn = self.conn.lock().await;

        let mut conditions = Vec::new();
        let mut params: Vec<libsql::Value> = Vec::new();
        let mut idx = 1;

        if let Some(s) = source {
            conditions.push(format!("source = ?{}", idx));
            params.push(s.to_string().into());
            idx += 1;
        }
        if let Some(mt) = memory_type {
            conditions.push(format!("memory_type = ?{}", idx));
            params.push(mt.to_string().into());
            idx += 1;
        }
        match scope {
            ReadScope::Global => {}
            ReadScope::Space(space) => {
                conditions.push(format!("space = ?{}", idx));
                params.push(space.clone().into());
                idx += 1;
            }
            ReadScope::Uncategorized => conditions.push(
                "(space IS NULL OR space = '00000000-0000-4000-8000-000000000001')".to_string(),
            ),
        }
        if let Some(c) = confirmed {
            if c {
                conditions.push(format!("confirmed = ?{}", idx));
                params.push(1i64.into());
                idx += 1;
            } else {
                // NULL means "not yet confirmed" — include both explicit 0 and NULL.
                // Also exclude archived supersedes and recap rows to match the
                // same set returned by list_unconfirmed_memories.
                conditions.push("(confirmed = 0 OR confirmed IS NULL)".to_string());
                conditions.push(
                    "(supersede_mode IS NULL OR supersede_mode NOT IN ('archive', 'evicted'))"
                        .to_string(),
                );
                conditions.push("(is_recap IS NULL OR is_recap != 1)".to_string());
            }
        }

        // Exclude superseded memories and pending revisions
        conditions.push("pending_revision = 0".to_string());
        // T2: never list verbatim episode rows in the filtered file view.
        conditions.push("source != 'episode'".to_string());
        conditions.push(superseder_not_exists(
            scope,
            "memories",
            "superseder.pending_revision = 0 AND superseder.source = 'memory'",
        ));

        let where_clause = if conditions.is_empty() {
            String::new()
        } else {
            format!("WHERE {}", conditions.join(" AND "))
        };

        params.push((limit as i64).into());
        let limit_param = idx;

        let sql = format!(
            "SELECT source_id, MAX(title) as title, MAX(source) as source,
                    MAX(url) as url, COUNT(*) as chunk_count,
                    MAX(last_modified) as last_modified, MAX(summary) as summary,
                    MAX(memory_type), MAX(space), MAX(source_agent),
                    MAX(CAST(confidence AS REAL)), MAX(confirmed), MAX(pinned),
                    MAX(created_at) as created_at,
                    MAX(content) as content
             FROM memories
             {}
             GROUP BY source_id
             ORDER BY MAX(last_modified) DESC
             LIMIT ?{}",
            where_clause, limit_param
        );

        let mut rows = conn
            .query(&sql, libsql::params_from_iter(params))
            .await
            .map_err(|e| WenlanError::VectorDb(format!("list_filtered: {}", e)))?;

        let mut results = Vec::new();
        while let Ok(Some(row)) = rows.next().await {
            results.push(IndexedFileInfo {
                source_id: row.get::<String>(0).unwrap_or_default(),
                title: row.get::<String>(1).unwrap_or_default(),
                source: row.get::<String>(2).unwrap_or_default(),
                url: row.get::<Option<String>>(3).unwrap_or(None),
                chunk_count: row.get::<i64>(4).unwrap_or(0) as u64,
                last_modified: row.get::<i64>(5).unwrap_or(0),
                summary: row.get::<Option<String>>(6).unwrap_or(None),
                processing: false,
                memory_type: row.get::<Option<String>>(7).unwrap_or(None),
                space: row.get::<Option<String>>(8).unwrap_or(None),
                source_agent: row.get::<Option<String>>(9).unwrap_or(None),
                confidence: row.get::<Option<f64>>(10).unwrap_or(None).map(|v| v as f32),
                confirmed: row.get::<Option<i64>>(11).unwrap_or(None).map(|v| v != 0),
                stability: None, // not fetched in list_filtered aggregate query
                pinned: row.get::<i64>(12).unwrap_or(0) != 0,
                created_at: row.get::<Option<i64>>(13).unwrap_or(None).unwrap_or(0),
                content: row
                    .get::<Option<String>>(14)
                    .unwrap_or(None)
                    .unwrap_or_default(),
            });
        }

        Ok(results)
    }

    // ===== Knowledge Graph Methods =====

    /// Create a new entity in the knowledge graph (simplified — no embedding, no source_agent/confidence).
    pub async fn create_entity(
        &self,
        name: &str,
        entity_type: &str,
        space: Option<&str>,
    ) -> Result<String, WenlanError> {
        let id = uuid::Uuid::new_v4().to_string();
        let now = chrono::Utc::now().timestamp();

        let conn = self.conn.lock().await;
        conn.execute(
            "INSERT INTO entities (id, name, entity_type, space, confirmed, created_at, updated_at)
             VALUES (?1, ?2, ?3, ?4, 0, ?5, ?5)",
            libsql::params![
                id.clone(),
                name.to_string(),
                entity_type.to_string(),
                space.map(|d| d.to_string()),
                now
            ],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("create_entity: {}", e)))?;

        Ok(id)
    }

    /// Store a new entity in the knowledge graph. Also dual-writes its
    /// `kind='entity'` page shadow (M3 PR-1 stage f) + `entity_page_map` row
    /// via `insert_entity_shadow_page`, all inside one transaction, so the
    /// entity and its shadow page can never diverge -- a failed shadow write
    /// rolls back the entity write, and vice versa.
    pub async fn store_entity(
        &self,
        name: &str,
        entity_type: &str,
        space: Option<&str>,
        source_agent: Option<&str>,
        confidence: Option<f32>,
    ) -> Result<String, WenlanError> {
        let id = uuid::Uuid::new_v4().to_string();
        let now = chrono::Utc::now().timestamp();
        let now_iso = chrono::Utc::now().to_rfc3339();

        let embedding = self.get_or_compute_embedding(name)?;
        let vec_str = Self::vec_to_sql(&embedding);

        let conn = self.conn.lock().await;
        conn.execute("BEGIN", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("store_entity begin: {}", e)))?;

        let result: Result<(), WenlanError> = async {
            conn.execute(
                "INSERT INTO entities (id, name, entity_type, space, source_agent, confidence,
                    confirmed, created_at, updated_at, embedding)
                 VALUES (?1, ?2, ?3, ?4, ?5, ?6, 0, ?7, ?7, vector32(?8))",
                libsql::params![
                    id.clone(),
                    name.to_string(),
                    entity_type.to_string(),
                    space
                        .map(|s| libsql::Value::Text(s.to_string()))
                        .unwrap_or(libsql::Value::Null),
                    source_agent
                        .map(|s| libsql::Value::Text(s.to_string()))
                        .unwrap_or(libsql::Value::Null),
                    confidence
                        .map(|v| libsql::Value::Real(v as f64))
                        .unwrap_or(libsql::Value::Null),
                    now,
                    vec_str
                ],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("store_entity: {}", e)))?;

            // Auto-create a self-alias for the entity name (lowercase).
            conn.execute(
                "INSERT OR IGNORE INTO entity_aliases (alias_name, canonical_entity_id, created_at, source) VALUES (?1, ?2, unixepoch(), 'auto')",
                libsql::params![name.to_lowercase(), id.clone()],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("store_entity alias: {}", e)))?;

            let page_id = crate::pages::new_page_id();
            Self::insert_entity_shadow_page(&conn, &id, &page_id, &now_iso).await?;
            // The insert path leaves `aliases` NULL (it is shared with
            // migration 92, which predates the `pages.aliases` column); the
            // self-alias inserted just above is now visible, so re-sync the
            // shadow to fold it in. Same transaction -> the shadow never
            // observes a NULL-aliases state.
            Self::update_entity_shadow_page(&conn, &id, &now_iso).await?;

            Ok(())
        }
        .await;

        match result {
            Ok(()) => {
                conn.execute("COMMIT", ())
                    .await
                    .map_err(|e| WenlanError::VectorDb(format!("store_entity commit: {}", e)))?;
            }
            Err(e) => {
                let _ = conn.execute("ROLLBACK", ()).await;
                return Err(e);
            }
        }

        Ok(id)
    }

    /// The canonical resolve-then-write cascade (M3 PR-1 stage d, spec's "one
    /// canonical entity-upsert service" gate): exact-name -> minhash ->
    /// vector-sim -> `store_entity`. Both `post_write::create_entity` (the
    /// agent/MCP/HTTP path) and `importer::resolve_entity_bulk` (the
    /// bulk-import path) delegate their resolution to this one function
    /// instead of each re-implementing it -- previously the two cascades were
    /// "kept hand-in-sync by comment" (a real divergence risk); collapsing
    /// them here removes that risk by construction. Returns
    /// `(entity_id, was_newly_created)`. Callers keep their own
    /// caller-specific concerns on top: `resolve_entity_bulk` layers its
    /// in-batch cache, `create_entity` layers input validation, its richer
    /// `WriteResult` wrapping, and post-write enrichment (verify, refinery
    /// enqueue, activity log) gated on `was_newly_created`.
    pub async fn resolve_or_create_entity(
        &self,
        name: &str,
        entity_type: &str,
        space: Option<&str>,
        source_agent: Option<&str>,
        confidence: Option<f32>,
    ) -> Result<(String, bool), WenlanError> {
        let _resolution_guard = self.entity_resolution_lock.lock().await;
        let name_lower = name.to_lowercase();

        // Step 1: alias lookup (exact, case-insensitive).
        if let Some(id) = self.resolve_entity_by_alias(&name_lower).await? {
            return Ok((id, false));
        }

        // Step 2: exact name search.
        if let Some(existing) = self.search_entities_by_name(name).await?.into_iter().next() {
            let _ = self
                .add_entity_alias(&name_lower, &existing.id, "auto")
                .await;
            return Ok((existing.id, false));
        }

        // Step 2.5: deterministic MinHash/LSH near-dedup (T16, opt-in).
        if crate::db::entity_minhash_enabled() {
            if let Some(cand_id) = self.minhash_resolve_candidate(name, entity_type).await? {
                let _ = self
                    .add_entity_alias(&name_lower, &cand_id, "minhash")
                    .await;
                return Ok((cand_id, false));
            }
        }

        // Step 3: vector similarity (distance < 0.1 => sim > 0.9).
        if let Some(result) = self
            .search_entities_by_vector(name, 1)
            .await?
            .into_iter()
            .next()
        {
            if result.distance < 0.1 {
                let _ = self
                    .add_entity_alias(&name_lower, &result.entity.id, "auto")
                    .await;
                return Ok((result.entity.id, false));
            }
        }

        // Step 4: create new.
        let id = self
            .store_entity(name, entity_type, space, source_agent, confidence)
            .await?;
        if crate::db::entity_minhash_enabled() {
            if let Err(e) = self.index_entity_minhash_if_eligible(&id, name).await {
                log::warn!("[resolve_or_create_entity] minhash band index failed for {id}: {e}");
            }
        }
        Ok((id, true))
    }

    /// Persist the LSH band keys for an entity into `entity_minhash_bands`
    /// (T16). Only high-entropy names are indexed (gated by the caller) so the
    /// table stays small. `INSERT OR IGNORE` keeps the call idempotent; the
    /// whole batch runs inside one BEGIN/COMMIT (batch-SQL rule).
    pub async fn store_entity_minhash_bands(
        &self,
        entity_id: &str,
        band_keys: &[u64],
    ) -> Result<(), WenlanError> {
        if band_keys.is_empty() {
            return Ok(());
        }
        let conn = self.conn.lock().await;
        conn.execute("BEGIN TRANSACTION", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("store_minhash begin: {e}")))?;
        let result: Result<(), WenlanError> = async {
            for &key in band_keys {
                // libSQL INTEGER is i64; band keys are u64 LSH hashes. Reinterpret
                // the bit pattern (i64::from_ne_bytes) so the round-trip is exact;
                // query_entities_by_band applies the inverse on the way out.
                let signed = key as i64;
                conn.execute(
                    "INSERT OR IGNORE INTO entity_minhash_bands (band_key, entity_id) VALUES (?1, ?2)",
                    libsql::params![signed, entity_id.to_string()],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("store_minhash insert: {e}")))?;
            }
            Ok(())
        }
        .await;
        match result {
            Ok(()) => {
                conn.execute("COMMIT", ())
                    .await
                    .map_err(|e| WenlanError::VectorDb(format!("store_minhash commit: {e}")))?;
                Ok(())
            }
            Err(e) => {
                if let Err(rb) = conn.execute("ROLLBACK", ()).await {
                    log::error!("store_entity_minhash_bands ROLLBACK failed: {rb}");
                }
                Err(e)
            }
        }
    }

    /// Return the distinct entity ids that share at least one of `band_keys`
    /// in `entity_minhash_bands` (T16 LSH candidate lookup). Placeholders are
    /// parameterized -- band keys are never interpolated into the SQL string.
    pub async fn query_entities_by_band(
        &self,
        band_keys: &[u64],
    ) -> Result<Vec<String>, WenlanError> {
        if band_keys.is_empty() {
            return Ok(Vec::new());
        }
        let placeholders = (1..=band_keys.len())
            .map(|i| format!("?{i}"))
            .collect::<Vec<_>>()
            .join(", ");
        let sql = format!(
            "SELECT DISTINCT entity_id FROM entity_minhash_bands WHERE band_key IN ({placeholders})"
        );
        let params: Vec<libsql::Value> = band_keys
            .iter()
            .map(|&k| libsql::Value::Integer(k as i64))
            .collect();
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(&sql, libsql::params_from_iter(params))
            .await
            .map_err(|e| WenlanError::VectorDb(format!("query_minhash: {e}")))?;
        let mut ids = Vec::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(format!("query_minhash row: {e}")))?
        {
            if let Ok(id) = row.get::<String>(0) {
                ids.push(id);
            }
        }
        Ok(ids)
    }

    /// Remove all band rows for an entity (explicit cleanup on merge-loser
    /// delete; complements the ON DELETE CASCADE FK in case it is not honored).
    pub async fn delete_entity_minhash_bands(&self, entity_id: &str) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;
        conn.execute(
            "DELETE FROM entity_minhash_bands WHERE entity_id = ?1",
            libsql::params![entity_id.to_string()],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("delete_minhash: {e}")))?;
        Ok(())
    }

    /// Lightweight `(name, entity_type)` fetch for a single entity id. Used by
    /// the T16 MinHash cascade to apply the same-type guard on band candidates
    /// without loading the full `EntityDetail` (observations etc.). Returns
    /// `None` if the id does not exist.
    pub async fn get_entity_name_type(
        &self,
        entity_id: &str,
    ) -> Result<Option<(String, String)>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT name, entity_type FROM entities WHERE id = ?1",
                libsql::params![entity_id.to_string()],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_entity_name_type: {e}")))?;
        if let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_entity_name_type row: {e}")))?
        {
            let name: String = row.get(0).unwrap_or_default();
            let etype: String = row.get(1).unwrap_or_default();
            Ok(Some((name, etype)))
        } else {
            Ok(None)
        }
    }

    /// T16 "Step 2.5": deterministic MinHash/LSH near-dedup resolution.
    ///
    /// SHARED by `post_write::create_entity` and `importer::resolve_entity_bulk`
    /// so the agent and bulk paths can never diverge (Risk #4). Caller must have
    /// already checked `entity_minhash_enabled()`. Returns `Some(existing_id)`
    /// when a same-type band candidate confirms at exact Jaccard >= 0.9 (the
    /// caller then records a "minhash" alias and resolves to that id); `None`
    /// when the name is low-entropy/short or no candidate confirms (caller falls
    /// through to the vector step).
    pub async fn minhash_resolve_candidate(
        &self,
        name: &str,
        entity_type: &str,
    ) -> Result<Option<String>, WenlanError> {
        use crate::retrieval::dedup;
        // Entropy gate: short/low-entropy names (3-char acronyms) are punted to
        // the vector step so the fuzzy layer never over-merges distinct names.
        if !dedup::has_high_entropy(name) {
            return Ok(None);
        }
        let bands = dedup::name_band_keys(name);
        let candidates = self.query_entities_by_band(&bands).await?;
        for cand_id in candidates {
            let Some((cand_name, cand_type)) = self.get_entity_name_type(&cand_id).await? else {
                continue;
            };
            // Same-type guard: never auto-merge across entity types.
            if !cand_type.eq_ignore_ascii_case(entity_type) {
                continue;
            }
            if dedup::name_jaccard(name, &cand_name) >= dedup::FUZZY_JACCARD_THRESHOLD {
                return Ok(Some(cand_id));
            }
        }
        Ok(None)
    }

    /// Index a newly created entity's band keys IFF it is high-entropy (T16).
    /// Keeps `entity_minhash_bands` small by skipping short/low-entropy names.
    /// Best-effort: caller has already checked `entity_minhash_enabled()`.
    pub async fn index_entity_minhash_if_eligible(
        &self,
        entity_id: &str,
        name: &str,
    ) -> Result<(), WenlanError> {
        use crate::retrieval::dedup;
        if !dedup::has_high_entropy(name) {
            return Ok(());
        }
        let bands = dedup::name_band_keys(name);
        self.store_entity_minhash_bands(entity_id, &bands).await
    }

    /// Resolve an entity ID from an alias (case-insensitive).
    pub async fn resolve_entity_by_alias(&self, name: &str) -> Result<Option<String>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT canonical_entity_id FROM entity_aliases WHERE alias_name = ?1",
                libsql::params![name.to_lowercase()],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("alias lookup: {}", e)))?;
        if let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(format!("alias row: {}", e)))?
        {
            Ok(Some(row.get::<String>(0).unwrap()))
        } else {
            Ok(None)
        }
    }

    /// Add an alias entry for an entity.
    pub async fn add_entity_alias(
        &self,
        alias: &str,
        entity_id: &str,
        source: &str,
    ) -> Result<(), WenlanError> {
        let now_iso = chrono::Utc::now().to_rfc3339();
        let conn = self.conn.lock().await;
        // Transaction so the alias insert and the shadow-page alias re-sync
        // (M3 PR-1 item C) commit atomically -- the shadow's `aliases` array
        // never lags the `entity_aliases` table.
        conn.execute("BEGIN", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("add alias begin: {}", e)))?;
        let result: Result<(), WenlanError> = async {
            conn.execute(
                "INSERT OR IGNORE INTO entity_aliases (alias_name, canonical_entity_id, created_at, source) VALUES (?1, ?2, unixepoch(), ?3)",
                libsql::params![alias.to_lowercase(), entity_id.to_string(), source.to_string()],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("add alias: {}", e)))?;
            Self::update_entity_shadow_page(&conn, entity_id, &now_iso).await?;
            Ok(())
        }
        .await;
        match result {
            Ok(()) => {
                conn.execute("COMMIT", ())
                    .await
                    .map_err(|e| WenlanError::VectorDb(format!("add alias commit: {}", e)))?;
                Ok(())
            }
            Err(e) => {
                let _ = conn.execute("ROLLBACK", ()).await;
                Err(e)
            }
        }
    }

    /// Resolve a relation type string against the vocabulary (case-insensitive).
    /// Returns `Some(canonical)` if the input matches a canonical or an alias,
    /// `None` if the input is not in the vocabulary.
    pub async fn resolve_relation_type(
        &self,
        relation_type: &str,
    ) -> Result<Option<String>, WenlanError> {
        let lower = relation_type.to_lowercase();
        let conn = self.conn.lock().await;

        // Check if input is already a canonical key (canonicals are lowercase).
        let mut rows = conn
            .query(
                "SELECT canonical FROM relation_type_vocabulary WHERE canonical = ?1",
                libsql::params![lower.clone()],
            )
            .await
            .map_err(|e| {
                WenlanError::VectorDb(format!("resolve_relation_type canonical: {}", e))
            })?;
        if rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(format!("resolve_relation_type row: {}", e)))?
            .is_some()
        {
            return Ok(Some(lower));
        }
        drop(rows);

        // Scan aliases JSON arrays for a case-insensitive match.
        let mut rows = conn
            .query(
                "SELECT canonical, aliases FROM relation_type_vocabulary WHERE aliases IS NOT NULL ORDER BY canonical",
                libsql::params![],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("resolve_relation_type aliases: {}", e)))?;
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(format!("resolve_relation_type alias row: {}", e)))?
        {
            let canonical = row.get::<String>(0).unwrap_or_default();
            let aliases_json = row.get::<String>(1).unwrap_or_default();
            if let Ok(serde_json::Value::Array(arr)) = serde_json::from_str(&aliases_json) {
                for v in &arr {
                    if let Some(alias) = v.as_str() {
                        if alias.to_lowercase() == lower {
                            return Ok(Some(canonical));
                        }
                    }
                }
            }
        }

        // Not found — not a vocabulary type.
        Ok(None)
    }

    /// All canonical relation types (lowercase), for safe-transform matching.
    pub async fn relation_canonicals(&self) -> Result<Vec<String>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT canonical FROM relation_type_vocabulary ORDER BY canonical",
                (),
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("relation_canonicals: {e}")))?;
        let mut out = Vec::new();
        while let Some(r) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            out.push(r.get::<String>(0).unwrap_or_default());
        }
        Ok(out)
    }

    /// Increment the usage count for a canonical relation type.
    pub async fn increment_relation_type_count(&self, canonical: &str) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;
        conn.execute(
            "UPDATE relation_type_vocabulary SET count = count + 1 WHERE canonical = ?1",
            libsql::params![canonical.to_string()],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("increment_relation_type_count: {}", e)))?;
        Ok(())
    }

    /// Resolve an entity type against the vocabulary. Canonical-first, then a
    /// deterministic ordered alias scan. Mirrors `resolve_relation_type`.
    pub async fn resolve_entity_type(
        &self,
        entity_type: &str,
    ) -> Result<Option<String>, WenlanError> {
        let lower = entity_type.to_lowercase();
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT canonical FROM entity_type_vocabulary WHERE canonical = ?1",
                libsql::params![lower.clone()],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("resolve_entity_type canonical: {e}")))?;
        if rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(format!("resolve_entity_type row: {e}")))?
            .is_some()
        {
            return Ok(Some(lower));
        }
        drop(rows);
        // Deterministic order so resolution can't flip between runs.
        let mut rows = conn
            .query(
                "SELECT canonical, aliases FROM entity_type_vocabulary WHERE aliases IS NOT NULL ORDER BY canonical",
                libsql::params![],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("resolve_entity_type aliases: {e}")))?;
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(format!("resolve_entity_type alias row: {e}")))?
        {
            let canonical = row.get::<String>(0).unwrap_or_default();
            let aliases_json = row.get::<String>(1).unwrap_or_default();
            if let Ok(serde_json::Value::Array(arr)) = serde_json::from_str(&aliases_json) {
                for v in &arr {
                    if v.as_str().map(|a| a.to_lowercase()) == Some(lower.clone()) {
                        return Ok(Some(canonical));
                    }
                }
            }
        }
        Ok(None)
    }

    /// Increment usage count for a canonical entity type.
    pub async fn increment_entity_type_count(&self, canonical: &str) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;
        conn.execute(
            "UPDATE entity_type_vocabulary SET count = count + 1 WHERE canonical = ?1",
            libsql::params![canonical.to_string()],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("increment_entity_type_count: {e}")))?;
        Ok(())
    }

    /// Search entities by exact name (case-insensitive).
    pub async fn search_entities_by_name(&self, name: &str) -> Result<Vec<Entity>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT id, name, entity_type, space, source_agent, confidence, confirmed, created_at, updated_at
                 FROM entities WHERE LOWER(name) = LOWER(?1)",
                libsql::params![name.to_string()],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("search_entities_by_name: {}", e)))?;

        let mut entities = Vec::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            entities.push(Entity {
                id: row.get::<String>(0).unwrap_or_default(),
                name: row.get::<String>(1).unwrap_or_default(),
                entity_type: row.get::<String>(2).unwrap_or_default(),
                space: row.get::<Option<String>>(3).unwrap_or(None),
                source_agent: row.get::<Option<String>>(4).unwrap_or(None),
                confidence: row.get::<Option<f64>>(5).unwrap_or(None).map(|v| v as f32),
                confirmed: row.get::<i64>(6).unwrap_or(0) != 0,
                created_at: row.get::<i64>(7).unwrap_or(0),
                updated_at: row.get::<i64>(8).unwrap_or(0),
            });
        }
        Ok(entities)
    }

    /// Refresh an entity's embedding by recomputing from the provided text.
    /// Also updates `embedding_updated_at` and `updated_at` timestamps.
    pub async fn refresh_entity_embedding(
        &self,
        entity_id: &str,
        text: &str,
    ) -> Result<(), WenlanError> {
        let embeddings = self.generate_embeddings(&[text.to_string()])?;
        if embeddings.is_empty() {
            return Err(WenlanError::VectorDb(
                "refresh_entity_embedding: empty embedding result".into(),
            ));
        }
        let vec_str = Self::vec_to_sql(&embeddings[0]);
        let now = chrono::Utc::now().timestamp();
        let now_iso = chrono::Utc::now().to_rfc3339();
        let conn = self.conn.lock().await;
        // Transaction so the entity embedding update and the shadow-page
        // re-sync (M3 PR-1 item C -- the shadow mirrors `embedding`) commit
        // atomically.
        conn.execute("BEGIN", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("refresh_entity_embedding begin: {}", e)))?;
        let result: Result<(), WenlanError> = async {
            conn.execute(
                "UPDATE entities SET embedding = vector32(?1), embedding_updated_at = ?2, updated_at = ?2 WHERE id = ?3",
                libsql::params![vec_str, now, entity_id.to_string()],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("refresh_entity_embedding: {}", e)))?;
            Self::update_entity_shadow_page(&conn, entity_id, &now_iso).await?;
            Ok(())
        }
        .await;
        match result {
            Ok(()) => {
                conn.execute("COMMIT", ()).await.map_err(|e| {
                    WenlanError::VectorDb(format!("refresh_entity_embedding commit: {}", e))
                })?;
                Ok(())
            }
            Err(e) => {
                let _ = conn.execute("ROLLBACK", ()).await;
                Err(e)
            }
        }
    }

    /// Add an observation to an entity.
    pub async fn add_observation(
        &self,
        entity_id: &str,
        content: &str,
        source_agent: Option<&str>,
        confidence: Option<f32>,
    ) -> Result<String, WenlanError> {
        let id = uuid::Uuid::new_v4().to_string();
        let now = chrono::Utc::now().timestamp();

        let conn = self.conn.lock().await;
        conn.execute(
            "INSERT INTO observations (id, entity_id, content, source_agent, confidence, confirmed, created_at)
             VALUES (?1, ?2, ?3, ?4, ?5, 0, ?6)",
            libsql::params![
                id.clone(),
                entity_id.to_string(),
                content.to_string(),
                source_agent.map(|s| libsql::Value::Text(s.to_string())).unwrap_or(libsql::Value::Null),
                confidence.map(|v| libsql::Value::Real(v as f64)).unwrap_or(libsql::Value::Null),
                now
            ],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("add_observation: {}", e)))?;

        // Update entity's updated_at
        conn.execute(
            "UPDATE entities SET updated_at = ?1 WHERE id = ?2",
            libsql::params![now, entity_id.to_string()],
        )
        .await
        .ok(); // Best effort

        Ok(id)
    }

    /// Merge `alias_id` into `canonical_id`. Re-points all FK references, registers
    /// the alias name, cleans dangling alias-table rows, and deletes the alias entity.
    /// Idempotent: returns `Ok(())` if `alias_id` is already gone.
    pub async fn merge_entities(
        &self,
        canonical_id: &str,
        alias_id: &str,
    ) -> Result<(), WenlanError> {
        if canonical_id == alias_id {
            return Err(WenlanError::Validation(
                "merge_entities: canonical and alias are the same id".into(),
            ));
        }

        let conn = self.conn.lock().await;
        // Idempotency check: assumes single-writer daemon (no other process holds
        // a libSQL connection to this DB). Mutex<Connection> serializes within-process;
        // cross-process races are not defended against.
        let alias_exists: i64 = {
            let mut rows = conn
                .query(
                    "SELECT COUNT(*) FROM entities WHERE id = ?1",
                    libsql::params![alias_id],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("merge_entities count alias: {e}")))?;
            let row = rows
                .next()
                .await
                .map_err(|e| WenlanError::VectorDb(format!("merge_entities row: {e}")))?
                .ok_or_else(|| WenlanError::VectorDb("merge_entities: no count row".into()))?;
            row.get(0).unwrap_or(0)
        };
        if alias_exists == 0 {
            return Ok(());
        }

        let canonical_exists: i64 = {
            let mut rows = conn
                .query(
                    "SELECT COUNT(*) FROM entities WHERE id = ?1",
                    libsql::params![canonical_id],
                )
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("merge_entities count canonical: {e}"))
                })?;
            let row = rows
                .next()
                .await
                .map_err(|e| WenlanError::VectorDb(format!("merge_entities row: {e}")))?
                .ok_or_else(|| WenlanError::VectorDb("merge_entities: no count row".into()))?;
            row.get(0).unwrap_or(0)
        };
        if canonical_exists == 0 {
            return Err(WenlanError::NotFound(format!(
                "canonical entity {canonical_id} not found"
            )));
        }

        let alias_name: Option<String> = {
            let mut rows = conn
                .query(
                    "SELECT name FROM entities WHERE id = ?1",
                    libsql::params![alias_id],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("merge_entities read name: {e}")))?;
            let row = rows
                .next()
                .await
                .map_err(|e| WenlanError::VectorDb(format!("merge_entities row: {e}")))?;
            row.and_then(|r| r.get::<String>(0).ok())
        };

        // T16 type-promotion inputs: read the alias (loser) type and the
        // canonical (winner) type BEFORE the transaction so the in-txn UPDATE
        // can promote a generic canonical to the loser's concrete type. Only
        // generic -> concrete is ever applied (never concrete -> different
        // concrete), so the winner's identity is preserved.
        let alias_type: String = {
            let mut rows = conn
                .query(
                    "SELECT entity_type FROM entities WHERE id = ?1",
                    libsql::params![alias_id],
                )
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("merge_entities read alias type: {e}"))
                })?;
            rows.next()
                .await
                .map_err(|e| WenlanError::VectorDb(format!("merge_entities row: {e}")))?
                .and_then(|r| r.get::<String>(0).ok())
                .unwrap_or_default()
        };
        let canonical_type: String = {
            let mut rows = conn
                .query(
                    "SELECT entity_type FROM entities WHERE id = ?1",
                    libsql::params![canonical_id],
                )
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("merge_entities read canonical type: {e}"))
                })?;
            rows.next()
                .await
                .map_err(|e| WenlanError::VectorDb(format!("merge_entities row: {e}")))?
                .and_then(|r| r.get::<String>(0).ok())
                .unwrap_or_default()
        };
        // Generic types eligible for promotion (case-insensitive). Promote only
        // when canonical is generic AND alias is concrete.
        let is_generic = |t: &str| {
            matches!(
                t.trim().to_ascii_lowercase().as_str(),
                "entity" | "unknown" | ""
            )
        };
        let should_promote = is_generic(&canonical_type) && !is_generic(&alias_type);
        let now_iso = chrono::Utc::now().to_rfc3339();

        // Snapshot the alias's active relation-edge shadows before endpoint
        // rewrite. The merge transaction below invalidates each old
        // content-addressed edge and reasserts the corrected endpoint edge;
        // grounded status and provenance survive the identity correction.
        let merge_edge_plans = {
            let mut relation_rows = conn
                .query(
                    "SELECT from_entity, to_entity, relation_type FROM relations \
                     WHERE from_entity = ?1 OR to_entity = ?1",
                    libsql::params![alias_id],
                )
                .await
                .map_err(|error| {
                    WenlanError::VectorDb(format!("merge_entities edge plan relations: {error}"))
                })?;
            let mut relations = Vec::new();
            while let Some(row) = relation_rows.next().await.map_err(|error| {
                WenlanError::VectorDb(format!("merge_entities edge plan relation row: {error}"))
            })? {
                relations.push((
                    row.get::<String>(0).unwrap_or_default(),
                    row.get::<String>(1).unwrap_or_default(),
                    row.get::<String>(2).unwrap_or_default(),
                ));
            }
            drop(relation_rows);

            let mut plans = Vec::new();
            for (old_src, old_dst, relation_type) in relations {
                let old_edge_id = crate::provenance::compute_edge_id(
                    "relates",
                    "entity",
                    &old_src,
                    "entity",
                    &old_dst,
                    &relation_type,
                );
                let mut edge_rows = conn
                    .query(
                        "SELECT grounded, valid_until, root_id, payload FROM edges \
                         WHERE edge_id = ?1",
                        libsql::params![old_edge_id.clone()],
                    )
                    .await
                    .map_err(|error| {
                        WenlanError::VectorDb(format!("merge_entities edge plan shadow: {error}"))
                    })?;
                let edge_state = edge_rows.next().await.map_err(|error| {
                    WenlanError::VectorDb(format!("merge_entities edge plan shadow row: {error}"))
                })?;
                let Some(edge_state) = edge_state else {
                    continue;
                };
                let grounded = edge_state.get::<i64>(0).unwrap_or(0) == 1;
                let valid_until = edge_state.get::<Option<i64>>(1).unwrap_or(None);
                let root_id = edge_state.get::<Option<String>>(2).unwrap_or(None);
                let payload = edge_state.get::<Option<String>>(3).unwrap_or(None);
                drop(edge_rows);
                if valid_until.is_some() {
                    continue;
                }

                let src_id = if old_src == alias_id {
                    canonical_id.to_owned()
                } else {
                    old_src
                };
                let dst_id = if old_dst == alias_id {
                    canonical_id.to_owned()
                } else {
                    old_dst
                };
                let mut space_rows = conn
                    .query(
                        "SELECT source.space, destination.space \
                         FROM entities source, entities destination \
                         WHERE source.id = ?1 AND destination.id = ?2",
                        libsql::params![src_id.clone(), dst_id.clone()],
                    )
                    .await
                    .map_err(|error| {
                        WenlanError::VectorDb(format!("merge_entities edge plan spaces: {error}"))
                    })?;
                let (src_space, dst_space) = match space_rows.next().await.map_err(|error| {
                    WenlanError::VectorDb(format!("merge_entities edge plan space row: {error}"))
                })? {
                    Some(row) => (
                        row.get::<Option<String>>(0).unwrap_or(None),
                        row.get::<Option<String>>(1).unwrap_or(None),
                    ),
                    None => (None, None),
                };
                drop(space_rows);
                let (lineage, space, cross_space_downgrade) =
                    match (src_space.as_ref(), dst_space.as_ref()) {
                        (Some(src_space), Some(dst_space)) if src_space == dst_space => {
                            ("assertion".to_owned(), src_space.clone(), false)
                        }
                        _ => (
                            "legacy".to_owned(),
                            src_space
                                .or(dst_space)
                                .unwrap_or_else(|| UNFILED_SPACE_ID.to_owned()),
                            true,
                        ),
                    };
                plans.push(EntityMergeEdgePlan {
                    old_edge_id,
                    src_id,
                    dst_id,
                    relation_type,
                    lineage,
                    space,
                    cross_space_downgrade,
                    grounded,
                    root_id,
                    payload,
                });
            }
            plans
        };

        conn.execute("BEGIN TRANSACTION", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("merge_entities begin: {e}")))?;

        let result: Result<Vec<CommunityGenerationUpdate>, WenlanError> = async {
            conn.execute(
                "UPDATE relations SET from_entity = ?1 WHERE from_entity = ?2",
                libsql::params![canonical_id, alias_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("merge_entities rel.from: {e}")))?;

            conn.execute(
                "UPDATE relations SET to_entity = ?1 WHERE to_entity = ?2",
                libsql::params![canonical_id, alias_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("merge_entities rel.to: {e}")))?;

            let mut graph_changes = Vec::new();
            for plan in &merge_edge_plans {
                if let Some(change) =
                    Self::dual_write_invalidate_edge(&conn, &plan.old_edge_id, None)
                        .await
                        .map_err(|error| {
                            WenlanError::VectorDb(format!(
                                "merge_entities invalidate old edge: {error}"
                            ))
                        })?
                {
                    graph_changes.push(change);
                }
                let (new_edge_id, reactivation_changes) = Self::dual_write_edge_with_payload(
                    &conn,
                    "relates",
                    "entity",
                    &plan.src_id,
                    "entity",
                    &plan.dst_id,
                    &plan.relation_type,
                    &plan.lineage,
                    &plan.space,
                    plan.cross_space_downgrade,
                    None,
                    plan.payload.as_deref(),
                )
                .await
                .map_err(|error| {
                    WenlanError::VectorDb(format!(
                        "merge_entities reassert corrected edge: {error}"
                    ))
                })?;
                graph_changes.extend(reactivation_changes);

                if plan.grounded {
                    let grounded_transition = conn
                        .execute(
                        "UPDATE edges SET grounded = 1, root_id = ?1, \
                            payload = COALESCE(payload, ?2) \
                         WHERE edge_id = ?3 AND valid_until IS NULL AND grounded = 0",
                        libsql::params![
                            plan.root_id.clone(),
                            plan.payload.clone(),
                            new_edge_id.clone()
                        ],
                    )
                    .await
                    .map_err(|error| {
                        WenlanError::VectorDb(format!(
                            "merge_entities preserve edge grounding: {error}"
                        ))
                    })?;
                    if grounded_transition == 0 {
                        conn.execute(
                            "UPDATE edges SET root_id = ?1, payload = COALESCE(payload, ?2) \
                             WHERE edge_id = ?3 AND valid_until IS NULL",
                            libsql::params![
                                plan.root_id.clone(),
                                plan.payload.clone(),
                                new_edge_id
                            ],
                        )
                        .await
                        .map_err(|error| {
                            WenlanError::VectorDb(format!(
                                "merge_entities preserve grounded edge metadata: {error}"
                            ))
                        })?;
                    } else if plan.lineage == "assertion" {
                        graph_changes.push(CommunityGraphChange {
                            space: plan.space.clone(),
                            src_id: plan.src_id.clone(),
                            dst_id: plan.dst_id.clone(),
                        });
                    }
                }
            }

            conn.execute(
                "UPDATE observations SET entity_id = ?1 WHERE entity_id = ?2",
                libsql::params![canonical_id, alias_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("merge_entities obs: {e}")))?;

            conn.execute(
                "UPDATE memories SET entity_id = ?1 WHERE entity_id = ?2",
                libsql::params![canonical_id, alias_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("merge_entities mem: {e}")))?;

            conn.execute(
                "INSERT OR IGNORE INTO memory_entities (memory_id, entity_id)
                 SELECT memory_id, ?1 FROM memory_entities WHERE entity_id = ?2",
                libsql::params![canonical_id, alias_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("merge_entities memory links: {e}")))?;

            conn.execute(
                "DELETE FROM memory_entities WHERE entity_id = ?1",
                libsql::params![alias_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("merge_entities old links: {e}")))?;

            conn.execute(
                "UPDATE pages SET entity_id = ?1 WHERE entity_id = ?2",
                libsql::params![canonical_id, alias_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("merge_entities pages: {e}")))?;

            conn.execute(
                "UPDATE OR IGNORE entity_aliases SET canonical_entity_id = ?1 WHERE canonical_entity_id = ?2",
                libsql::params![canonical_id, alias_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("merge_entities alias redirect: {e}")))?;

            if let Some(name) = &alias_name {
                conn.execute(
                    "INSERT OR IGNORE INTO entity_aliases (alias_name, canonical_entity_id, created_at, source) \
                     VALUES (?1, ?2, unixepoch(), 'merge')",
                    libsql::params![name.as_str(), canonical_id],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("merge_entities alias register: {e}")))?;
            }

            // T16 conservative type-promotion: generic canonical -> alias's
            // concrete type. The WHERE guard re-checks both conditions in SQL so
            // a concurrent write can't demote a concrete canonical. Never flips
            // between two concrete types.
            if should_promote {
                conn.execute(
                    "UPDATE entities SET entity_type = ?1 \
                     WHERE id = ?2 \
                       AND LOWER(entity_type) IN ('entity', 'unknown', '') \
                       AND LOWER(?1) NOT IN ('entity', 'unknown', '')",
                    libsql::params![alias_type.as_str(), canonical_id],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("merge_entities promote type: {e}")))?;
            }

            // T16 band cleanup for the loser (complements ON DELETE CASCADE).
            conn.execute(
                "DELETE FROM entity_minhash_bands WHERE entity_id = ?1",
                libsql::params![alias_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("merge_entities band cleanup: {e}")))?;

            conn.execute(
                "DELETE FROM entity_aliases WHERE canonical_entity_id = ?1",
                libsql::params![alias_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("merge_entities alias cleanup: {e}")))?;

            // M3 PR-1 item C (beyond Sol's enumerated list): the loser's shadow
            // page would otherwise be orphaned by the entity delete below (the
            // map row cascades on the entity FK, never the page). Delete it
            // first so its own ON DELETE CASCADE drops the map row.
            if let Some(loser_page_id) =
                entity_page_adapter::page_id_for_entity(&conn, alias_id).await?
            {
                conn.execute(
                    "DELETE FROM pages WHERE kind = 'entity' AND id = ?1",
                    libsql::params![loser_page_id],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("merge_entities loser shadow: {e}")))?;
            }

            conn.execute(
                "DELETE FROM entities WHERE id = ?1",
                libsql::params![alias_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("merge_entities delete alias: {e}")))?;

            // The canonical's shadowed fields drifted in this merge: aliases
            // were redirected + the loser's name registered, and its
            // entity_type may have been promoted. Re-sync the canonical shadow
            // to the final entity state (M3 PR-1 item C).
            Self::update_entity_shadow_page(&conn, canonical_id, &now_iso).await?;

            Self::bump_community_graph_generations(&conn, graph_changes)
                .await
                .map_err(|error| {
                    WenlanError::VectorDb(format!(
                        "merge_entities community generation: {error}"
                    ))
                })
        }
        .await;

        match result {
            Ok(generation_updates) => {
                conn.execute("COMMIT", ())
                    .await
                    .map_err(|e| WenlanError::VectorDb(format!("merge_entities commit: {e}")))?;
                self.record_community_dirty_nodes(generation_updates);
                Ok(())
            }
            Err(e) => {
                if let Err(rollback_err) = conn.execute("ROLLBACK", ()).await {
                    log::error!("merge_entities ROLLBACK failed: {rollback_err}");
                }
                Err(e)
            }
        }
    }

    /// Hard-delete the losing relation and return a JSON snapshot of the row
    /// for the caller to record in activity-log payload (soft-archive via log,
    /// not via schema column). `Ok(None)` when loser_id does not exist.
    /// `winner_id` is accepted for activity-log payload at the capability fn
    /// layer; existence not verified here.
    pub async fn supersede_relation(
        &self,
        loser_id: &str,
        winner_id: &str,
    ) -> Result<Option<serde_json::Value>, WenlanError> {
        if loser_id == winner_id {
            return Err(WenlanError::Validation(
                "supersede_relation: loser and winner are the same id".into(),
            ));
        }
        let conn = self.conn.lock().await;
        conn.execute("BEGIN", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("supersede_relation begin: {e}")))?;

        let exec = async {
            let mut rows = conn
                .query(
                    "SELECT id, from_entity, to_entity, relation_type, source_agent, \
                            confidence, explanation, source_memory_id, created_at \
                     FROM relations WHERE id = ?1",
                    libsql::params![loser_id],
                )
                .await?;

            let snapshot = rows.next().await?.map(|row| {
                serde_json::json!({
                    "id":               row.get::<String>(0).ok(),
                    "from_entity":      row.get::<String>(1).ok(),
                    "to_entity":        row.get::<String>(2).ok(),
                    "relation_type":    row.get::<String>(3).ok(),
                    "source_agent":     row.get::<String>(4).ok(),
                    "confidence":       row.get::<f64>(5).ok(),
                    "explanation":      row.get::<String>(6).ok(),
                    "source_memory_id": row.get::<String>(7).ok(),
                    "created_at":       row.get::<i64>(8).ok(),
                })
            });
            drop(rows);

            conn.execute(
                "DELETE FROM relations WHERE id = ?1",
                libsql::params![loser_id],
            )
            .await?;

            // Dual-write (M2 PR-1): soft-invalidate the corresponding edge
            // rather than hard-delete it (append-only-with-soft-supersession,
            // spec v3 §2). Same-id computation as the live create_relation
            // dual-write and the migration-81 relations backfill.
            let mut graph_changes = Vec::new();
            if let Some(snap) = &snapshot {
                if let (Some(fe), Some(te), Some(rt)) = (
                    snap["from_entity"].as_str(),
                    snap["to_entity"].as_str(),
                    snap["relation_type"].as_str(),
                ) {
                    let edge_id = crate::provenance::compute_edge_id(
                        "relates", "entity", fe, "entity", te, rt,
                    );
                    if let Some(change) =
                        Self::dual_write_invalidate_edge(&conn, &edge_id, None).await?
                    {
                        graph_changes.push(change);
                    }
                }
            }
            let generation_updates =
                Self::bump_community_graph_generations(&conn, graph_changes).await?;

            Ok::<_, libsql::Error>((snapshot, generation_updates))
        }
        .await;

        match exec {
            Ok((snapshot, generation_updates)) => {
                conn.execute("COMMIT", ()).await.map_err(|e| {
                    WenlanError::VectorDb(format!("supersede_relation commit: {e}"))
                })?;
                self.record_community_dirty_nodes(generation_updates);
                Ok(snapshot)
            }
            Err(e) => {
                let _ = conn.execute("ROLLBACK", ()).await;
                Err(WenlanError::VectorDb(format!("supersede_relation: {e}")))
            }
        }
    }

    /// Set `pending_revision = 1` on all chunks matching `source_id`. Idempotent
    /// (re-flag is no-op; the UPDATE matches the same row count). Returns NotFound
    /// when zero rows matched.
    pub async fn flag_memory_for_revision(&self, source_id: &str) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;
        let rows = conn
            .execute(
                "UPDATE memories SET pending_revision = 1 WHERE source_id = ?1",
                libsql::params![source_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("flag_memory_for_revision: {e}")))?;
        if rows == 0 {
            return Err(WenlanError::NotFound(format!(
                "memory {source_id} not found"
            )));
        }
        Ok(())
    }

    /// Create a relation between two entities.
    /// The relation type is normalized against the vocabulary via `resolve_relation_type`
    /// before insertion. On conflict (same from/to/type), updates confidence if higher
    /// and fills in explanation/source_memory_id if previously null.
    /// Returns the ID of the inserted or existing relation.
    #[allow(clippy::too_many_arguments)]
    pub async fn create_relation(
        &self,
        from_entity: &str,
        to_entity: &str,
        relation_type: &str,
        source_agent: Option<&str>,
        confidence: Option<f64>,
        explanation: Option<&str>,
        source_memory_id: Option<&str>,
    ) -> Result<String, WenlanError> {
        self.create_relation_with_span(
            from_entity,
            to_entity,
            relation_type,
            source_agent,
            confidence,
            explanation,
            source_memory_id,
            None,
            None,
            None,
            None,
        )
        .await
    }

    /// Like [`create_relation`], plus a verbatim source-memory `span_quote`
    /// (M3g Stage A capture, §2.3-§2.4 of `docs/plans/2026-07-25-m3g-promotion-mechanics.md`).
    /// `source_content` is the exact memory text the extractor saw, used
    /// ONLY to locate `span_quote`'s char offsets -- never re-fetched from
    /// the DB, since batch extraction can combine multiple memories'
    /// content and the caller must supply the exact string the model read.
    /// `model_version`/`prompt_version` record the extraction call's
    /// provenance (§6.6). When all four are `None` (the plain
    /// `create_relation` wrapper), no payload is written and the edge
    /// stays `payload=NULL`, identical to before M3g.
    #[allow(clippy::too_many_arguments)]
    pub async fn create_relation_with_span(
        &self,
        from_entity: &str,
        to_entity: &str,
        relation_type: &str,
        source_agent: Option<&str>,
        confidence: Option<f64>,
        explanation: Option<&str>,
        source_memory_id: Option<&str>,
        span_quote: Option<&str>,
        source_content: Option<&str>,
        model_version: Option<&str>,
        prompt_version: Option<&str>,
    ) -> Result<String, WenlanError> {
        // Normalize relation type against vocabulary.
        // NOTE: resolve_relation_type acquires the conn lock, so we must not hold it here.
        let canonical = match self.resolve_relation_type(relation_type).await? {
            Some(c) => c,
            None => {
                log::warn!(
                    "[create_relation] non-vocabulary type '{}' coerced to 'related_to' (queued as promote candidate)",
                    relation_type
                );
                // Capture-at-coercion: keep the review queue fed. Best-effort —
                // a failed insert must never fail ingest. resolve_relation_type
                // has released its lock; insert_vocab_promote_proposal takes its
                // own, and we have not locked self.conn yet.
                if let Err(e) = self
                    .insert_vocab_promote_proposal("relation", relation_type, None)
                    .await
                {
                    log::warn!(
                        "[create_relation] capture-at-coercion insert failed (ignored): {e}"
                    );
                }
                "related_to".to_string()
            }
        };

        let id = uuid::Uuid::new_v4().to_string();
        let now = chrono::Utc::now().timestamp();

        let conn = self.conn.lock().await;
        conn.execute("BEGIN", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("create_relation begin: {e}")))?;

        let exec = async {
            // Upsert: insert new or update existing if new confidence is higher.
            let affected = conn.execute(
                "INSERT INTO relations (id, from_entity, to_entity, relation_type, source_agent, confidence, explanation, source_memory_id, created_at)
                 VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)
                 ON CONFLICT(from_entity, to_entity, relation_type) DO UPDATE SET
                     confidence = CASE
                         WHEN EXCLUDED.confidence IS NOT NULL AND (confidence IS NULL OR EXCLUDED.confidence > confidence)
                         THEN EXCLUDED.confidence ELSE confidence END,
                     explanation = CASE
                         WHEN EXCLUDED.confidence IS NOT NULL AND (confidence IS NULL OR EXCLUDED.confidence > confidence)
                         THEN COALESCE(EXCLUDED.explanation, explanation) ELSE explanation END,
                     source_memory_id = COALESCE(source_memory_id, EXCLUDED.source_memory_id)",
                libsql::params![
                    id.clone(),
                    from_entity.to_string(),
                    to_entity.to_string(),
                    canonical.clone(),
                    source_agent.map(|s| libsql::Value::Text(s.to_string())).unwrap_or(libsql::Value::Null),
                    confidence.map(libsql::Value::Real).unwrap_or(libsql::Value::Null),
                    explanation.map(|s| libsql::Value::Text(s.to_string())).unwrap_or(libsql::Value::Null),
                    source_memory_id.map(|s| libsql::Value::Text(s.to_string())).unwrap_or(libsql::Value::Null),
                    now
                ],
            )
            .await?;

            if affected == 0 {
                return Ok::<
                    Option<(String, Vec<CommunityGenerationUpdate>)>,
                    libsql::Error,
                >(None);
            }

            // Check if this was an insert (the id we generated exists) vs an update.
            let mut rows = conn
                .query(
                    "SELECT id FROM relations WHERE from_entity = ?1 AND to_entity = ?2 AND relation_type = ?3",
                    libsql::params![from_entity.to_string(), to_entity.to_string(), canonical.clone()],
                )
                .await?;
            let existing_id = match rows.next().await? {
                Some(row) => row.get::<String>(0).unwrap_or(id.clone()),
                None => id.clone(),
            };
            drop(rows);

            // Dual-write (M2 PR-1): mirror `backfill_edges_from_relations`'s
            // classification exactly so a live-written edge and a backfilled
            // edge for the same fact converge on the same edge_id.
            let mut space_rows = conn
                .query(
                    "SELECT fe.space, te.space FROM entities fe, entities te WHERE fe.id = ?1 AND te.id = ?2",
                    libsql::params![from_entity.to_string(), to_entity.to_string()],
                )
                .await?;
            let (from_space, to_space): (Option<String>, Option<String>) =
                match space_rows.next().await? {
                    Some(row) => (row.get(0).unwrap_or(None), row.get(1).unwrap_or(None)),
                    None => (None, None),
                };
            drop(space_rows);
            // `relates` resolves two endpoints, not one destination, so it does
            // not go through `resolved_space_downgrades`: SAME-SPACE requires
            // both entity spaces present and equal; anything else (differing, or
            // either unresolved) is a cross-space/indeterminate downgrade. dst
            // is always `entity` (never fence-exempt external). Mirrors
            // `backfill_edges_from_relations`.
            let (lineage, space, cross_space_downgrade) = match (&from_space, &to_space) {
                (Some(fs), Some(ts)) if fs == ts => ("assertion", fs.clone(), false),
                _ => (
                    "legacy",
                    from_space
                        .or(to_space)
                        .unwrap_or_else(|| UNFILED_SPACE_ID.to_string()),
                    true,
                ),
            };
            // M3g Stage A span capture (§2.3/§2.4): CODE locates the
            // model-supplied quote as an exact char-offset substring of the
            // source memory's content -- never guessed. A payload is only
            // written when this call actually carries extraction-time data
            // (the plain `create_relation` wrapper passes all four as
            // `None`, so existing edges keep `payload=NULL`).
            let payload = if span_quote.is_some() || model_version.is_some() || prompt_version.is_some() {
                let span_json = span_quote.map(|quote| {
                    let offsets = source_content
                        .and_then(|content| crate::extract::locate_span_chars(content, quote));
                    serde_json::json!({
                        "quote": quote,
                        "char_start": offsets.map(|(start, _)| start),
                        "char_end": offsets.map(|(_, end)| end),
                    })
                });
                Some(
                    serde_json::json!({
                        "source_memory_id": source_memory_id,
                        "span": span_json,
                        "model_version": model_version,
                        "prompt_version": prompt_version,
                    })
                    .to_string(),
                )
            } else {
                None
            };

            let (_, graph_changes) = Self::dual_write_edge_with_payload(
                &conn,
                "relates",
                "entity",
                from_entity,
                "entity",
                to_entity,
                &canonical,
                lineage,
                &space,
                cross_space_downgrade,
                None,
                payload.as_deref(),
            )
            .await?;
            let generation_updates =
                Self::bump_community_graph_generations(&conn, graph_changes).await?;

            Ok(Some((existing_id, generation_updates)))
        }
        .await;

        match exec {
            Ok(Some((existing_id, generation_updates))) => {
                conn.execute("COMMIT", ())
                    .await
                    .map_err(|e| WenlanError::VectorDb(format!("create_relation commit: {e}")))?;
                self.record_community_dirty_nodes(generation_updates);
                drop(conn);
                // Only count new inserts (our generated id matches the stored id).
                if existing_id == id {
                    self.increment_relation_type_count(&canonical).await.ok();
                }
                Ok(existing_id)
            }
            Ok(None) => {
                conn.execute("COMMIT", ())
                    .await
                    .map_err(|e| WenlanError::VectorDb(format!("create_relation commit: {e}")))?;
                drop(conn);
                Ok(id)
            }
            Err(e) => {
                let _ = conn.execute("ROLLBACK", ()).await;
                Err(WenlanError::VectorDb(format!("create_relation: {e}")))
            }
        }
    }

    pub async fn list_relations_between(
        &self,
        from_entity: &str,
        to_entity: &str,
    ) -> Result<Vec<(String, String)>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT id, relation_type FROM relations WHERE from_entity = ?1 AND to_entity = ?2",
                libsql::params![from_entity.to_string(), to_entity.to_string()],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
        let mut result = Vec::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            result.push((
                row.get::<String>(0).unwrap_or_default(),
                row.get::<String>(1).unwrap_or_default(),
            ));
        }
        Ok(result)
    }

    pub async fn entity_exists(&self, entity_id: &str) -> Result<bool, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT 1 FROM entities WHERE id = ?1 LIMIT 1",
                libsql::params![entity_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
        Ok(rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .is_some())
    }

    pub async fn list_entities(
        &self,
        entity_type: Option<&str>,
        space: Option<&str>,
    ) -> Result<Vec<Entity>, WenlanError> {
        let conn = self.conn.lock().await;

        let mut sql = String::from(
            "SELECT id, name, entity_type, space, source_agent, confidence, confirmed, created_at, updated_at
             FROM entities WHERE 1=1"
        );
        let mut params: Vec<libsql::Value> = Vec::new();

        if let Some(et) = entity_type {
            params.push(et.into());
            sql.push_str(&format!(" AND entity_type = ?{}", params.len()));
        }
        if let Some(d) = space {
            if d == "uncategorized" {
                sql.push_str(" AND space IS NULL");
            } else {
                params.push(d.into());
                sql.push_str(&format!(" AND space = ?{}", params.len()));
            }
        }

        sql.push_str(" ORDER BY updated_at DESC");

        let mut rows = conn
            .query(&sql, libsql::params_from_iter(params))
            .await
            .map_err(|e| WenlanError::VectorDb(format!("list_entities: {}", e)))?;

        let mut entities = Vec::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            entities.push(Entity {
                id: row.get::<String>(0).unwrap_or_default(),
                name: row.get::<String>(1).unwrap_or_default(),
                entity_type: row.get::<String>(2).unwrap_or_default(),
                space: row.get::<Option<String>>(3).unwrap_or(None),
                source_agent: row.get::<Option<String>>(4).unwrap_or(None),
                confidence: row.get::<Option<f64>>(5).unwrap_or(None).map(|v| v as f32),
                confirmed: row.get::<i64>(6).unwrap_or(0) != 0,
                created_at: row.get::<i64>(7).unwrap_or(0),
                updated_at: row.get::<i64>(8).unwrap_or(0),
            });
        }
        Ok(entities)
    }

    pub async fn get_entity_detail(&self, entity_id: &str) -> Result<EntityDetail, WenlanError> {
        let conn = self.conn.lock().await;

        // Fetch entity
        let mut rows = conn
            .query(
                "SELECT id, name, entity_type, space, source_agent, confidence, confirmed, created_at, updated_at
                 FROM entities WHERE id = ?1",
                libsql::params![entity_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_entity: {}", e)))?;

        let entity = if let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            Entity {
                id: row.get::<String>(0).unwrap_or_default(),
                name: row.get::<String>(1).unwrap_or_default(),
                entity_type: row.get::<String>(2).unwrap_or_default(),
                space: row.get::<Option<String>>(3).unwrap_or(None),
                source_agent: row.get::<Option<String>>(4).unwrap_or(None),
                confidence: row.get::<Option<f64>>(5).unwrap_or(None).map(|v| v as f32),
                confirmed: row.get::<i64>(6).unwrap_or(0) != 0,
                created_at: row.get::<i64>(7).unwrap_or(0),
                updated_at: row.get::<i64>(8).unwrap_or(0),
            }
        } else {
            return Err(WenlanError::NotFound("entity not found".to_string()));
        };

        // Fetch observations
        let mut obs_rows = conn
            .query(
                "SELECT id, entity_id, content, source_agent, confidence, confirmed, created_at
                 FROM observations WHERE entity_id = ?1 ORDER BY created_at DESC",
                libsql::params![entity_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_observations: {}", e)))?;

        let mut observations = Vec::new();
        while let Some(row) = obs_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            observations.push(Observation {
                id: row.get::<String>(0).unwrap_or_default(),
                entity_id: row.get::<String>(1).unwrap_or_default(),
                content: row.get::<String>(2).unwrap_or_default(),
                source_agent: row.get::<Option<String>>(3).unwrap_or(None),
                confidence: row.get::<Option<f64>>(4).unwrap_or(None).map(|v| v as f32),
                confirmed: row.get::<i64>(5).unwrap_or(0) != 0,
                created_at: row.get::<i64>(6).unwrap_or(0),
            });
        }

        // Fetch relations (both directions) with entity names
        let mut rel_rows = conn
            .query(
                "SELECT r.id, r.relation_type, r.source_agent, r.created_at,
                        'outgoing' as direction, r.to_entity as entity_id,
                        e.name as entity_name, e.entity_type as entity_type
                 FROM relations r JOIN entities e ON e.id = r.to_entity
                 WHERE r.from_entity = ?1
                 UNION ALL
                 SELECT r.id, r.relation_type, r.source_agent, r.created_at,
                        'incoming' as direction, r.from_entity as entity_id,
                        e.name as entity_name, e.entity_type as entity_type
                 FROM relations r JOIN entities e ON e.id = r.from_entity
                 WHERE r.to_entity = ?1
                 ORDER BY 4 DESC",
                libsql::params![entity_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_relations: {}", e)))?;

        let mut relations = Vec::new();
        while let Some(row) = rel_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            relations.push(RelationWithEntity {
                id: row.get::<String>(0).unwrap_or_default(),
                relation_type: row.get::<String>(1).unwrap_or_default(),
                source_agent: row.get::<Option<String>>(2).unwrap_or(None),
                created_at: row.get::<i64>(3).unwrap_or(0),
                direction: row.get::<String>(4).unwrap_or_default(),
                entity_id: row.get::<String>(5).unwrap_or_default(),
                entity_name: row.get::<String>(6).unwrap_or_default(),
                entity_type: row.get::<String>(7).unwrap_or_default(),
            });
        }

        Ok(EntityDetail {
            entity,
            observations,
            relations,
        })
    }

    pub async fn update_observation(
        &self,
        observation_id: &str,
        content: &str,
    ) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;
        conn.execute(
            "UPDATE observations SET content = ?1 WHERE id = ?2",
            libsql::params![content, observation_id],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("update_observation: {}", e)))?;
        Ok(())
    }

    pub async fn delete_observation(&self, observation_id: &str) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;
        conn.execute(
            "DELETE FROM observations WHERE id = ?1",
            libsql::params![observation_id],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("delete_observation: {}", e)))?;
        Ok(())
    }

    pub async fn delete_entity(&self, entity_id: &str) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;
        conn.execute("BEGIN", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("delete_entity begin: {e}")))?;

        let result: Result<(), WenlanError> = async {
            conn.execute(
                "UPDATE memories SET entity_id = NULL WHERE entity_id = ?1",
                libsql::params![entity_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("delete_entity memories: {e}")))?;

            conn.execute(
                "UPDATE pages SET entity_id = NULL WHERE entity_id = ?1",
                libsql::params![entity_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("delete_entity pages: {e}")))?;

            conn.execute(
                "DELETE FROM entity_aliases WHERE canonical_entity_id = ?1",
                libsql::params![entity_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("delete_entity aliases: {e}")))?;

            // Delete the entity's shadow page (M3 PR-1 item C). The
            // `entity_page_map` row has an ON DELETE CASCADE FK to `pages`, so
            // deleting the shadow removes the map row too; the subsequent
            // `DELETE FROM entities` then finds no dangling map row. Without
            // this the shadow would be orphaned (the map's entity-side cascade
            // drops the map row on entity delete, but never the page itself).
            if let Some(shadow_page_id) =
                entity_page_adapter::page_id_for_entity(&conn, entity_id).await?
            {
                conn.execute(
                    "DELETE FROM pages WHERE kind = 'entity' AND id = ?1",
                    libsql::params![shadow_page_id],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("delete_entity shadow: {e}")))?;
            }

            conn.execute(
                "DELETE FROM entities WHERE id = ?1",
                libsql::params![entity_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("delete_entity entity: {e}")))?;

            Ok(())
        }
        .await;

        match result {
            Ok(()) => match conn.execute("COMMIT", ()).await {
                Ok(_) => Ok(()),
                Err(e) => {
                    let _ = conn.execute("ROLLBACK", ()).await;
                    Err(WenlanError::VectorDb(format!("delete_entity commit: {e}")))
                }
            },
            Err(e) => {
                let _ = conn.execute("ROLLBACK", ()).await;
                Err(e)
            }
        }
    }

    /// True if any non-archived memory carries the given space. Legacy data probe:
    /// registered spaces, not memory rows, define valid user-facing scopes.
    pub async fn space_has_memories(&self, space: &str) -> Result<bool, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT 1 FROM memories WHERE space = ?1 AND source != 'episode' LIMIT 1",
                libsql::params![space],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("space_has_memories: {}", e)))?;
        Ok(rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .is_some())
    }

    /// Resolve entity by name: exact match → LIKE substring → vector search → None.
    pub async fn resolve_entity_by_name(&self, name: &str) -> Result<Option<String>, WenlanError> {
        {
            let conn = self.conn.lock().await;
            // Step A: exact case-insensitive match
            let mut rows = conn
                .query(
                    "SELECT id FROM entities WHERE LOWER(name) = LOWER(?1) LIMIT 1",
                    libsql::params![name],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("resolve_entity exact: {}", e)))?;
            if let Ok(Some(row)) = rows.next().await {
                let id: String = row.get(0).unwrap();
                return Ok(Some(id));
            }
            // Step B: fuzzy LIKE substring match
            let mut rows = conn
                .query(
                    "SELECT id FROM entities WHERE name LIKE '%' || ?1 || '%' LIMIT 1",
                    libsql::params![name],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("resolve_entity fuzzy: {}", e)))?;
            if let Ok(Some(row)) = rows.next().await {
                let id: String = row.get(0).unwrap();
                return Ok(Some(id));
            }
        } // Drop conn lock before vector search (which acquires its own lock)
          // Step C: vector similarity match (cosine distance < 0.15 ≈ similarity > 0.85)
        if let Ok(hits) = self.search_entities_by_vector(name, 1).await {
            if let Some(hit) = hits.first() {
                if hit.distance < 0.15 {
                    return Ok(Some(hit.entity.id.clone()));
                }
            }
        }
        Ok(None)
    }

    /// Update a memory's entity_id (for post-ingest entity linking).
    pub async fn update_memory_entity_id(
        &self,
        source_id: &str,
        entity_id: &str,
    ) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;
        conn.execute(
            "UPDATE memories SET entity_id = ?1 WHERE source_id = ?2",
            libsql::params![entity_id, source_id],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("update_memory_entity_id: {}", e)))?;
        Ok(())
    }

    /// Write a row to `memory_entities` for each entity in `entity_ids`.
    ///
    /// Idempotent: `ON CONFLICT DO NOTHING` silently skips duplicates.
    /// Transactional: inserts are wrapped in BEGIN/COMMIT.
    pub async fn link_memory_entities(
        &self,
        memory_source_id: &str,
        entity_ids: &[&str],
    ) -> Result<(), WenlanError> {
        if entity_ids.is_empty() {
            return Ok(());
        }
        let conn = self.conn.lock().await;
        conn.execute("BEGIN", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("link_memory_entities BEGIN: {e}")))?;
        for eid in entity_ids {
            conn.execute(
                "INSERT INTO memory_entities (memory_id, entity_id) VALUES (?1, ?2) ON CONFLICT DO NOTHING",
                libsql::params![memory_source_id, *eid],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("link_memory_entities INSERT: {e}")))?;
        }
        conn.execute("COMMIT", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("link_memory_entities COMMIT: {e}")))?;
        Ok(())
    }

    /// Compute the `memory_entities` degree distribution in one pass.
    pub async fn memory_entities_degree_stats(
        &self,
    ) -> Result<MemoryEntitiesDegreeStats, WenlanError> {
        let conn = self.conn.lock().await;
        // Per-entity degree (memories linked), sorted ascending for percentiles.
        let mut rows = conn
            .query(
                "SELECT COUNT(*) c FROM memory_entities GROUP BY entity_id ORDER BY c ASC",
                (),
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("degree_stats group: {e}")))?;
        let mut degs: Vec<i64> = Vec::new();
        while let Ok(Some(row)) = rows.next().await {
            degs.push(row.get::<i64>(0).unwrap_or(0));
        }
        let edges: i64 = degs.iter().sum();
        let distinct_entities = degs.len() as i64;
        let pct = |a: &[i64], p: f64| -> i64 {
            if a.is_empty() {
                0
            } else {
                a[((a.len() as f64 * p) as usize).min(a.len() - 1)]
            }
        };
        let memories_linked: i64 = conn
            .query("SELECT COUNT(DISTINCT memory_id) FROM memory_entities", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("degree_stats memcount: {e}")))?
            .next()
            .await
            .ok()
            .flatten()
            .and_then(|r| r.get::<i64>(0).ok())
            .unwrap_or(0);
        Ok(MemoryEntitiesDegreeStats {
            edges,
            distinct_entities,
            memories_linked,
            p50_memories_per_entity: pct(&degs, 0.5),
            p90_memories_per_entity: pct(&degs, 0.9),
            max_memories_per_entity: degs.last().copied().unwrap_or(0),
            entities_gt_20: degs.iter().filter(|&&d| d > 20).count() as i64,
            entities_gt_50: degs.iter().filter(|&&d| d > 50).count() as i64,
            entities_gt_100: degs.iter().filter(|&&d| d > 100).count() as i64,
        })
    }

    /// Fetch up to `limit` memories not yet in the `memory_entities` junction,
    /// IGNORING the legacy 1:1 `entity_id` column. Used by the graph-substrate
    /// gate harness: the seed's speaker pool already fills `entity_id` on ~all
    /// memories (2520/2531 in locomo_v1), so a production-style `entity_id IS
    /// NULL` filter would leave only the 11 stragglers. The gate must re-link
    /// FINE entities into the junction for EVERY memory to measure the true
    /// fine-entity degree distribution. (Production uses the separate
    /// `get_unlinked_memories`; this method is gate-only.)
    pub async fn unlinked_memories(
        &self,
        limit: usize,
    ) -> Result<Vec<(String, String)>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT source_id, content FROM memories \
                 WHERE source != 'episode' AND chunk_index = 0 \
                   AND source_id NOT IN (SELECT memory_id FROM memory_entities) \
                 ORDER BY source_id \
                 LIMIT ?1",
                libsql::params![limit as i64],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("unlinked_memories: {e}")))?;
        let mut out = Vec::new();
        while let Ok(Some(row)) = rows.next().await {
            let sid: String = row.get(0).unwrap_or_default();
            let content: String = row.get(1).unwrap_or_default();
            if !sid.is_empty() {
                out.push((sid, content));
            }
        }
        Ok(out)
    }

    /// Top-N entities by memory_entities degree, with their names. Eyeball aid.
    pub async fn top_memory_entity_hubs(
        &self,
        n: usize,
    ) -> Result<Vec<(i64, String)>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT me.entity_id, COUNT(*) c, COALESCE(e.name, me.entity_id) nm \
                 FROM memory_entities me LEFT JOIN entities e ON e.id = me.entity_id \
                 GROUP BY me.entity_id ORDER BY c DESC LIMIT ?1",
                libsql::params![n as i64],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("top_hubs: {e}")))?;
        let mut out = Vec::new();
        while let Ok(Some(row)) = rows.next().await {
            let c: i64 = row.get(1).unwrap_or(0);
            let nm: String = row.get(2).unwrap_or_default();
            out.push((c, nm));
        }
        Ok(out)
    }

    /// Maximum entity-extraction attempts before a poison row becomes terminal.
    const ENTITY_ENRICHMENT_MAX_ATTEMPTS: u32 = 3;

    /// Commit one parsed entity-extraction result as a single source-guarded
    /// transaction. The LLM parse is intentionally complete before this method
    /// runs; no KG row becomes visible unless the source is still current and
    /// non-pending when the receipt is written.
    async fn commit_entity_enrichment_at_version(
        &self,
        source_id: &str,
        expected_version: i64,
        kg_results: &[crate::extract::KgExtractionResult],
    ) -> Result<bool, WenlanError> {
        // Avoid CPU-heavy embedding/minhash preparation when inference already
        // returned after the source became stale. The transaction below still
        // repeats this guard because the source can change during preparation.
        {
            let conn = self.conn.lock().await;
            let mut rows = conn
                .query(
                    "SELECT 1 FROM memories
                     WHERE source_id = ?1 AND chunk_index = 0
                       AND version = ?2 AND COALESCE(pending_revision, 0) = 0
                       AND NOT EXISTS (
                           SELECT 1 FROM memories superseder
                           WHERE superseder.supersedes = memories.source_id
                             AND superseder.pending_revision = 0
                             AND superseder.source = 'memory'
                       )
                     LIMIT 1",
                    libsql::params![source_id, expected_version],
                )
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("entity enrichment preflight guard: {e}"))
                })?;
            if rows
                .next()
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("entity enrichment preflight row: {e}"))
                })?
                .is_none()
            {
                return Ok(false);
            }
        }

        let mut seen_names = HashSet::new();
        let mut entities = Vec::new();
        for kg in kg_results {
            for entity in &kg.entities {
                let name = entity.name.trim();
                let entity_type = entity.entity_type.trim();
                let lower = name.to_lowercase();
                if name.is_empty() || entity_type.is_empty() || !seen_names.insert(lower.clone()) {
                    continue;
                }
                entities.push((lower, name.to_string(), entity_type.to_string()));
            }
        }

        // Embedding is CPU work and must not hold the SQLite connection lock.
        // Batch it once for the selected memory instead of once per entity.
        let entity_names: Vec<String> = entities.iter().map(|(_, name, _)| name.clone()).collect();
        let embeddings = if entity_names.is_empty() {
            Vec::new()
        } else {
            self.generate_embeddings(&entity_names)?
        };
        if embeddings.len() != entity_names.len() {
            return Err(WenlanError::VectorDb(format!(
                "entity enrichment embedding count mismatch: expected {}, got {}",
                entity_names.len(),
                embeddings.len()
            )));
        }
        let minhash_enabled = entity_minhash_enabled();
        let mut prepared_entities = Vec::with_capacity(entities.len());
        for ((lower, name, entity_type), embedding) in entities.into_iter().zip(embeddings) {
            let minhash_candidate = if minhash_enabled {
                self.minhash_resolve_candidate(&name, &entity_type).await?
            } else {
                None
            };
            prepared_entities.push((
                lower,
                name,
                entity_type,
                Self::vec_to_sql(&embedding),
                minhash_candidate,
            ));
        }

        let now = chrono::Utc::now().timestamp();
        let conn = self.conn.lock().await;
        conn.execute("BEGIN", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("entity enrichment begin: {e}")))?;

        let mut created_entities: Vec<(String, String)> = Vec::new();
        let result: Result<bool, WenlanError> = async {
            let mut current_rows = conn
                .query(
                    "SELECT 1 FROM memories
                     WHERE source_id = ?1 AND chunk_index = 0
                       AND version = ?2 AND COALESCE(pending_revision, 0) = 0
                       AND NOT EXISTS (
                           SELECT 1 FROM memories superseder
                           WHERE superseder.supersedes = memories.source_id
                             AND superseder.pending_revision = 0
                             AND superseder.source = 'memory'
                       )
                     LIMIT 1",
                    libsql::params![source_id, expected_version],
                )
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("entity enrichment source guard: {e}"))
                })?;
            let current = current_rows
                .next()
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("entity enrichment source guard row: {e}"))
                })?
                .is_some();
            drop(current_rows);
            if !current {
                return Ok(false);
            }

            conn.execute(
                "DELETE FROM observations WHERE source_memory_id = ?1",
                libsql::params![source_id],
            )
            .await
            .map_err(|e| {
                WenlanError::VectorDb(format!(
                    "entity enrichment replace source observations: {e}"
                ))
            })?;

            let mut entity_ids: HashMap<String, String> = HashMap::new();
            let mut first_entity_id: Option<String> = None;
            for (lower, name, entity_type, embedding, minhash_candidate) in &prepared_entities {
                let mut resolved: Option<String> = None;
                let mut alias_source = "auto";

                let mut alias_rows = conn
                    .query(
                        "SELECT canonical_entity_id FROM entity_aliases
                         WHERE alias_name = ?1 LIMIT 1",
                        libsql::params![lower.as_str()],
                    )
                    .await
                    .map_err(|e| {
                        WenlanError::VectorDb(format!("entity enrichment alias lookup: {e}"))
                    })?;
                if let Some(row) = alias_rows.next().await.map_err(|e| {
                    WenlanError::VectorDb(format!("entity enrichment alias row: {e}"))
                })? {
                    resolved = Some(row.get::<String>(0).map_err(|e| {
                        WenlanError::VectorDb(format!("entity enrichment alias id: {e}"))
                    })?);
                }
                drop(alias_rows);

                if resolved.is_none() {
                    let mut exact_rows = conn
                        .query(
                            "SELECT id FROM entities WHERE LOWER(name) = ?1
                             ORDER BY created_at ASC, id ASC LIMIT 1",
                            libsql::params![lower.as_str()],
                        )
                        .await
                        .map_err(|e| {
                            WenlanError::VectorDb(format!(
                                "entity enrichment exact-name lookup: {e}"
                            ))
                        })?;
                    if let Some(row) = exact_rows.next().await.map_err(|e| {
                        WenlanError::VectorDb(format!("entity enrichment exact-name row: {e}"))
                    })? {
                        resolved = Some(row.get::<String>(0).map_err(|e| {
                            WenlanError::VectorDb(format!("entity enrichment exact-name id: {e}"))
                        })?);
                    }
                    drop(exact_rows);
                }

                // MinHash is an opt-in step between exact-name and vector
                // resolution in the canonical create_entity cascade. Its
                // candidate was prepared outside this transaction; verify the
                // entity still exists before accepting it.
                if resolved.is_none() {
                    if let Some(candidate_id) = minhash_candidate {
                        let mut candidate_rows = conn
                            .query(
                                "SELECT 1 FROM entities WHERE id = ?1 LIMIT 1",
                                libsql::params![candidate_id.as_str()],
                            )
                            .await
                            .map_err(|e| {
                                WenlanError::VectorDb(format!(
                                    "entity enrichment minhash candidate: {e}"
                                ))
                            })?;
                        if candidate_rows
                            .next()
                            .await
                            .map_err(|e| {
                                WenlanError::VectorDb(format!(
                                    "entity enrichment minhash candidate row: {e}"
                                ))
                            })?
                            .is_some()
                        {
                            resolved = Some(candidate_id.clone());
                            alias_source = "minhash";
                        }
                    }
                }

                // Preserve the existing create_entity cascade's >0.9 vector
                // resolution without leaving the transaction.
                if resolved.is_none() {
                    if let Ok(mut vector_rows) = conn
                        .query(
                            "SELECT id, vector_distance_cos(embedding, vector32(?1)) AS distance
                             FROM entities WHERE embedding IS NOT NULL
                             ORDER BY distance ASC LIMIT 1",
                            libsql::params![embedding.as_str()],
                        )
                        .await
                    {
                        if let Ok(Some(row)) = vector_rows.next().await {
                            let distance = row.get::<f64>(1).unwrap_or(1.0);
                            if distance < 0.1 {
                                resolved = row.get::<String>(0).ok();
                            }
                        }
                    }
                }

                let entity_id = match resolved {
                    Some(id) => id,
                    None => {
                        let id = uuid::Uuid::new_v4().to_string();
                        conn.execute(
                            "INSERT INTO entities
                                 (id, name, entity_type, space, source_agent, confidence,
                                  confirmed, created_at, updated_at, embedding)
                             VALUES (?1, ?2, ?3, NULL, 'post_ingest', NULL,
                                     0, ?4, ?4, vector32(?5))",
                            libsql::params![
                                id.as_str(),
                                name.as_str(),
                                entity_type.as_str(),
                                now,
                                embedding.as_str()
                            ],
                        )
                        .await
                        .map_err(|e| {
                            WenlanError::VectorDb(format!("entity enrichment entity insert: {e}"))
                        })?;
                        created_entities.push((id.clone(), name.clone()));
                        id
                    }
                };

                conn.execute(
                    "INSERT OR IGNORE INTO entity_aliases
                         (alias_name, canonical_entity_id, created_at, source)
                     VALUES (?1, ?2, ?3, ?4)",
                    libsql::params![lower.as_str(), entity_id.as_str(), now, alias_source],
                )
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("entity enrichment alias insert: {e}"))
                })?;

                if first_entity_id.is_none() {
                    first_entity_id = Some(entity_id.clone());
                }
                entity_ids.insert(lower.clone(), entity_id);
            }

            for kg in kg_results {
                for observation in &kg.observations {
                    let content = observation.content.trim();
                    if content.chars().count() < 5 {
                        continue;
                    }
                    let Some(entity_id) = entity_ids.get(&observation.entity.to_lowercase()) else {
                        continue;
                    };
                    let observation_id = uuid::Uuid::new_v4().to_string();
                    conn.execute(
                        "INSERT INTO observations
                             (id, entity_id, content, source_memory_id, source_agent,
                              confidence, confirmed, created_at)
                         VALUES (?1, ?2, ?3, ?4, 'post_ingest', NULL, 0, ?5)",
                        libsql::params![
                            observation_id.as_str(),
                            entity_id.as_str(),
                            content,
                            source_id,
                            now
                        ],
                    )
                    .await
                    .map_err(|e| {
                        WenlanError::VectorDb(format!(
                            "entity enrichment observation insert: {e}"
                        ))
                    })?;
                    conn.execute(
                        "UPDATE entities SET updated_at = ?1 WHERE id = ?2",
                        libsql::params![now, entity_id.as_str()],
                    )
                    .await
                    .map_err(|e| {
                        WenlanError::VectorDb(format!(
                            "entity enrichment observation timestamp: {e}"
                        ))
                    })?;
                }

                for relation in &kg.relations {
                    let raw_type = relation.relation_type.trim().to_lowercase();
                    let mut chars = raw_type.chars();
                    let valid_type = chars.next().is_some_and(|c| c.is_ascii_lowercase())
                        && chars.all(|c| {
                            c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_'
                        });
                    if !valid_type {
                        continue;
                    }
                    let Some(from_id) = entity_ids.get(&relation.from.to_lowercase()) else {
                        continue;
                    };
                    let Some(to_id) = entity_ids.get(&relation.to.to_lowercase()) else {
                        continue;
                    };

                    let mut canonical = None;
                    let mut canonical_rows = conn
                        .query(
                            "SELECT canonical FROM relation_type_vocabulary
                             WHERE canonical = ?1 LIMIT 1",
                            libsql::params![raw_type.as_str()],
                        )
                        .await
                        .map_err(|e| {
                            WenlanError::VectorDb(format!(
                                "entity enrichment relation vocabulary: {e}"
                            ))
                        })?;
                    if let Some(row) = canonical_rows.next().await.map_err(|e| {
                        WenlanError::VectorDb(format!(
                            "entity enrichment relation vocabulary row: {e}"
                        ))
                    })? {
                        canonical = row.get::<String>(0).ok();
                    }
                    drop(canonical_rows);
                    if canonical.is_none() {
                        let mut alias_rows = conn
                            .query(
                                "SELECT canonical, aliases FROM relation_type_vocabulary
                                 WHERE aliases IS NOT NULL",
                                (),
                            )
                            .await
                            .map_err(|e| {
                                WenlanError::VectorDb(format!(
                                    "entity enrichment relation aliases: {e}"
                                ))
                            })?;
                        while let Some(row) = alias_rows.next().await.map_err(|e| {
                            WenlanError::VectorDb(format!(
                                "entity enrichment relation alias row: {e}"
                            ))
                        })? {
                            let name = row.get::<String>(0).unwrap_or_default();
                            let aliases = row.get::<String>(1).unwrap_or_default();
                            let matched = serde_json::from_str::<Vec<String>>(&aliases)
                                .unwrap_or_default()
                                .iter()
                                .any(|alias| alias.eq_ignore_ascii_case(&raw_type));
                            if matched {
                                canonical = Some(name);
                                break;
                            }
                        }
                        drop(alias_rows);
                    }
                    let canonical = canonical.unwrap_or_else(|| "related_to".to_string());
                    let relation_id = uuid::Uuid::new_v4().to_string();
                    conn.execute(
                        "INSERT INTO relations
                             (id, from_entity, to_entity, relation_type, source_agent,
                              confidence, explanation, source_memory_id, created_at)
                         VALUES (?1, ?2, ?3, ?4, 'post_ingest', ?5, ?6, ?7, ?8)
                         ON CONFLICT(from_entity, to_entity, relation_type) DO UPDATE SET
                             confidence = CASE
                                 WHEN EXCLUDED.confidence IS NOT NULL
                                  AND (confidence IS NULL OR EXCLUDED.confidence > confidence)
                                 THEN EXCLUDED.confidence ELSE confidence END,
                             explanation = CASE
                                 WHEN EXCLUDED.confidence IS NOT NULL
                                  AND (confidence IS NULL OR EXCLUDED.confidence > confidence)
                                 THEN COALESCE(EXCLUDED.explanation, explanation)
                                 ELSE explanation END,
                             source_memory_id = COALESCE(EXCLUDED.source_memory_id, source_memory_id)",
                        libsql::params![
                            relation_id.as_str(),
                            from_id.as_str(),
                            to_id.as_str(),
                            canonical.as_str(),
                            relation
                                .confidence
                                .map(libsql::Value::Real)
                                .unwrap_or(libsql::Value::Null),
                            relation
                                .explanation
                                .as_deref()
                                .map(|value| libsql::Value::Text(value.to_string()))
                                .unwrap_or(libsql::Value::Null),
                            source_id,
                            now
                        ],
                    )
                    .await
                    .map_err(|e| {
                        WenlanError::VectorDb(format!("entity enrichment relation insert: {e}"))
                    })?;
                    conn.execute(
                        "DELETE FROM relations
                         WHERE from_entity = ?1 AND to_entity = ?2
                           AND relation_type <> ?3",
                        libsql::params![from_id.as_str(), to_id.as_str(), canonical.as_str()],
                    )
                    .await
                    .map_err(|e| {
                        WenlanError::VectorDb(format!(
                            "entity enrichment relation supersede: {e}"
                        ))
                    })?;
                }
            }

            for entity_id in entity_ids.values() {
                conn.execute(
                    "INSERT INTO memory_entities (memory_id, entity_id)
                     VALUES (?1, ?2) ON CONFLICT DO NOTHING",
                    libsql::params![source_id, entity_id.as_str()],
                )
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("entity enrichment memory link: {e}"))
                })?;
            }
            if let Some(first_entity_id) = first_entity_id {
                conn.execute(
                    "UPDATE memories SET entity_id = ?1 WHERE source_id = ?2",
                    libsql::params![first_entity_id.as_str(), source_id],
                )
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("entity enrichment legacy link: {e}"))
                })?;
            }

            conn.execute(
                "INSERT INTO enrichment_steps
                     (source_id, step_name, status, error, attempts, updated_at, input_version)
                 VALUES (?1, 'entity_extract', 'ok', NULL, 1, ?2, ?3)
                 ON CONFLICT(source_id, step_name) DO UPDATE SET
                     status = 'ok', error = NULL,
                     attempts = CASE
                         WHEN enrichment_steps.input_version = excluded.input_version
                              AND enrichment_steps.status <> 'skipped'
                         THEN enrichment_steps.attempts + 1
                         ELSE 1
                     END,
                     updated_at = ?2, input_version = ?3",
                libsql::params![source_id, now, expected_version],
            )
            .await
            .map_err(|e| {
                WenlanError::VectorDb(format!("entity enrichment receipt: {e}"))
            })?;

            Ok(true)
        }
        .await;

        match result {
            Ok(true) => {
                conn.execute("COMMIT", ())
                    .await
                    .map_err(|e| WenlanError::VectorDb(format!("entity enrichment commit: {e}")))?;
                drop(conn);
                if minhash_enabled {
                    for (entity_id, name) in created_entities {
                        if let Err(error) = self
                            .index_entity_minhash_if_eligible(&entity_id, &name)
                            .await
                        {
                            log::warn!(
                                "[entity_enrichment_slice] minhash index failed for {entity_id}: {error}"
                            );
                        }
                    }
                }
                Ok(true)
            }
            Ok(false) => {
                let _ = conn.execute("ROLLBACK", ()).await;
                Ok(false)
            }
            Err(error) => {
                if let Err(rollback_error) = conn.execute("ROLLBACK", ()).await {
                    log::error!(
                        "entity enrichment rollback failed after {error}: {rollback_error}"
                    );
                }
                Err(error)
            }
        }
    }

    async fn record_entity_enrichment_failure_at_version(
        &self,
        source_id: &str,
        expected_version: i64,
        status: &str,
        error: &str,
    ) -> Result<bool, WenlanError> {
        self.record_enrichment_step_at_version(
            source_id,
            "entity_extract",
            status,
            Some(error),
            expected_version,
        )
        .await
    }

    async fn commit_entity_link_at_version(
        &self,
        source_id: &str,
        expected_version: i64,
        entity_id: &str,
    ) -> Result<bool, WenlanError> {
        let now = chrono::Utc::now().timestamp();
        let conn = self.conn.lock().await;
        conn.execute("BEGIN", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("entity link begin: {e}")))?;
        let result: Result<bool, WenlanError> = async {
            let mut rows = conn
                .query(
                    "SELECT 1 FROM memories
                     WHERE source='memory' AND source_id=?1 AND chunk_index=0
                       AND version=?2 AND COALESCE(pending_revision, 0)=0
                       AND EXISTS (SELECT 1 FROM entities WHERE id=?3)
                       AND NOT EXISTS (
                           SELECT 1 FROM memories superseder
                           WHERE superseder.supersedes = memories.source_id
                             AND superseder.pending_revision = 0
                             AND superseder.source = 'memory'
                       )
                     LIMIT 1",
                    libsql::params![source_id, expected_version, entity_id],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("entity link guard: {e}")))?;
            let current = rows
                .next()
                .await
                .map_err(|e| WenlanError::VectorDb(format!("entity link guard row: {e}")))?
                .is_some();
            drop(rows);
            if !current {
                return Ok(false);
            }

            conn.execute(
                "INSERT INTO memory_entities (memory_id, entity_id)
                 VALUES (?1, ?2) ON CONFLICT DO NOTHING",
                libsql::params![source_id, entity_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("entity link junction: {e}")))?;
            conn.execute(
                "UPDATE memories SET entity_id=?1 WHERE source_id=?2",
                libsql::params![entity_id, source_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("entity link mirror: {e}")))?;

            for (step, status) in [("entity_link", "ok"), ("entity_extract", "ok")] {
                conn.execute(
                    "INSERT INTO enrichment_steps
                         (source_id, step_name, status, error,
                          attempts, updated_at, input_version)
                     VALUES (?1, ?2, ?3, NULL, 1, ?4, ?5)
                     ON CONFLICT(source_id, step_name) DO UPDATE SET
                         status=?3, error=NULL,
                         attempts=CASE
                             WHEN enrichment_steps.input_version=excluded.input_version
                              AND enrichment_steps.status <> 'skipped'
                             THEN enrichment_steps.attempts + 1
                             ELSE 1
                         END,
                         updated_at=?4, input_version=?5",
                    libsql::params![source_id, step, status, now, expected_version],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("entity link receipt: {e}")))?;
            }
            Ok(true)
        }
        .await;

        match result {
            Ok(true) => {
                conn.execute("COMMIT", ())
                    .await
                    .map_err(|e| WenlanError::VectorDb(format!("entity link commit: {e}")))?;
                Ok(true)
            }
            Ok(false) => {
                let _ = conn.execute("ROLLBACK", ()).await;
                Ok(false)
            }
            Err(error) => {
                let _ = conn.execute("ROLLBACK", ()).await;
                Err(error)
            }
        }
    }

    /// Enrich at most one memory that has no entity linkage via `extract_fn`.
    ///
    /// Memories ingested while the LLM was unavailable have `entity_id IS NULL`
    /// and no rows in `memory_entities`. One invocation selects one row and
    /// persists an `entity_extract` outcome, so a provider failure or a valid
    /// empty result cannot refetch the same head batch forever.
    ///
    /// `extract_fn` receives memory content and returns a pure parsed KG result.
    /// The source guard, KG rows, links, and receipt then commit together.
    ///
    /// Returns 1 when a memory was selected and attempted, or 0 when no row is
    /// eligible. `skipped` means ingestion had no provider and remains eligible;
    /// a successful empty extraction is terminal `ok`. Failures
    /// are `needs_retry` until the third attempt, then `abandoned`.
    pub async fn run_entity_enrichment_slice<F, Fut>(
        &self,
        extract_fn: F,
    ) -> Result<usize, WenlanError>
    where
        F: FnOnce(String) -> Fut,
        Fut: std::future::Future<
            Output = Result<Vec<crate::extract::KgExtractionResult>, WenlanError>,
        >,
    {
        self.run_entity_enrichment_slice_inner(None, extract_fn)
            .await
    }

    /// Try the zero-inference vector-link path before spending the provider
    /// budget on extraction. A current link commits its junction row, legacy
    /// mirror, and versioned receipts atomically.
    pub async fn run_entity_enrichment_slice_with_auto_link<F, Fut>(
        &self,
        entity_link_distance: f32,
        extract_fn: F,
    ) -> Result<usize, WenlanError>
    where
        F: FnOnce(String) -> Fut,
        Fut: std::future::Future<
            Output = Result<Vec<crate::extract::KgExtractionResult>, WenlanError>,
        >,
    {
        self.run_entity_enrichment_slice_inner(Some(entity_link_distance), extract_fn)
            .await
    }

    async fn run_entity_enrichment_slice_inner<F, Fut>(
        &self,
        entity_link_distance: Option<f32>,
        extract_fn: F,
    ) -> Result<usize, WenlanError>
    where
        F: FnOnce(String) -> Fut,
        Fut: std::future::Future<
            Output = Result<Vec<crate::extract::KgExtractionResult>, WenlanError>,
        >,
    {
        struct EntityEnrichmentCandidate {
            source_id: String,
            prior_attempts: u32,
            prior_status: Option<String>,
            expected_version: i64,
            existing_entity_id: Option<String>,
        }

        // The authoritative linkage is the junction table; `entity_id` is a
        // legacy one-to-one mirror. Terminal step outcomes exclude valid
        // no-entity memories and poison rows even though they remain unlinked.
        let candidate: Option<EntityEnrichmentCandidate> = {
            let conn = self.conn.lock().await;
            let mut rows = conn
                .query(
                    "SELECT m.source_id, \
                            CASE WHEN es.status = 'skipped' \
                                      OR es.input_version IS NULL \
                                      OR es.input_version <> m.version \
                                 THEN 0 \
                                 ELSE COALESCE(es.attempts, 0) END, \
                            es.status, m.version, \
                            COALESCE( \
                                (SELECT e.id FROM entities e WHERE e.id=m.entity_id), \
                                (SELECT me.entity_id FROM memory_entities me \
                                 JOIN entities e ON e.id=me.entity_id \
                                 WHERE me.memory_id=m.source_id \
                                 ORDER BY me.entity_id LIMIT 1) \
                            ) \
                     FROM memories m \
                     LEFT JOIN enrichment_origin eo \
                       ON eo.source_id = m.source_id \
                     LEFT JOIN enrichment_steps es \
                       ON es.source_id = m.source_id \
                      AND es.step_name = 'entity_extract' \
                     WHERE m.source = 'memory' AND m.chunk_index = 0 \
                       AND COALESCE(m.pending_revision, 0) = 0 \
                       AND NOT EXISTS ( \
                           SELECT 1 FROM memories superseder \
                           WHERE superseder.supersedes=m.source_id \
                             AND superseder.pending_revision=0 \
                             AND superseder.source='memory' \
                       ) \
                       AND ( \
                           es.source_id IS NULL \
                           OR es.input_version IS NULL \
                           OR es.input_version <> m.version \
                           OR es.status = 'skipped' \
                           OR ( \
                               es.input_version = m.version \
                               AND \
                               es.status IN ('failed', 'needs_retry') \
                               AND es.attempts < ?1 \
                           ) \
                       ) \
                     ORDER BY CASE WHEN m.supersedes IS NOT NULL THEN 0 ELSE 1 END, \
                              COALESCE(eo.service_class, 2) ASC, \
                              COALESCE(es.updated_at, m.last_modified) ASC, m.source_id ASC \
                     LIMIT 1",
                    libsql::params![Self::ENTITY_ENRICHMENT_MAX_ATTEMPTS as i64],
                )
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("run_entity_enrichment_slice query: {e}"))
                })?;
            rows.next()
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("run_entity_enrichment_slice row: {e}"))
                })?
                .map(|row| EntityEnrichmentCandidate {
                    source_id: row.get::<String>(0).unwrap_or_default(),
                    prior_attempts: row.get::<u32>(1).unwrap_or(0),
                    prior_status: row.get::<Option<String>>(2).unwrap_or(None),
                    expected_version: row.get::<i64>(3).unwrap_or(1),
                    existing_entity_id: row.get::<Option<String>>(4).unwrap_or(None),
                })
        };

        let Some(candidate) = candidate else {
            return Ok(0);
        };
        let EntityEnrichmentCandidate {
            source_id,
            prior_attempts,
            prior_status,
            expected_version,
            existing_entity_id,
        } = candidate;
        if source_id.is_empty() {
            return Ok(0);
        }
        // A historical `skipped` receipt and a receipt from an older source
        // generation both start a fresh retry budget. The guarded upsert below
        // resets their attempt count without an eager delete race.
        let _ = prior_status;

        if let Some(entity_id) = existing_entity_id {
            if !self
                .commit_entity_link_at_version(&source_id, expected_version, &entity_id)
                .await?
            {
                log::info!(
                    "[entity_enrichment_slice] dropped stale linked-receipt repair for {source_id}"
                );
            }
            return Ok(1);
        }

        let content = {
            let conn = self.conn.lock().await;
            Self::load_memory_enrichment_content(&conn, &source_id, expected_version).await?
        };

        if let Some(distance) = entity_link_distance {
            match self.search_entities_by_vector(&content, 3).await {
                Ok(entities) => {
                    if let Some(entity) = entities.iter().find(|entity| entity.distance < distance)
                    {
                        if !self
                            .commit_entity_link_at_version(
                                &source_id,
                                expected_version,
                                &entity.entity.id,
                            )
                            .await?
                        {
                            log::info!(
                                "[entity_enrichment_slice] dropped stale auto-link for {source_id}"
                            );
                        }
                        return Ok(1);
                    }
                    if !self
                        .record_enrichment_step_at_version(
                            &source_id,
                            "entity_link",
                            "ok",
                            None,
                            expected_version,
                        )
                        .await?
                    {
                        return Ok(1);
                    }
                }
                Err(error) => {
                    log::warn!(
                        "[entity_enrichment_slice] vector auto-link failed for {source_id}: {error}; falling back to extraction"
                    );
                }
            }
        }

        match extract_fn(content).await {
            Ok(kg_results) => {
                if !self
                    .commit_entity_enrichment_at_version(&source_id, expected_version, &kg_results)
                    .await?
                {
                    log::info!("[entity_enrichment_slice] dropped stale result for {source_id}");
                }
            }
            Err(error) => {
                let next_attempt = prior_attempts.saturating_add(1);
                let status = if next_attempt >= Self::ENTITY_ENRICHMENT_MAX_ATTEMPTS {
                    "abandoned"
                } else {
                    "needs_retry"
                };
                if self
                    .record_entity_enrichment_failure_at_version(
                        &source_id,
                        expected_version,
                        status,
                        &error.to_string(),
                    )
                    .await?
                {
                    log::warn!(
                        "[entity_enrichment_slice] extraction failed for {source_id}: {error}"
                    );
                } else {
                    log::info!("[entity_enrichment_slice] dropped stale failure for {source_id}");
                }
            }
        }

        Ok(1)
    }

    /// Get the entity_id for a memory (by source_id, chunk_index=0).
    pub async fn get_memory_entity_id(
        &self,
        source_id: &str,
    ) -> Result<Option<String>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT entity_id FROM memories WHERE source_id = ?1 AND chunk_index = 0 LIMIT 1",
                libsql::params![source_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_memory_entity_id: {}", e)))?;
        if let Ok(Some(row)) = rows.next().await {
            Ok(row.get::<Option<String>>(0).unwrap_or(None))
        } else {
            Ok(None)
        }
    }

    /// Get the source_agent for a memory (by source_id, chunk_index=0).
    pub async fn get_memory_source_agent(
        &self,
        source_id: &str,
    ) -> Result<Option<String>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT source_agent FROM memories WHERE source_id = ?1 AND chunk_index = 0 LIMIT 1",
                libsql::params![source_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_memory_source_agent: {}", e)))?;
        if let Ok(Some(row)) = rows.next().await {
            Ok(row.get::<Option<String>>(0).unwrap_or(None))
        } else {
            Ok(None)
        }
    }

    /// Find recent memories from the same source_agent within a time window, for batched extraction.
    /// Returns `Vec<(source_id, content)>` ordered by last_modified ASC, max 10.
    pub async fn find_recent_batch(
        &self,
        source_agent: &str,
        window_secs: i64,
    ) -> Result<Vec<(String, String)>, WenlanError> {
        let conn = self.conn.lock().await;
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs() as i64;
        let cutoff = now - window_secs;

        let mut rows = conn
            .query(
                "SELECT source_id, content FROM memories \
                 WHERE source = 'memory' AND chunk_index = 0 \
                   AND source_agent = ?1 \
                   AND entity_id IS NULL \
                   AND last_modified > ?2 \
                 ORDER BY last_modified ASC \
                 LIMIT 10",
                libsql::params![source_agent, cutoff],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("find_recent_batch: {}", e)))?;

        let mut results = Vec::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            let source_id: String = row
                .get(0)
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
            let content: String = row
                .get(1)
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
            results.push((source_id, content));
        }
        Ok(results)
    }

    /// Find memories that have no entity extraction (entity_id IS NULL).
    /// Used by the refinery's entity backfill phase to gradually self-heal.
    /// Returns `Vec<(source_id, content)>` ordered by last_modified DESC (newest first).
    pub async fn find_memories_without_entities(
        &self,
        limit: usize,
    ) -> Result<Vec<(String, String)>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT source_id, content FROM memories
                 WHERE source = 'memory' AND chunk_index=0 AND entity_id IS NULL
                   AND COALESCE(pending_revision, 0)=0
                   AND NOT EXISTS (
                       SELECT 1 FROM memories superseder
                       WHERE superseder.supersedes=memories.source_id
                         AND superseder.pending_revision=0
                         AND superseder.source='memory'
                   )
                   AND content IS NOT NULL AND content != ''
                 ORDER BY last_modified DESC
                 LIMIT ?1",
                libsql::params![limit as i64],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("find_memories_without_entities: {e}")))?;
        let mut results = Vec::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            let source_id: String = row
                .get(0)
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
            let content: String = row
                .get(1)
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
            results.push((source_id, content));
        }
        Ok(results)
    }

    /// Get enrichment status for a memory, derived from per-step outcomes.
    /// Delegates to `get_enrichment_summary` so callers get a live view of
    /// what actually ran rather than a stale flag.
    pub async fn get_enrichment_status(
        &self,
        source_id: &str,
    ) -> Result<Option<String>, WenlanError> {
        let summary = self.get_enrichment_summary(source_id).await?;
        Ok(Some(summary))
    }

    pub async fn get_enrichment_status_scoped(
        &self,
        source_id: &str,
        scope: &ReadScope,
    ) -> Result<Option<wenlan_types::EnrichmentStatusResponse>, WenlanError> {
        let exists = {
            let mut conditions = vec![
                "source = 'memory'".to_string(),
                "source_id = ?".to_string(),
                "chunk_index = 0".to_string(),
            ];
            let mut values = vec![libsql::Value::Text(source_id.to_string())];
            push_read_scope_filter_folded(scope, "space", &mut conditions, &mut values);
            let sql = format!(
                "SELECT 1 FROM memories WHERE {} LIMIT 1",
                conditions.join(" AND ")
            );
            let conn = self.conn.lock().await;
            let mut rows = conn
                .query(&sql, libsql::params_from_iter(values))
                .await
                .map_err(|e| WenlanError::VectorDb(format!("get_enrichment_status_scoped: {e}")))?;
            rows.next()
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("get_enrichment_status_scoped row: {e}"))
                })?
                .is_some()
        };
        if !exists {
            return Ok(None);
        }

        let steps = self.get_enrichment_steps(source_id).await?;
        let summary = self.get_enrichment_summary(source_id).await?;
        Ok(Some(wenlan_types::EnrichmentStatusResponse {
            source_id: source_id.to_string(),
            summary,
            steps,
        }))
    }

    /// Record (or upsert) a single enrichment step outcome for a memory.
    /// If a row for (source_id, step_name) already exists, increments attempts and updates status/error.
    pub async fn record_enrichment_step(
        &self,
        source_id: &str,
        step_name: &str,
        status: &str,
        error: Option<&str>,
    ) -> Result<(), WenlanError> {
        let now = chrono::Utc::now().timestamp();
        let conn = self.conn.lock().await;
        conn.execute(
            "INSERT INTO enrichment_steps (source_id, step_name, status, error, attempts, updated_at)
             VALUES (?1, ?2, ?3, ?4, 1, ?5)
             ON CONFLICT(source_id, step_name) DO UPDATE SET
                status = ?3, error = ?4, attempts = enrichment_steps.attempts + 1, updated_at = ?5",
            libsql::params![source_id, step_name, status, error, now],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("record_enrichment_step: {e}")))?;
        Ok(())
    }

    /// Record an enrichment outcome only when the source head still matches
    /// the generation that produced it. The source guard and receipt upsert
    /// share one transaction; `false` is a stale/pending/missing CAS miss.
    pub async fn record_enrichment_step_at_version(
        &self,
        source_id: &str,
        step_name: &str,
        status: &str,
        error: Option<&str>,
        expected_version: i64,
    ) -> Result<bool, WenlanError> {
        let now = chrono::Utc::now().timestamp();
        let conn = self.conn.lock().await;
        conn.execute("BEGIN", ()).await.map_err(|e| {
            WenlanError::VectorDb(format!("versioned enrichment receipt begin: {e}"))
        })?;
        let result: Result<bool, WenlanError> = async {
            let mut rows = conn
                .query(
                    "SELECT 1 FROM memories
                     WHERE source_id = ?1 AND chunk_index = 0
                       AND version = ?2 AND COALESCE(pending_revision, 0) = 0
                       AND NOT EXISTS (
                           SELECT 1 FROM memories superseder
                           WHERE superseder.supersedes = memories.source_id
                             AND superseder.pending_revision = 0
                             AND superseder.source = 'memory'
                       )
                     LIMIT 1",
                    libsql::params![source_id, expected_version],
                )
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("versioned enrichment receipt guard: {e}"))
                })?;
            let current = rows
                .next()
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("versioned enrichment receipt row: {e}"))
                })?
                .is_some();
            drop(rows);
            if !current {
                return Ok(false);
            }

            conn.execute(
                "INSERT INTO enrichment_steps
                     (source_id, step_name, status, error, attempts, updated_at, input_version)
                 VALUES (?1, ?2, ?3, ?4, 1, ?5, ?6)
                 ON CONFLICT(source_id, step_name) DO UPDATE SET
                     status = ?3, error = ?4,
                     attempts = CASE
                         WHEN enrichment_steps.input_version = excluded.input_version
                              AND enrichment_steps.status <> 'skipped'
                         THEN enrichment_steps.attempts + 1
                         ELSE 1
                     END,
                     updated_at = ?5, input_version = ?6",
                libsql::params![source_id, step_name, status, error, now, expected_version],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("versioned enrichment receipt: {e}")))?;
            Ok(true)
        }
        .await;

        match result {
            Ok(true) => {
                conn.execute("COMMIT", ()).await.map_err(|e| {
                    WenlanError::VectorDb(format!("versioned enrichment receipt commit: {e}"))
                })?;
                Ok(true)
            }
            Ok(false) => {
                let _ = conn.execute("ROLLBACK", ()).await;
                Ok(false)
            }
            Err(error) => {
                let _ = conn.execute("ROLLBACK", ()).await;
                Err(error)
            }
        }
    }

    /// Bulk-mark all chunk_index=0 memories as enriched (for eval).
    /// Inserts an "extract" enrichment step for every memory that doesn't have one.
    /// Returns the number of rows inserted.
    pub async fn mark_all_memories_enriched_for_eval(&self) -> Result<usize, WenlanError> {
        let now = chrono::Utc::now().timestamp();
        let conn = self.conn.lock().await;
        let affected = conn
            .execute(
                "INSERT OR IGNORE INTO enrichment_steps (source_id, step_name, status, attempts, updated_at)
                 SELECT source_id, 'extract', 'done', 1, ?1
                 FROM memories
                 WHERE source = 'memory' AND chunk_index = 0
                   AND source_id NOT IN (SELECT source_id FROM enrichment_steps WHERE step_name = 'extract')",
                libsql::params![now],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("mark_enriched_for_eval: {e}")))?;
        Ok(affected as usize)
    }

    /// Return all enrichment step records for a memory, ordered by insertion.
    pub async fn get_enrichment_steps(
        &self,
        source_id: &str,
    ) -> Result<Vec<wenlan_types::EnrichmentStepStatus>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT step_name, status, error, attempts, input_version
                 FROM enrichment_steps WHERE source_id = ?1 ORDER BY rowid",
                libsql::params![source_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_enrichment_steps: {e}")))?;
        let mut steps = Vec::new();
        while let Ok(Some(row)) = rows.next().await {
            steps.push(wenlan_types::EnrichmentStepStatus {
                step: row.get::<String>(0).unwrap_or_default(),
                status: row.get::<String>(1).unwrap_or_default(),
                error: row.get::<Option<String>>(2).ok().flatten(),
                attempts: row.get::<u32>(3).unwrap_or(0),
                input_version: row.get::<Option<i64>>(4).ok().flatten(),
            });
        }
        Ok(steps)
    }

    /// Derive a summary string from the enrichment_steps for a memory.
    /// Returns: "raw" (no steps), "enriched" (all ok/skipped), "enrichment_failed" (all failed/abandoned),
    /// or "enrichment_partial" (mixed).
    pub async fn get_enrichment_summary(&self, source_id: &str) -> Result<String, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT COUNT(*) as total,
                        SUM(CASE WHEN status IN ('failed', 'abandoned', 'needs_retry') THEN 1 ELSE 0 END) as failed_count,
                        SUM(CASE WHEN status IN ('ok','skipped') THEN 1 ELSE 0 END) as ok_count
                 FROM enrichment_steps WHERE source_id = ?1",
                libsql::params![source_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_enrichment_summary: {e}")))?;
        if let Ok(Some(row)) = rows.next().await {
            let total: i64 = row.get(0).unwrap_or(0);
            let failed: i64 = row.get(1).unwrap_or(0);
            let ok: i64 = row.get(2).unwrap_or(0);
            Ok(if total == 0 {
                "raw".to_string()
            } else if failed == 0 {
                "enriched".to_string()
            } else if ok == 0 {
                "enrichment_failed".to_string()
            } else {
                "enrichment_partial".to_string()
            })
        } else {
            Ok("raw".to_string())
        }
    }

    /// Return memories with at least one `failed` enrichment step that hasn't
    /// exceeded `max_attempts`, ordered oldest-first. Returns (source_id, step_name, content).
    pub async fn get_failed_enrichment_memories(
        &self,
        max_attempts: usize,
        limit: usize,
    ) -> Result<Vec<(String, String, String)>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT es.source_id, es.step_name, m.content
                 FROM enrichment_steps es
                 JOIN (SELECT source_id, content FROM memories WHERE chunk_index = 0 AND source = 'memory') m
                    ON m.source_id = es.source_id
                 WHERE es.status = 'failed' AND es.step_name != 'title_enrich'
                   AND es.attempts < ?1
                 ORDER BY es.updated_at ASC LIMIT ?2",
                libsql::params![max_attempts as i64, limit as i64],
            )
            .await
            .map_err(|e| {
                WenlanError::VectorDb(format!("get_failed_enrichment_memories: {e}"))
            })?;
        let mut results = Vec::new();
        while let Ok(Some(row)) = rows.next().await {
            results.push((
                row.get::<String>(0).unwrap_or_default(),
                row.get::<String>(1).unwrap_or_default(),
                row.get::<String>(2).unwrap_or_default(),
            ));
        }
        Ok(results)
    }

    /// Return memories needing title re-enrichment: those with `title_enrich`
    /// step in `failed` or `needs_retry` status, under the attempt limit.
    /// Returns (source_id, content) pairs, oldest-first.
    pub async fn get_title_reenrich_candidates(
        &self,
        max_attempts: usize,
        limit: usize,
    ) -> Result<Vec<(String, String)>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT es.source_id, m.content
                 FROM enrichment_steps es
                 JOIN memories m ON m.source_id = es.source_id
                    AND m.chunk_index = 0 AND m.source = 'memory'
                 WHERE es.step_name = 'title_enrich'
                   AND es.status IN ('failed', 'needs_retry')
                   AND es.attempts < ?1
                 ORDER BY es.updated_at ASC LIMIT ?2",
                libsql::params![max_attempts as i64, limit as i64],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_title_reenrich_candidates: {e}")))?;
        let mut results = Vec::new();
        while let Ok(Some(row)) = rows.next().await {
            results.push((
                row.get::<String>(0).unwrap_or_default(),
                row.get::<String>(1).unwrap_or_default(),
            ));
        }
        Ok(results)
    }

    /// Return memories where `title_enrich` is recorded as `ok` but the title
    /// still looks truncated (ends with "..." or length >= 75). Used for
    /// one-time backfill of pre-fix memories.
    pub async fn get_truncated_title_memories(
        &self,
        limit: usize,
    ) -> Result<Vec<(String, String)>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT m.source_id, m.content
                 FROM memories m
                 JOIN enrichment_steps es
                    ON es.source_id = m.source_id AND es.step_name = 'title_enrich'
                 WHERE m.chunk_index = 0 AND m.source = 'memory'
                   AND (m.title LIKE '%...' OR LENGTH(m.title) >= 75)
                   AND es.status = 'ok'
                 LIMIT ?1",
                libsql::params![limit as i64],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_truncated_title_memories: {e}")))?;
        let mut results = Vec::new();
        while let Ok(Some(row)) = rows.next().await {
            results.push((
                row.get::<String>(0).unwrap_or_default(),
                row.get::<String>(1).unwrap_or_default(),
            ));
        }
        Ok(results)
    }

    pub async fn confirm_entity(
        &self,
        entity_id: &str,
        confirmed: bool,
    ) -> Result<(), WenlanError> {
        let now_iso = chrono::Utc::now().to_rfc3339();
        let conn = self.conn.lock().await;
        // Transaction so the entity confirm and the shadow-page re-sync
        // (M3 PR-1 item C -- the shadow mirrors `entity_confirmed`) commit
        // atomically.
        conn.execute("BEGIN", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("confirm_entity begin: {}", e)))?;
        let result: Result<(), WenlanError> = async {
            conn.execute(
                "UPDATE entities SET confirmed = ?1 WHERE id = ?2",
                libsql::params![if confirmed { 1i64 } else { 0i64 }, entity_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("confirm_entity: {}", e)))?;
            Self::update_entity_shadow_page(&conn, entity_id, &now_iso).await?;
            Ok(())
        }
        .await;
        match result {
            Ok(()) => {
                conn.execute("COMMIT", ())
                    .await
                    .map_err(|e| WenlanError::VectorDb(format!("confirm_entity commit: {}", e)))?;
                Ok(())
            }
            Err(e) => {
                let _ = conn.execute("ROLLBACK", ()).await;
                Err(e)
            }
        }
    }

    pub async fn confirm_observation(
        &self,
        observation_id: &str,
        confirmed: bool,
    ) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;
        conn.execute(
            "UPDATE observations SET confirmed = ?1 WHERE id = ?2",
            libsql::params![if confirmed { 1i64 } else { 0i64 }, observation_id],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("confirm_observation: {}", e)))?;
        Ok(())
    }

    /// Run label propagation community detection on the entity-relationship graph.
    /// Returns the number of communities found and updates community_id on each entity.
    pub async fn detect_communities(&self) -> Result<usize, WenlanError> {
        let conn = self.conn.lock().await;

        // 1. Load all entity IDs
        let mut entity_rows = conn
            .query("SELECT id FROM entities", ())
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?;

        let mut entity_ids: Vec<String> = Vec::new();
        while let Some(row) = entity_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            entity_ids.push(
                row.get::<String>(0)
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?,
            );
        }
        drop(entity_rows);

        if entity_ids.is_empty() {
            return Ok(0);
        }

        // 2. Build adjacency list (undirected, weighted by parallel-edge count).
        // Reader cutover (M2 PR-2, stage c): the "communities" consumer reads
        // the `relates` adjacency from `edges` instead of the legacy
        // `relations` store ONLY when `reader_uses_edges` says parity is
        // proven-clean and current -- otherwise it stays on legacy. The two
        // sources are byte-identical under clean parity for SAME-SPACE rows:
        // `relations` has a UNIQUE(from_entity,to_entity,relation_type) index,
        // so each row maps to exactly one distinct `relates` edge_id and the
        // (from,to) multiset matches. D6 (M2 review fork-#2 verdict (a),
        // deferred to "an explicit M3 reader-cutover gate"): a
        // `lineage='legacy'` edge whose endpoints are cross-space is EXCLUDED
        // below once flipped -- read-side only, never a row mutation (would
        // register as parity drift and freeze every cutover) -- so the two
        // paths diverge exactly on cross-space legacy rows. The gate defaults
        // OFF, so production behavior is unchanged until a cutover is
        // explicitly enabled AND a clean watermark exists; regression-locked
        // by `detect_communities_edges_path_matches_legacy` (same-space
        // parity) and `detect_communities_flipped_excludes_cross_space_legacy_edge`
        // (the cross-space carve-out).
        let adjacency_sql = if Self::reader_uses_edges(&conn, "communities")
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            // Endpoint-space predicate reused verbatim from
            // `audit_legacy_cross_space_links`'s `relations` tally
            // (NULL-safe: an indeterminate-space endpoint is `null_space`,
            // not `cross_space`, so it is not excluded here either).
            "SELECT e.src_id, e.dst_id FROM edges e \
             LEFT JOIN entities se ON se.id = e.src_id \
             LEFT JOIN entities de ON de.id = e.dst_id \
             WHERE e.edge_type = 'relates' AND e.valid_until IS NULL \
             AND NOT (e.lineage = 'legacy' \
                      AND se.space IS NOT NULL AND de.space IS NOT NULL \
                      AND se.space != de.space)"
        } else {
            "SELECT from_entity, to_entity FROM relations"
        };
        let mut edge_rows = conn
            .query(adjacency_sql, ())
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?;

        let mut adjacency: std::collections::HashMap<
            String,
            std::collections::HashMap<String, u32>,
        > = std::collections::HashMap::new();

        while let Some(row) = edge_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            let from: String = row
                .get(0)
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
            let to: String = row
                .get(1)
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
            *adjacency
                .entry(from.clone())
                .or_default()
                .entry(to.clone())
                .or_insert(0) += 1;
            *adjacency.entry(to).or_default().entry(from).or_insert(0) += 1;
        }
        drop(edge_rows);

        // 3. Initialize labels: each entity gets its own index as label
        let id_to_idx: std::collections::HashMap<String, u32> = entity_ids
            .iter()
            .enumerate()
            .map(|(i, id)| (id.clone(), i as u32))
            .collect();
        let mut labels: Vec<u32> = (0..entity_ids.len() as u32).collect();

        // 4. Label propagation (max 100 iterations)
        for iteration in 0..100 {
            let mut changed = false;
            for (i, entity_id) in entity_ids.iter().enumerate() {
                if let Some(neighbors) = adjacency.get(entity_id) {
                    // Count neighbor labels weighted by edge count
                    let mut label_counts: std::collections::HashMap<u32, u32> =
                        std::collections::HashMap::new();
                    for (neighbor_id, weight) in neighbors {
                        if let Some(&neighbor_idx) = id_to_idx.get(neighbor_id) {
                            *label_counts
                                .entry(labels[neighbor_idx as usize])
                                .or_insert(0) += weight;
                        }
                    }
                    // Adopt most common label (ties broken by smallest label for determinism)
                    if let Some((&best_label, _)) = label_counts
                        .iter()
                        .max_by(|(l1, c1), (l2, c2)| c1.cmp(c2).then(l2.cmp(l1)))
                    {
                        if labels[i] != best_label {
                            labels[i] = best_label;
                            changed = true;
                        }
                    }
                }
            }
            if !changed {
                log::info!("[community] converged after {} iterations", iteration + 1);
                break;
            }
        }

        // 5. Normalize labels to sequential community IDs
        let mut label_to_community: std::collections::HashMap<u32, u32> =
            std::collections::HashMap::new();
        let mut next_community = 0u32;
        for &label in &labels {
            label_to_community.entry(label).or_insert_with(|| {
                let id = next_community;
                next_community += 1;
                id
            });
        }

        // 6. Update community_id on each entity (batch in transaction)
        conn.execute("BEGIN", ())
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
        let update_result: Result<(), WenlanError> = async {
            for (i, entity_id) in entity_ids.iter().enumerate() {
                let community_id = label_to_community[&labels[i]];
                conn.execute(
                    "UPDATE entities SET community_id = ?1 WHERE id = ?2",
                    libsql::params![community_id, entity_id.clone()],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
            }
            Ok(())
        }
        .await;
        if let Err(error) = update_result {
            let _ = conn.execute("ROLLBACK", ()).await;
            return Err(error);
        }
        if let Err(error) = conn.execute("COMMIT", ()).await {
            let _ = conn.execute("ROLLBACK", ()).await;
            return Err(WenlanError::VectorDb(error.to_string()));
        }

        log::info!(
            "[community] detected {} communities across {} entities",
            next_community,
            entity_ids.len()
        );
        Ok(next_community as usize)
    }

    /// Pin a confirmed memory. Returns an error if the memory is not confirmed
    /// or if the maximum number of pinned memories (12) has been reached.
    pub async fn pin_memory(&self, source_id: &str) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;

        // Check the memory exists
        let mut rows = conn
            .query(
                "SELECT source_id FROM memories WHERE source_id = ?1 AND source = 'memory' LIMIT 1",
                libsql::params![source_id.to_string()],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("pin_memory check: {}", e)))?;

        rows.next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .ok_or_else(|| WenlanError::VectorDb(format!("memory '{}' not found", source_id)))?;

        // Check if already pinned (skip count check if so)
        let mut already_rows = conn
            .query(
                "SELECT pinned FROM memories WHERE source_id = ?1 AND source = 'memory' LIMIT 1",
                libsql::params![source_id.to_string()],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("pin_memory already check: {}", e)))?;

        if let Some(r) = already_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            if r.get::<i64>(0).unwrap_or(0) != 0 {
                // Already pinned, nothing to do
                return Ok(());
            }
        }

        // Check count of distinct pinned source_ids
        let mut count_rows = conn
            .query(
                "SELECT COUNT(DISTINCT source_id) FROM memories WHERE pinned = 1 AND source = 'memory'",
                (),
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("pin_memory count: {}", e)))?;

        let pinned_count = count_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<i64>(0).unwrap_or(0))
            .unwrap_or(0);

        if pinned_count >= 12 {
            return Err(WenlanError::VectorDb(
                "maximum of 12 pinned memories reached".to_string(),
            ));
        }

        conn.execute(
            "UPDATE memories SET pinned = 1 WHERE source_id = ?1 AND source = 'memory'",
            libsql::params![source_id.to_string()],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("pin_memory update: {}", e)))?;

        Ok(())
    }

    /// Unpin a memory.
    pub async fn unpin_memory(&self, source_id: &str) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;
        conn.execute(
            "UPDATE memories SET pinned = 0 WHERE source_id = ?1 AND source = 'memory'",
            libsql::params![source_id.to_string()],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("unpin_memory: {}", e)))?;
        Ok(())
    }

