    /// Get snapshot captures whose current Memory owner belongs to `scope`.
    pub async fn get_captures_for_snapshot_scoped(
        &self,
        snapshot_id: &str,
        scope: &ReadScope,
    ) -> Result<Vec<CaptureRefRow>, WenlanError> {
        if matches!(scope, ReadScope::Global) {
            return self.get_captures_for_snapshot(snapshot_id).await;
        }

        let mut conditions = vec!["cr.snapshot_id = ?".to_string()];
        let mut values = vec![libsql::Value::Text(snapshot_id.to_string())];
        push_read_scope_filter_folded(scope, "m.space", &mut conditions, &mut values);
        match scope {
            ReadScope::Space(space) => {
                conditions.push(
                    "NOT EXISTS (
                         SELECT 1 FROM memories other
                          WHERE other.source = m.source
                            AND other.source_id = m.source_id
                            AND (other.space IS NULL OR other.space <> ?)
                     )"
                    .to_string(),
                );
                values.push(libsql::Value::Text(space.clone()));
            }
            ReadScope::Uncategorized => conditions.push(
                "NOT EXISTS (
                     SELECT 1 FROM memories other
                      WHERE other.source = m.source
                        AND other.source_id = m.source_id
                        AND other.space IS NOT NULL
                        AND other.space != '00000000-0000-4000-8000-000000000001'
                 )"
                .to_string(),
            ),
            ReadScope::Global => unreachable!(),
        }
        let sql = format!(
            "SELECT cr.source_id, cr.activity_id, cr.snapshot_id, cr.app_name,
                    cr.window_title, cr.timestamp, cr.source
               FROM capture_refs cr
               JOIN memories m
                 ON m.source_id = cr.source_id
                AND m.chunk_index = 0
                AND m.source = CASE cr.source
                    WHEN 'focus' THEN 'focus_capture'
                    WHEN 'hotkey' THEN 'hotkey_capture'
                    WHEN 'snip' THEN 'snip_capture'
                    WHEN 'thought' THEN 'quick_thought'
                    ELSE cr.source
                END
              WHERE {}
              ORDER BY cr.timestamp",
            conditions.join(" AND ")
        );
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(&sql, libsql::params_from_iter(values))
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_captures_for_snapshot_scoped: {e}")))?;
        let mut results = Vec::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(format!("snapshot capture row: {e}")))?
        {
            results.push(CaptureRefRow {
                source_id: row
                    .get(0)
                    .map_err(|e| WenlanError::VectorDb(format!("snapshot source_id: {e}")))?,
                activity_id: row
                    .get(1)
                    .map_err(|e| WenlanError::VectorDb(format!("snapshot activity_id: {e}")))?,
                snapshot_id: row
                    .get(2)
                    .map_err(|e| WenlanError::VectorDb(format!("snapshot id: {e}")))?,
                app_name: row
                    .get(3)
                    .map_err(|e| WenlanError::VectorDb(format!("snapshot app_name: {e}")))?,
                window_title: row
                    .get(4)
                    .map_err(|e| WenlanError::VectorDb(format!("snapshot window_title: {e}")))?,
                timestamp: row
                    .get(5)
                    .map_err(|e| WenlanError::VectorDb(format!("snapshot timestamp: {e}")))?,
                source: row
                    .get(6)
                    .map_err(|e| WenlanError::VectorDb(format!("snapshot source: {e}")))?,
            });
        }

        if results.is_empty() {
            Err(WenlanError::NotFound("snapshot not found".to_string()))
        } else {
            Ok(results)
        }
    }

    async fn get_snapshot_capture_content(
        &self,
        source: &str,
        source_id: &str,
        scope: &ReadScope,
    ) -> Result<String, WenlanError> {
        let mut conditions = vec!["source = ?".to_string(), "source_id = ?".to_string()];
        let mut values = vec![
            libsql::Value::Text(source.to_string()),
            libsql::Value::Text(source_id.to_string()),
        ];
        push_read_scope_filter_folded(scope, "space", &mut conditions, &mut values);
        let sql = format!(
            "SELECT content FROM memories WHERE {} ORDER BY chunk_index ASC LIMIT 10000",
            conditions.join(" AND ")
        );
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(&sql, libsql::params_from_iter(values))
            .await
            .map_err(|e| WenlanError::VectorDb(format!("snapshot capture content: {e}")))?;
        let mut chunks = Vec::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(format!("snapshot content row: {e}")))?
        {
            chunks.push(
                row.get::<String>(0)
                    .map_err(|e| WenlanError::VectorDb(format!("snapshot content: {e}")))?,
            );
        }
        if chunks.is_empty() {
            return Err(WenlanError::VectorDb(format!(
                "snapshot capture content missing: {source_id}"
            )));
        }
        Ok(chunks.join("\n"))
    }

    /// Get scoped snapshot captures with required content and summary loads.
    pub async fn get_snapshot_captures_with_content_scoped(
        &self,
        snapshot_id: &str,
        scope: &ReadScope,
    ) -> Result<Vec<wenlan_types::SnapshotCaptureWithContent>, WenlanError> {
        let captures = self
            .get_captures_for_snapshot_scoped(snapshot_id, scope)
            .await?;
        let indexed_files = self.list_indexed_files_scoped(scope).await?;
        let mut results = Vec::with_capacity(captures.len());

        for capture in captures {
            let memory_source = capture_memory_source(&capture.source);
            let content = self
                .get_snapshot_capture_content(memory_source, &capture.source_id, scope)
                .await?;
            let summary = indexed_files
                .iter()
                .find(|file| file.source == memory_source && file.source_id == capture.source_id)
                .and_then(|file| file.summary.clone());

            results.push(wenlan_types::SnapshotCaptureWithContent {
                source_id: capture.source_id,
                app_name: capture.app_name,
                window_title: capture.window_title,
                timestamp: capture.timestamp,
                source: capture.source,
                content,
                summary,
            });
        }

        Ok(results)
    }

    // ==================== Session Snapshots ====================

    /// Insert a session snapshot.
    pub async fn insert_snapshot(&self, snap: &SessionSnapshotRow) -> Result<(), WenlanError> {
        let now = chrono::Utc::now().timestamp();
        let apps_json = serde_json::to_string(&snap.primary_apps).unwrap_or_default();
        let tags_json = serde_json::to_string(&snap.tags).unwrap_or_default();
        let conn = self.conn.lock().await;
        conn.execute(
            "INSERT INTO session_snapshots (id, activity_id, started_at, ended_at, primary_apps, summary, tags, capture_count, created_at) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)",
            libsql::params![snap.id.clone(), snap.activity_id.clone(), snap.started_at, snap.ended_at, apps_json, snap.summary.clone(), tags_json, snap.capture_count as i64, now],
        ).await.map_err(|e| WenlanError::VectorDb(format!("insert_snapshot: {}", e)))?;
        Ok(())
    }

    /// Get recent session snapshots.
    pub async fn get_recent_snapshots(
        &self,
        limit: usize,
    ) -> Result<Vec<SessionSnapshotRow>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn.query(
            "SELECT id, activity_id, started_at, ended_at, primary_apps, summary, tags, capture_count FROM session_snapshots ORDER BY started_at DESC LIMIT ?1",
            [limit as i64],
        ).await.map_err(|e| WenlanError::VectorDb(format!("get_recent_snapshots: {}", e)))?;
        let mut results = vec![];
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            let apps_json: String = row
                .get(4)
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
            let tags_json: String = row
                .get(6)
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
            results.push(SessionSnapshotRow {
                id: row
                    .get(0)
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?,
                activity_id: row
                    .get(1)
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?,
                started_at: row
                    .get(2)
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?,
                ended_at: row
                    .get(3)
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?,
                primary_apps: serde_json::from_str(&apps_json).unwrap_or_default(),
                summary: row
                    .get(5)
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?,
                tags: serde_json::from_str(&tags_json).unwrap_or_default(),
                capture_count: row
                    .get::<i64>(7)
                    .map_err(|e| WenlanError::VectorDb(e.to_string()))?
                    as usize,
            });
        }
        Ok(results)
    }

    /// Delete a session snapshot and unlink its captures.
    pub async fn delete_snapshot(&self, snapshot_id: &str) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;
        conn.execute(
            "UPDATE capture_refs SET snapshot_id = NULL WHERE snapshot_id = ?1",
            [snapshot_id],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("delete_snapshot unlink: {}", e)))?;
        conn.execute("DELETE FROM session_snapshots WHERE id = ?1", [snapshot_id])
            .await
            .map_err(|e| WenlanError::VectorDb(format!("delete_snapshot: {}", e)))?;
        Ok(())
    }

    /// Update a snapshot's summary and tags (called by LLM after synthesis).
    pub async fn update_snapshot_summary(
        &self,
        snapshot_id: &str,
        summary: &str,
        tags: &[String],
    ) -> Result<(), WenlanError> {
        let tags_json = serde_json::to_string(tags).unwrap_or_default();
        let conn = self.conn.lock().await;
        conn.execute(
            "UPDATE session_snapshots SET summary = ?1, tags = ?2 WHERE id = ?3",
            libsql::params![summary, tags_json, snapshot_id],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("update_snapshot_summary: {}", e)))?;
        Ok(())
    }

    /// Delete session data (activities, capture_refs, snapshots) overlapping a time range.
    pub async fn delete_session_by_time_range(
        &self,
        start: i64,
        end: i64,
    ) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;
        // Find overlapping activity IDs
        let mut rows = conn
            .query(
                "SELECT id FROM activities WHERE started_at <= ?2 AND ended_at >= ?1",
                libsql::params![start, end],
            )
            .await
            .map_err(|e| {
                WenlanError::VectorDb(format!("delete_session_by_time_range query: {}", e))
            })?;
        let mut ids = vec![];
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            let id: String = row
                .get(0)
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
            ids.push(id);
        }
        drop(rows);

        for id in &ids {
            conn.execute(
                "UPDATE capture_refs SET snapshot_id = NULL WHERE activity_id = ?1 AND snapshot_id IS NOT NULL",
                [id.as_str()],
            ).await.map_err(|e| WenlanError::VectorDb(format!("delete_session unlink: {}", e)))?;
            conn.execute(
                "DELETE FROM session_snapshots WHERE activity_id = ?1",
                [id.as_str()],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("delete_session snapshots: {}", e)))?;
            conn.execute(
                "DELETE FROM capture_refs WHERE activity_id = ?1",
                [id.as_str()],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("delete_session captures: {}", e)))?;
            conn.execute("DELETE FROM activities WHERE id = ?1", [id.as_str()])
                .await
                .map_err(|e| WenlanError::VectorDb(format!("delete_session activity: {}", e)))?;
        }
        Ok(())
    }

