    /// Shared embedder singleton so the ONNX model is loaded exactly once
    /// across all tests (avoids concurrent download/read race).
    fn shared_embedder() -> Arc<std::sync::Mutex<TextEmbedding>> {
        static EMBEDDER: OnceLock<Arc<std::sync::Mutex<TextEmbedding>>> = OnceLock::new();
        EMBEDDER
            .get_or_init(|| {
                // Reuse the daemon's FastEmbed cache so tests don't try to
                // re-download the 140 MB ONNX model (which fails on hosts
                // with restricted network / HuggingFace TLS bundle issues,
                // e.g. the `OSStatus -26276` symptom we hit 2026-04-16).
                // We pass a bogus `db_path` — `resolve_fastembed_cache_dir`
                // will skip the per-DB branch (its tempdir-style db_path is
                // empty) and walk the env + shared-host candidates.
                let mut opts = InitOptions::new(EmbeddingModel::BGEBaseENV15Q)
                    .with_show_download_progress(false);
                let cache_dir =
                    resolve_fastembed_cache_dir(std::path::Path::new(".nonexistent"));
                if let Some(cache) = &cache_dir {
                    opts = opts.with_cache_dir(cache.clone());
                }
                let emb = init_text_embedding(opts).expect(
                    "failed to init embedder for tests (set WENLAN_TEST_FASTEMBED_CACHE or run the daemon once to populate the shared cache)",
                );
                Arc::new(std::sync::Mutex::new(emb))
            })
            .clone()
    }

    /// Helper: create a MemoryDB backed by a temp directory, reusing
    /// the shared embedder so tests can run in parallel safely.
    pub async fn test_db() -> (MemoryDB, tempfile::TempDir) {
        let dir = tempdir().expect("failed to create temp dir");
        let db_path = dir.path();
        std::fs::create_dir_all(db_path).unwrap();
        let db_file = db_path.join("origin_memory.db");

        let db = libsql::Builder::new_local(db_file.to_str().unwrap())
            .build()
            .await
            .expect("libsql open");
        let conn = db.connect().expect("libsql connect");
        conn.execute_batch("PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON;")
            .await
            .unwrap();
        conn.execute_batch(SCHEMA).await.unwrap();
        let _ = conn.execute_batch(FTS_SCHEMA).await;
        let _ = conn.execute_batch(FTS_TRIGGERS).await;

        // Create vector indexes (same as MemoryDB::new does)
        let _ = conn
            .execute(
                "CREATE INDEX IF NOT EXISTS memories_vec_idx ON memories (
                    libsql_vector_idx(embedding, 'metric=cosine', 'compress_neighbors=float8', 'max_neighbors=32')
                )",
                (),
            )
            .await;
        let _ = conn
            .execute(
                "CREATE INDEX IF NOT EXISTS entities_vec_idx ON entities (
                    libsql_vector_idx(embedding, 'metric=cosine', 'compress_neighbors=float8', 'max_neighbors=32')
                )",
                (),
            )
            .await;
        // T15a: child-vector index (migration 58 also creates it IF NOT EXISTS).
        let _ = conn
            .execute(
                "CREATE INDEX IF NOT EXISTS child_vectors_vec_idx ON child_vectors (
                    libsql_vector_idx(embedding, 'metric=cosine', 'compress_neighbors=float8', 'max_neighbors=32')
                )",
                (),
            )
            .await;

        let lint_freshness = Arc::new(
            crate::lint::snapshot::LintFreshnessClock::new(&db).expect("lint freshness observer"),
        );
        let memory_db = MemoryDB {
            _db: db,
            conn: Arc::new(tokio::sync::Mutex::new(conn)),
            entity_resolution_lock: tokio::sync::Mutex::new(()),
            lint_freshness,
            page_projection_tracker: crate::page_projection_tracker::PageProjectionTracker::new(),
            derived_artifact_state: crate::derived_artifact_state::DerivedArtifactState::new(),
            embedder: Some(shared_embedder()),
            // Token-aware chunker matching production; falls back to char-based
            // when the BGE tokenizer isn't in the resolved cache.
            chunker: build_chunker(std::path::Path::new(".nonexistent")),
            embedding_cache: std::sync::Mutex::new(EmbeddingCache::new(200)),
            community_dirty_nodes: std::sync::Mutex::new(BTreeMap::new()),
            community_grouping_runtime: std::sync::Mutex::new(
                crate::community_grouping::CommunityGroupingRuntime::default(),
            ),
        };
        memory_db
            .run_migrations(&crate::events::NoopEmitter)
            .await
            .unwrap();
        (memory_db, dir)
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn cancelling_m4_finalize_rolls_back_and_restores_lease_connection_and_runtime() {
        const SPACE: &str = "m4-cancel-space";
        const ROOT: &str = "m4-cancel-root";
        const NODE_COUNT: usize = 32;

        let (db, _dir) = test_db().await;
        let db = Arc::new(db);
        {
            let conn = db.conn.lock().await;
            conn.execute(
                "INSERT INTO provenance_roots
                    (root_id, identity_version, identity_digest, root_kind,
                     independence_group_id, status, created_at)
                 VALUES (?1, 1, 'm4-cancel-digest', 'generated',
                         'm4-cancel-group', 'active', 1712707200)",
                libsql::params![ROOT],
            )
            .await
            .unwrap();
            for node in 0..NODE_COUNT {
                conn.execute(
                    "INSERT INTO entities
                        (id, name, entity_type, space, created_at, updated_at)
                     VALUES (?1, ?1, 'concept', ?2, 1712707200, 1712707200)",
                    libsql::params![format!("m4-cancel-node-{node:02}"), SPACE],
                )
                .await
                .unwrap();
            }
            for node in 0..NODE_COUNT {
                conn.execute(
                    "INSERT INTO edges
                        (edge_id, src_id, src_kind, dst_id, dst_kind, edge_type, lineage,
                         grounded, root_id, space, created_at)
                     VALUES (?1, ?2, 'entity', ?3, 'entity', 'relates', 'assertion',
                             1, ?4, ?5, 1712707200)",
                    libsql::params![
                        format!("m4-cancel-edge-{node:02}"),
                        format!("m4-cancel-node-{node:02}"),
                        format!("m4-cancel-node-{:02}", (node + 1) % NODE_COUNT),
                        ROOT,
                        SPACE
                    ],
                )
                .await
                .unwrap();
            }
        }

        let first = db
            .run_next_community_grouping_cycle()
            .await
            .unwrap()
            .expect("first M4 cancellation fixture publication");
        assert!(matches!(
            first,
            crate::community_grouping::CommunityGroupingOutcome::Published(ref receipt)
                if receipt.compute_mode
                    == (crate::community_grouping::CommunityGroupingComputeMode::Full {
                        reason: crate::community_grouping::CommunityGroupingFullReason::FirstPublication,
                    })
        ));

        let (published_before, members_before, input_generation) = {
            let conn = db.conn.lock().await;
            let mut state = conn
                .query(
                    "SELECT published_generation FROM space_graph_state WHERE space = ?1",
                    libsql::params![SPACE],
                )
                .await
                .unwrap();
            let published = state
                .next()
                .await
                .unwrap()
                .unwrap()
                .get::<Option<i64>>(0)
                .unwrap()
                .unwrap();
            drop(state);
            let mut member_rows = conn
                .query(
                    "SELECT COUNT(*) FROM community_members WHERE space = ?1",
                    libsql::params![SPACE],
                )
                .await
                .unwrap();
            let members = member_rows
                .next()
                .await
                .unwrap()
                .unwrap()
                .get::<i64>(0)
                .unwrap();
            drop(member_rows);
            conn.execute(
                "INSERT INTO edges
                    (edge_id, src_id, src_kind, dst_id, dst_kind, edge_type, lineage,
                     grounded, root_id, space, created_at)
                 VALUES ('m4-cancel-chord', 'm4-cancel-node-00', 'entity',
                         'm4-cancel-node-03', 'entity', 'relates', 'assertion',
                         1, ?1, ?2, 1712707200)",
                libsql::params![ROOT, SPACE],
            )
            .await
            .unwrap();
            let mut generation_rows = conn
                .query(
                    "SELECT grouping_generation FROM space_graph_state WHERE space = ?1",
                    libsql::params![SPACE],
                )
                .await
                .unwrap();
            let generation = generation_rows
                .next()
                .await
                .unwrap()
                .unwrap()
                .get::<i64>(0)
                .unwrap();
            (published, members, generation)
        };
        db.record_community_dirty_nodes(vec![(
            SPACE.to_owned(),
            input_generation,
            BTreeSet::from([
                "m4-cancel-node-00".to_owned(),
                "m4-cancel-node-03".to_owned(),
            ]),
        )]);

        let (reached, _resume) = community_grouping_test_hooks::pause_after_member_delete(SPACE);
        let operation = {
            let db = Arc::clone(&db);
            tokio::spawn(async move { db.run_next_community_grouping_cycle().await })
        };
        reached.notified().await;
        operation.abort();
        assert!(operation.await.unwrap_err().is_cancelled());

        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            loop {
                let conn = db.conn.lock().await;
                let mut lease_rows = conn
                    .query(
                        "SELECT COUNT(*) FROM grouping_leases
                         WHERE phase = 'community' AND space = ?1",
                        libsql::params![SPACE],
                    )
                    .await
                    .unwrap();
                let leases = lease_rows
                    .next()
                    .await
                    .unwrap()
                    .unwrap()
                    .get::<i64>(0)
                    .unwrap();
                drop(lease_rows);
                drop(conn);
                if leases == 0 {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("attempt drop must release its durable lease");

        let (published_after, dirty_after, members_after) = {
            let conn = db.conn.lock().await;
            let mut state = conn
                .query(
                    "SELECT published_generation, dirty FROM space_graph_state WHERE space = ?1",
                    libsql::params![SPACE],
                )
                .await
                .unwrap();
            let state = state.next().await.unwrap().unwrap();
            let published = state.get::<Option<i64>>(0).unwrap().unwrap();
            let dirty = state.get::<i64>(1).unwrap();
            let mut member_rows = conn
                .query(
                    "SELECT COUNT(*) FROM community_members WHERE space = ?1",
                    libsql::params![SPACE],
                )
                .await
                .unwrap();
            let members = member_rows
                .next()
                .await
                .unwrap()
                .unwrap()
                .get::<i64>(0)
                .unwrap();
            (published, dirty, members)
        };
        assert_eq!(published_after, published_before);
        assert_eq!(dirty_after, 1);
        assert_eq!(members_after, members_before);
        assert_eq!(db.get_memory_count().await.unwrap(), 0);

        let retry = db
            .run_next_community_grouping_cycle()
            .await
            .unwrap()
            .expect("retry cancelled M4 publication");
        assert!(matches!(
            retry,
            crate::community_grouping::CommunityGroupingOutcome::Published(ref receipt)
                if matches!(
                    receipt.compute_mode,
                    crate::community_grouping::CommunityGroupingComputeMode::Incremental {
                        optimized_nodes
                    } if optimized_nodes > 0 && optimized_nodes < NODE_COUNT
                )
        ));
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn older_m4_cycle_cannot_overwrite_newer_published_runtime() {
        const SPACE: &str = "m4-overlap-space";
        const ROOT: &str = "m4-overlap-root";
        const NODE_COUNT: usize = 32;

        let (db, _dir) = test_db().await;
        let db = Arc::new(db);
        {
            let conn = db.conn.lock().await;
            conn.execute(
                "INSERT INTO provenance_roots
                    (root_id, identity_version, identity_digest, root_kind,
                     independence_group_id, status, created_at)
                 VALUES (?1, 1, 'm4-overlap-digest', 'generated',
                         'm4-overlap-group', 'active', 1712707200)",
                libsql::params![ROOT],
            )
            .await
            .unwrap();
            for node in 0..NODE_COUNT {
                conn.execute(
                    "INSERT INTO entities
                        (id, name, entity_type, space, created_at, updated_at)
                     VALUES (?1, ?1, 'concept', ?2, 1712707200, 1712707200)",
                    libsql::params![format!("m4-overlap-node-{node:02}"), SPACE],
                )
                .await
                .unwrap();
            }
            for node in 0..NODE_COUNT {
                conn.execute(
                    "INSERT INTO edges
                        (edge_id, src_id, src_kind, dst_id, dst_kind, edge_type, lineage,
                         grounded, root_id, space, created_at)
                     VALUES (?1, ?2, 'entity', ?3, 'entity', 'relates', 'assertion',
                             1, ?4, ?5, 1712707200)",
                    libsql::params![
                        format!("m4-overlap-ring-{node:02}"),
                        format!("m4-overlap-node-{node:02}"),
                        format!("m4-overlap-node-{:02}", (node + 1) % NODE_COUNT),
                        ROOT,
                        SPACE
                    ],
                )
                .await
                .unwrap();
            }
        }

        let first = db
            .run_next_community_grouping_cycle()
            .await
            .unwrap()
            .expect("publish initial M4 overlap runtime");
        let initial_generation = match first {
            crate::community_grouping::CommunityGroupingOutcome::Published(receipt) => {
                receipt.published_generation
            }
            crate::community_grouping::CommunityGroupingOutcome::Held(receipt) => {
                panic!("initial M4 overlap publication unexpectedly held: {receipt:?}")
            }
            crate::community_grouping::CommunityGroupingOutcome::Stale(receipt) => {
                panic!("initial M4 overlap publication went stale: {receipt:?}")
            }
        };

        let generation_g = {
            let conn = db.conn.lock().await;
            conn.execute(
                "INSERT INTO edges
                    (edge_id, src_id, src_kind, dst_id, dst_kind, edge_type, lineage,
                     grounded, root_id, space, created_at)
                 VALUES ('m4-overlap-g', 'm4-overlap-node-00', 'entity',
                         'm4-overlap-node-03', 'entity', 'relates', 'assertion',
                         1, ?1, ?2, 1712707200)",
                libsql::params![ROOT, SPACE],
            )
            .await
            .unwrap();
            let mut rows = conn
                .query(
                    "SELECT grouping_generation FROM space_graph_state WHERE space = ?1",
                    libsql::params![SPACE],
                )
                .await
                .unwrap();
            rows.next().await.unwrap().unwrap().get::<i64>(0).unwrap()
        };
        assert!(generation_g > initial_generation);
        db.record_community_dirty_nodes(vec![(
            SPACE.to_owned(),
            generation_g,
            BTreeSet::from([
                "m4-overlap-node-00".to_owned(),
                "m4-overlap-node-03".to_owned(),
            ]),
        )]);

        let (reached, resume) = community_grouping_test_hooks::pause_after_runtime_take(SPACE);
        let older_cycle = {
            let db = Arc::clone(&db);
            tokio::spawn(async move { db.run_next_community_grouping_cycle().await })
        };
        tokio::time::timeout(std::time::Duration::from_secs(2), reached.notified())
            .await
            .expect("generation G must pause after taking the shared runtime");

        let generation_g1 = {
            let conn = db.conn.lock().await;
            conn.execute(
                "INSERT INTO edges
                    (edge_id, src_id, src_kind, dst_id, dst_kind, edge_type, lineage,
                     grounded, root_id, space, created_at)
                 VALUES ('m4-overlap-g1', 'm4-overlap-node-01', 'entity',
                         'm4-overlap-node-05', 'entity', 'relates', 'assertion',
                         1, ?1, ?2, 1712707200)",
                libsql::params![ROOT, SPACE],
            )
            .await
            .unwrap();
            let mut rows = conn
                .query(
                    "SELECT grouping_generation FROM space_graph_state WHERE space = ?1",
                    libsql::params![SPACE],
                )
                .await
                .unwrap();
            rows.next().await.unwrap().unwrap().get::<i64>(0).unwrap()
        };
        assert!(generation_g1 > generation_g);
        db.record_community_dirty_nodes(vec![(
            SPACE.to_owned(),
            generation_g1,
            BTreeSet::from([
                "m4-overlap-node-01".to_owned(),
                "m4-overlap-node-05".to_owned(),
            ]),
        )]);

        let newer = db
            .run_next_community_grouping_cycle()
            .await
            .unwrap()
            .expect("generation G+1 must publish while G is paused");
        assert!(matches!(
            newer,
            crate::community_grouping::CommunityGroupingOutcome::Published(ref receipt)
                if receipt.published_generation == generation_g1
                    && receipt.compute_mode
                        == (crate::community_grouping::CommunityGroupingComputeMode::Full {
                            reason: crate::community_grouping::CommunityGroupingFullReason::RuntimeStateMissing,
                        })
        ));

        resume.notify_one();
        assert!(
            older_cycle.await.unwrap().is_err(),
            "generation G must lose its superseded lease"
        );
        assert_eq!(
            db.community_grouping_runtime
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .published_generation(SPACE),
            Some(generation_g1),
            "the unwinding generation G guard must not replace the published G+1 runtime"
        );

        let generation_g2 = {
            let conn = db.conn.lock().await;
            conn.execute(
                "INSERT INTO edges
                    (edge_id, src_id, src_kind, dst_id, dst_kind, edge_type, lineage,
                     grounded, root_id, space, created_at)
                 VALUES ('m4-overlap-g2', 'm4-overlap-node-02', 'entity',
                         'm4-overlap-node-07', 'entity', 'relates', 'assertion',
                         1, ?1, ?2, 1712707200)",
                libsql::params![ROOT, SPACE],
            )
            .await
            .unwrap();
            let mut rows = conn
                .query(
                    "SELECT grouping_generation FROM space_graph_state WHERE space = ?1",
                    libsql::params![SPACE],
                )
                .await
                .unwrap();
            rows.next().await.unwrap().unwrap().get::<i64>(0).unwrap()
        };
        db.record_community_dirty_nodes(vec![(
            SPACE.to_owned(),
            generation_g2,
            BTreeSet::from([
                "m4-overlap-node-02".to_owned(),
                "m4-overlap-node-07".to_owned(),
            ]),
        )]);
        let next = db
            .run_next_community_grouping_cycle()
            .await
            .unwrap()
            .expect("generation G+2 must retain the warm G+1 runtime");
        assert!(matches!(
            next,
            crate::community_grouping::CommunityGroupingOutcome::Published(ref receipt)
                if matches!(
                    receipt.compute_mode,
                    crate::community_grouping::CommunityGroupingComputeMode::Incremental {
                        optimized_nodes
                    } if optimized_nodes > 0 && optimized_nodes < NODE_COUNT
                )
        ));
    }

    /// Helper: build a minimal RawDocument for testing.
    fn make_doc(source: &str, source_id: &str, title: &str, content: &str) -> RawDocument {
        RawDocument {
            source: source.to_string(),
            source_id: source_id.to_string(),
            title: title.to_string(),
            summary: None,
            content: content.to_string(),
            url: None,
            last_modified: chrono::Utc::now().timestamp(),
            metadata: HashMap::new(),
            memory_type: None,
            space: None,
            source_agent: None,
            confidence: None,
            confirmed: None,
            supersedes: None,
            pending_revision: false,
            ..Default::default()
        }
    }

    /// Helper: build a RawDocument with memory-layer fields set.
    fn make_memory_doc(
        source_id: &str,
        content: &str,
        memory_type: &str,
        space: &str,
        source_agent: &str,
    ) -> RawDocument {
        let supersede_mode = if memory_type == "decision" {
            "archive".to_string()
        } else {
            "hide".to_string()
        };
        RawDocument {
            source: "memory".to_string(),
            source_id: source_id.to_string(),
            title: format!("memory-{}", source_id),
            summary: None,
            content: content.to_string(),
            url: None,
            last_modified: chrono::Utc::now().timestamp(),
            metadata: HashMap::new(),
            memory_type: Some(memory_type.to_string()),
            space: Some(space.to_string()),
            source_agent: Some(source_agent.to_string()),
            confidence: Some(0.9),
            confirmed: Some(false),
            supersedes: None,
            pending_revision: false,
            supersede_mode,
            ..Default::default()
        }
    }

    async fn memory_row_id(db: &MemoryDB, source: &str, source_id: &str) -> String {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT id FROM memories
                 WHERE source = ?1 AND source_id = ?2 AND chunk_index = 0",
                libsql::params![source, source_id],
            )
            .await
            .unwrap();
        rows.next()
            .await
            .unwrap()
            .unwrap()
            .get::<String>(0)
            .unwrap()
    }

    async fn install_page_locator_forms(
        db: &MemoryDB,
        prefix: &str,
        logical_source_id: &str,
        row_id: &str,
    ) -> Vec<(String, i64, i64)> {
        let now = chrono::Utc::now().to_rfc3339();
        let mixed_page_id = format!("{prefix}-mixed");
        db.insert_page(
            &mixed_page_id,
            &mixed_page_id,
            None,
            "body",
            None,
            None,
            &[logical_source_id, row_id],
            &now,
        )
        .await
        .unwrap();

        let json_only_page_id = format!("{prefix}-json-only");
        db.insert_page(
            &json_only_page_id,
            &json_only_page_id,
            None,
            "body",
            None,
            None,
            &[],
            &now,
        )
        .await
        .unwrap();
        {
            let conn = db.conn.lock().await;
            conn.execute(
                "UPDATE pages SET source_memory_ids = ?1 WHERE id = ?2",
                libsql::params![
                    serde_json::to_string(&[logical_source_id, row_id]).unwrap(),
                    json_only_page_id.as_str()
                ],
            )
            .await
            .unwrap();
        }

        let mut before = Vec::new();
        for page_id in [mixed_page_id, json_only_page_id] {
            db.clear_page_staleness(&page_id).await.unwrap();
            let page = db.get_page(&page_id).await.unwrap().unwrap();
            before.push((
                page_id.clone(),
                db.get_page_source_revision(&page_id).await.unwrap(),
                page.sources_updated_count,
            ));
        }
        before
    }

    async fn assert_pages_invalidated_once(
        db: &MemoryDB,
        before: &[(String, i64, i64)],
        expected_reason: &str,
    ) {
        for (page_id, revision_before, count_before) in before {
            let page = db.get_page(page_id).await.unwrap().unwrap();
            assert_eq!(page.stale_reason.as_deref(), Some(expected_reason));
            assert_eq!(
                db.get_page_source_revision(page_id).await.unwrap(),
                revision_before + 1,
                "{page_id} must advance its CAS token exactly once even when both logical and row locators match"
            );
            assert_eq!(
                page.sources_updated_count,
                count_before + 1,
                "{page_id} must count one changed logical source, not locator aliases"
            );
            if expected_reason == "source_removed" {
                assert!(
                    page.source_memory_ids.is_empty(),
                    "{page_id} must prune logical, physical-row, and JSON-only aliases"
                );
                assert!(db.get_page_sources(page_id).await.unwrap().is_empty());
                assert!(db.get_page_evidence(page_id).await.unwrap().is_empty());
            }
        }
    }

