    // ==================== Distillation Clustering ====================

    #[tokio::test]
    async fn test_find_distillation_clusters() {
        let (db, _dir) = test_db().await;

        // Insert 4 memories: 2 about topic A (same entity), 2 about topic B (same entity)
        for (i, (entity, content)) in [
            (
                "entity_arch",
                "libSQL stores vectors and knowledge graph in one database",
            ),
            (
                "entity_arch",
                "Using libSQL for all storage simplifies deployment",
            ),
            (
                "entity_mcp",
                "MCP surface was redesigned from 12 tools to 4",
            ),
            (
                "entity_mcp",
                "The MCP tools are remember recall context forget",
            ),
        ]
        .iter()
        .enumerate()
        {
            let doc = RawDocument {
                source: "memory".to_string(),
                source_id: format!("cluster_{}", i),
                title: content.to_string(),
                content: content.to_string(),
                entity_id: Some(entity.to_string()),
                space: Some("origin".to_string()),
                ..Default::default()
            };
            db.upsert_documents(vec![doc]).await.unwrap();
            // Record an enrichment step so the memory passes the EXISTS gate.
            db.record_enrichment_step(&format!("cluster_{}", i), "dedup", "ok", None)
                .await
                .unwrap();
        }

        let clusters = db
            .find_distillation_clusters(0.5, 2, 20, 3500, 50, 50)
            .await
            .unwrap();
        // Should find at least 1 cluster (entity groups with 2+ members)
        assert!(!clusters.is_empty(), "should find at least one cluster");
        // Each cluster should have at least 2 members
        for cluster in &clusters {
            assert!(
                cluster.source_ids.len() >= 2,
                "cluster too small: {:?}",
                cluster.source_ids
            );
        }
    }

    #[tokio::test]
    async fn find_distillation_clusters_includes_memories_without_enrichment_steps() {
        // The EXISTS enrichment_steps gate was removed when distillation was
        // unified to support Basic Memory mode (no daemon LLM, no enrichment).
        // All eligible memories now enter clustering regardless of enrichment
        // state; the synthesizer (daemon LLM or agent) decides what to make
        // of them.
        let (db, _dir) = test_db().await;

        let now = chrono::Utc::now().timestamp_millis();
        for (i, sid) in ["mem_e1", "mem_e2", "mem_r1", "mem_r2"].iter().enumerate() {
            let doc = RawDocument {
                source: "memory".to_string(),
                source_id: sid.to_string(),
                content: format!("Test content about Wenlan item {}", i),
                title: format!("Test mem {}", i),
                url: None,
                last_modified: now,
                memory_type: Some("fact".to_string()),
                space: Some("test".to_string()),
                entity_id: Some("ent_test".to_string()),
                ..Default::default()
            };
            db.upsert_documents(vec![doc]).await.unwrap();
        }

        // Record enrichment steps for only the first 2 — used to gate, now
        // doesn't.
        for sid in ["mem_e1", "mem_e2"].iter() {
            db.record_enrichment_step(sid, "dedup", "ok", None)
                .await
                .unwrap();
        }

        let clusters = db
            .find_distillation_clusters(0.3, 2, 20, 3500, 50, 50)
            .await
            .unwrap();

        let all_source_ids: Vec<String> = clusters
            .iter()
            .flat_map(|c| c.source_ids.iter().cloned())
            .collect();
        // All 4 memories share an entity_id and pass every other filter, so
        // the unenriched pair must now appear in the cluster set too.
        for sid in ["mem_e1", "mem_e2", "mem_r1", "mem_r2"].iter() {
            assert!(
                all_source_ids.contains(&sid.to_string()),
                "memory {} missing from clusters after enrichment gate removal: {:?}",
                sid,
                all_source_ids
            );
        }
    }

    #[tokio::test]
    async fn find_distillation_clusters_reads_space_scoped_staging_pool() {
        let (db, _dir) = test_db().await;

        let now = chrono::Utc::now().timestamp();
        let mut docs = Vec::new();
        for (sid, confirmed, source_agent, is_recap, space) in [
            ("stage_confirmed", Some(true), "test-agent", false, "alpha"),
            (
                "stage_unconfirmed",
                Some(false),
                "test-agent",
                false,
                "alpha",
            ),
            // Third capture so the cluster clears the >= 3 capture seed floor;
            // without it the two captures + one folder doc would not seed.
            (
                "stage_capture_third",
                Some(false),
                "test-agent",
                false,
                "alpha",
            ),
            (
                "stage_page_linked",
                Some(false),
                "test-agent",
                false,
                "alpha",
            ),
            ("recap_stage", Some(false), "test-agent", true, "alpha"),
            ("stage_folder_doc", None, "folder", false, "alpha"),
            (
                "stage_other_space",
                Some(false),
                "test-agent",
                false,
                "beta",
            ),
        ] {
            let mut doc = make_memory_doc(
                sid,
                &format!("Shared staging pool memory content for {sid}"),
                "fact",
                space,
                source_agent,
            );
            doc.confirmed = confirmed;
            doc.is_recap = is_recap;
            doc.entity_id = Some("stage_entity".to_string());
            doc.last_modified = now;
            docs.push(doc);
        }
        db.upsert_documents(docs).await.unwrap();

        db.insert_page(
            "stage_page",
            "Stage Page",
            Some("Already linked page"),
            "Already linked page body",
            None,
            Some("alpha"),
            &["stage_page_linked"],
            &chrono::Utc::now().to_rfc3339(),
        )
        .await
        .unwrap();

        let clusters = db
            .find_distillation_clusters_scoped(0.0, 1, 10, 3500, 50, 50, None, Some("alpha"))
            .await
            .unwrap();
        let actual: std::collections::BTreeSet<String> = clusters
            .iter()
            .flat_map(|cluster| cluster.source_ids.iter().cloned())
            .collect();

        assert_eq!(
            actual,
            std::collections::BTreeSet::from([
                "stage_capture_third".to_string(),
                "stage_confirmed".to_string(),
                "stage_folder_doc".to_string(),
                "stage_unconfirmed".to_string(),
            ]),
            "staging pool must include the three captures + recruited folder-doc for the requested space, and exclude page-linked/recap/other-space rows"
        );
    }

    #[tokio::test]
    async fn find_distillation_clusters_requires_three_non_document_captures_to_seed() {
        // Seeding rule (spec §4.2/§4.3): a cluster needs >= 3 staging CAPTURE
        // (non-doc) members to seed a page. Folder documents join clusters as
        // recruited evidence but never seed one. A book must not mint pages
        // from its own chapters. Here: 3 folder-doc chapters + 2 captures ->
        // only 2 captures -> no page seeds.
        let (db, _dir) = test_db().await;

        let now = chrono::Utc::now().timestamp_millis();
        let topic = "Wenlan distillation seed floor";
        let mut docs = Vec::new();
        for i in 0..3 {
            docs.push(RawDocument {
                source: "memory".to_string(),
                source_id: format!("seed_doc_chapter_{i}"),
                title: format!("Seed doc chapter {i}"),
                content: format!("{topic} folder chapter evidence section {i}"),
                last_modified: now + i,
                memory_type: Some("fact".to_string()),
                space: Some("alpha".to_string()),
                source_agent: Some("folder".to_string()),
                entity_id: Some("ent_seed_floor".to_string()),
                content_hash: Some("seed-floor-doc-hash".to_string()),
                ..Default::default()
            });
        }
        for i in 0..2 {
            docs.push(RawDocument {
                source: "memory".to_string(),
                source_id: format!("seed_capture_{i}"),
                title: format!("Seed capture {i}"),
                content: format!("{topic} captured note {i}"),
                last_modified: now + 10 + i,
                memory_type: Some("fact".to_string()),
                space: Some("alpha".to_string()),
                entity_id: Some("ent_seed_floor".to_string()),
                content_hash: None,
                ..Default::default()
            });
        }
        db.upsert_documents(docs).await.unwrap();

        let clusters = db
            .find_distillation_clusters_scoped(0.0, 3, 10, 3500, 50, 50, None, Some("alpha"))
            .await
            .unwrap();

        assert!(
            clusters.is_empty(),
            "document evidence must not seed a page with fewer than three captures: {:?}",
            clusters
                .iter()
                .map(|cluster| cluster.source_ids.clone())
                .collect::<Vec<_>>()
        );
    }

    #[tokio::test]
    async fn find_distillation_clusters_compares_same_space_memories_across_entity_buckets() {
        // Space is the only partition (spec §3.2/§8): two same-topic memories
        // that today sit in different entity buckets must now be compared and
        // cluster together. Setup: 3 captures in space "alpha" split across
        // two entity_ids; the old entity/community bucketing would never
        // compare ent_alpha vs ent_beta, so they could never co-cluster.
        let (db, _dir) = test_db().await;

        let now = chrono::Utc::now().timestamp_millis();
        for (sid, entity_id) in [
            ("cross_bucket_alpha", "ent_alpha"),
            ("cross_bucket_beta", "ent_beta"),
            ("cross_bucket_anchor", "ent_alpha"),
        ] {
            db.upsert_documents(vec![RawDocument {
                source: "memory".to_string(),
                source_id: sid.to_string(),
                title: format!("Cross bucket {sid}"),
                content: format!("Shared cross bucket topic about Wenlan distillation {sid}"),
                last_modified: now,
                memory_type: Some("fact".to_string()),
                space: Some("alpha".to_string()),
                entity_id: Some(entity_id.to_string()),
                content_hash: None,
                ..Default::default()
            }])
            .await
            .unwrap();
        }

        let clusters = db
            .find_distillation_clusters_scoped(0.0, 3, 10, 3500, 50, 50, None, Some("alpha"))
            .await
            .unwrap();

        assert!(
            clusters.iter().any(|cluster| {
                cluster
                    .source_ids
                    .iter()
                    .any(|id| id == "cross_bucket_alpha")
                    && cluster
                        .source_ids
                        .iter()
                        .any(|id| id == "cross_bucket_beta")
                    && cluster.source_ids.len() == 3
            }),
            "same-space memories from different entity buckets must be compared together: {:?}",
            clusters
                .iter()
                .map(|cluster| cluster.source_ids.clone())
                .collect::<Vec<_>>()
        );
    }

    #[tokio::test]
    async fn find_distillation_clusters_treats_empty_entity_id_as_unlinked() {
        // Space is the only partition now (entity/community buckets deleted).
        // Memories with no declared space fall into the single unlinked
        // catch-all, which carries the tighter `max_unlinked_cluster_size`
        // cap. entity_id is irrelevant to partitioning here — these rows have
        // space = None, so the unlinked cap must hold regardless of entity_id.
        //
        // Setup: 8 highly-similar memories with no space and empty-string
        // entity_id, with max_unlinked_cluster_size = 5. They land in the
        // unlinked catch-all → cap kicks in → returned cluster sizes <= 5.
        let (db, _dir) = test_db().await;

        let now = chrono::Utc::now().timestamp_millis();
        for i in 0..8 {
            let doc = RawDocument {
                source: "memory".to_string(),
                source_id: format!("mem_empty_eid_{}", i),
                content: format!("origin notes about distillation iteration {}", i),
                title: format!("Note {}", i),
                last_modified: now + i as i64,
                memory_type: None,
                space: None,
                entity_id: Some(String::new()), // <-- the marker
                ..Default::default()
            };
            db.upsert_documents(vec![doc]).await.unwrap();
            db.record_enrichment_step(
                &format!("mem_empty_eid_{}", i),
                "entity_backfill",
                "skipped",
                None,
            )
            .await
            .unwrap();
        }

        let clusters = db
            .find_distillation_clusters(0.3, 2, 20, 3500, 5, 50)
            .await
            .unwrap();

        for cluster in &clusters {
            assert!(
                cluster.source_ids.len() <= 5,
                "cluster of {} memories with empty entity_id exceeded cap 5 — \
                 bucketing bug?",
                cluster.source_ids.len(),
            );
        }
    }

    #[tokio::test]
    async fn find_distillation_clusters_caps_oversized_unlinked() {
        let (db, _dir) = test_db().await;

        // Insert 60 unlinked memories (no entity_id, no domain) with similar
        // content — should form ONE big unlinked cluster.
        let now = chrono::Utc::now().timestamp_millis();
        for i in 0..60 {
            let doc = RawDocument {
                source: "memory".to_string(),
                source_id: format!("mem_unlinked_{}", i),
                // Highly similar content — all about same topic
                content: format!("notes on origin distillation pipeline iteration {}", i),
                title: format!("Note {}", i),
                url: None,
                last_modified: now + i as i64,
                memory_type: None,
                space: None,
                entity_id: None,
                ..Default::default()
            };
            db.upsert_documents(vec![doc]).await.unwrap();
            // Mark enriched (must satisfy Task 4 gate)
            db.record_enrichment_step(&format!("mem_unlinked_{}", i), "dedup", "ok", None)
                .await
                .unwrap();
        }

        // Run with cap = 30. The single 60-memory unlinked cluster should be
        // skipped entirely. No clusters > 30 should be returned.
        let clusters = db
            .find_distillation_clusters(0.3, 2, 20, 3500, 30, 50)
            .await
            .unwrap();

        for cluster in &clusters {
            assert!(
                cluster.source_ids.len() <= 30,
                "cluster of {} memories exceeded cap of 30: {:?}",
                cluster.source_ids.len(),
                cluster.source_ids.first()
            );
        }
    }

    #[tokio::test]
    async fn find_distillation_clusters_caps_oversized_entity_group() {
        // A single space (think a "Wenlan" workspace in prod) accumulates a
        // long tail of memories over time. Greedy clustering returns one big
        // blob; the agent's coherence check rejects it as a grab-bag and the
        // user sees nothing. The grouped-cluster cap (named-space partition)
        // forces a re-split so coherent sub-topics still surface.
        let (db, _dir) = test_db().await;

        let now = chrono::Utc::now().timestamp_millis();
        // 20 memories on the same entity, all with similar prose so they
        // collapse into one greedy cluster at threshold 0.3 — well above the
        // grouped cap of 6 used below.
        for i in 0..20 {
            let doc = RawDocument {
                source: "memory".to_string(),
                source_id: format!("mem_origin_{}", i),
                content: format!("origin distillation pipeline note number {}", i),
                title: format!("Note {}", i),
                url: None,
                last_modified: now + i as i64,
                memory_type: None,
                space: Some("origin".to_string()),
                entity_id: Some("ent_origin".to_string()),
                ..Default::default()
            };
            db.upsert_documents(vec![doc]).await.unwrap();
        }

        // grouped cap = 6 → original blob must re-split or drop; no cluster
        // returned can exceed 6 memories.
        let clusters = db
            .find_distillation_clusters(0.3, 2, 20, 3500, 50, 6)
            .await
            .unwrap();

        for cluster in &clusters {
            assert!(
                cluster.source_ids.len() <= 6,
                "space-partition cluster of {} memories exceeded grouped cap 6 — \
                 oversized re-split not applied to the named-space partition",
                cluster.source_ids.len(),
            );
        }
    }

