    /// Contract test for `apply_enrichment` — the combined writeback path
    /// used by the async classify + extract flow in `handle_store_memory`.
    ///
    /// Invariants locked down:
    ///   * `memory_type` and `supersede_mode` overwrite unconditionally
    ///     (agent-refined classification wins over the initial placeholder).
    ///   * `domain` / `quality` use `COALESCE(?, col)` — `None` passes
    ///     preserve the caller-supplied original, `Some` replaces.
    ///   * `structured_fields` / `retrieval_cue` only touch `chunk_index = 0`
    ///     (those fields live on the lead chunk only).
    ///   * `needs_reembed` flips to `1` iff structured fields were provided
    ///     (so the re-embed pass picks it up).
    #[tokio::test]
    async fn test_apply_enrichment_writes_classification_and_extraction() {
        let (db, _dir) = test_db().await;
        let mut doc = make_memory_doc(
            "mem_apply",
            "Alice prefers dark mode in editors",
            "fact",
            "preferences",
            "claude",
        );
        // Caller-supplied space should survive a `None` in apply_enrichment.
        doc.space = Some("preferences".to_string());
        db.upsert_documents(vec![doc]).await.unwrap();

        // Apply enrichment with a refined memory_type, no space/quality,
        // fresh supersede_mode, and a structured-fields payload.
        db.apply_enrichment(
            "mem_apply",
            "preference",
            None,
            Some("high"),
            "hide",
            Some(r#"{"preference":"dark mode","applies_when":"editors"}"#),
            Some("What editor theme does Alice use?"),
            None,
            None,
            None,
        )
        .await
        .unwrap();

        // Assert the row-level metadata flipped / preserved per spec.
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT memory_type, space, quality, supersede_mode,
                        structured_fields, retrieval_cue, needs_reembed
                 FROM memories WHERE source_id = 'mem_apply' AND chunk_index = 0",
                (),
            )
            .await
            .unwrap();
        let row = rows.next().await.unwrap().unwrap();
        let memory_type: String = row.get(0).unwrap();
        let space: Option<String> = row.get(1).unwrap();
        let quality: Option<String> = row.get(2).unwrap();
        let supersede_mode: String = row.get(3).unwrap();
        let sf: Option<String> = row.get(4).unwrap();
        let cue: Option<String> = row.get(5).unwrap();
        let needs_reembed: i64 = row.get(6).unwrap();

        assert_eq!(memory_type, "preference");
        assert_eq!(
            space.as_deref(),
            Some("preferences"),
            "None space input must preserve existing column value via COALESCE"
        );
        assert_eq!(quality.as_deref(), Some("high"));
        assert_eq!(supersede_mode, "hide");
        assert!(sf.is_some());
        assert!(sf.unwrap().contains("dark mode"));
        assert_eq!(cue.as_deref(), Some("What editor theme does Alice use?"));
        assert_eq!(
            needs_reembed, 1,
            "structured_fields update must set needs_reembed = 1 so re-embed picks it up"
        );
    }

    #[tokio::test]
    async fn stale_classification_writes_no_fields_tags_or_receipt() {
        let (db, _dir) = test_db().await;
        db.upsert_documents(vec![make_memory_doc(
            "mem_stale_classification",
            "Original input for classification",
            "fact",
            "work",
            "agent",
        )])
        .await
        .unwrap();
        db.set_document_tags(
            "memory",
            "mem_stale_classification",
            vec!["original".to_string()],
        )
        .await
        .unwrap();

        db.apply_memory_update(
            "mem_stale_classification",
            Some("New input while classification is running"),
            None,
            false,
            None,
            None,
        )
        .await
        .unwrap();

        let committed = db
            .commit_classification_at_version(
                "mem_stale_classification",
                1,
                Some("preference"),
                Some("personal"),
                Some("high"),
                Some("hide"),
                Some(9),
                &["stale".to_string()],
            )
            .await
            .unwrap();
        assert!(!committed, "a v1 result must not commit over v2 input");

        let conn = db.conn.lock().await;
        let row = conn
            .query(
                "SELECT memory_type, space, quality, importance
                 FROM memories
                 WHERE source_id='mem_stale_classification' AND chunk_index=0",
                (),
            )
            .await
            .unwrap()
            .next()
            .await
            .unwrap()
            .unwrap();
        assert_eq!(row.get::<String>(0).unwrap(), "fact");
        assert_eq!(
            row.get::<Option<String>>(1).unwrap().as_deref(),
            Some("work")
        );
        assert_eq!(row.get::<Option<String>>(2).unwrap(), None);
        assert_eq!(row.get::<Option<i64>>(3).unwrap(), None);
        let receipt_count = conn
            .query(
                "SELECT COUNT(*) FROM enrichment_steps
                 WHERE source_id='mem_stale_classification' AND step_name='classify'",
                (),
            )
            .await
            .unwrap()
            .next()
            .await
            .unwrap()
            .unwrap()
            .get::<i64>(0)
            .unwrap();
        assert_eq!(receipt_count, 0);
        drop(conn);
        assert_eq!(
            db.get_document_tags("memory", "mem_stale_classification")
                .await
                .unwrap(),
            vec!["original".to_string()]
        );
    }

