    // ── migration 53 replay test ──────────────────────────────────────────────

    #[tokio::test]
    async fn test_migration_53_relations_indexes() {
        let tmp = tempfile::tempdir().unwrap();
        let db_path = tmp.path().join("test.db");

        // First open: runs all migrations including 53.
        let db = MemoryDB::new(&db_path, Arc::new(crate::events::NoopEmitter))
            .await
            .unwrap();

        {
            let conn = db.conn.lock().await;

            let mut rows = conn
                .query("SELECT name FROM sqlite_master WHERE type='index' AND tbl_name='relations' AND name IN ('idx_relations_from', 'idx_relations_to')", ())
                .await
                .unwrap();
            let mut names: Vec<String> = Vec::new();
            while let Some(row) = rows.next().await.unwrap() {
                names.push(row.get::<String>(0).unwrap());
            }
            names.sort();
            assert_eq!(
                names,
                vec![
                    "idx_relations_from".to_string(),
                    "idx_relations_to".to_string()
                ]
            );

            // Verify the indexes are composite (cover 2 columns each).
            let mut rows = conn
                .query(
                    "SELECT COUNT(*) FROM pragma_index_info('idx_relations_from')",
                    (),
                )
                .await
                .unwrap();
            let count: i64 = if let Some(row) = rows.next().await.unwrap() {
                row.get::<i64>(0).unwrap_or(0)
            } else {
                0
            };
            assert_eq!(count, 2, "idx_relations_from must be composite (2 columns)");

            let mut rows2 = conn
                .query(
                    "SELECT COUNT(*) FROM pragma_index_info('idx_relations_to')",
                    (),
                )
                .await
                .unwrap();
            let count2: i64 = if let Some(row) = rows2.next().await.unwrap() {
                row.get::<i64>(0).unwrap_or(0)
            } else {
                0
            };
            assert_eq!(count2, 2, "idx_relations_to must be composite (2 columns)");
        }
    }

    #[tokio::test]
    async fn test_migration_54_memory_entities_table() {
        let tmp = tempfile::tempdir().unwrap();
        let db_path = tmp.path().join("test.db");
        let db = MemoryDB::new(&db_path, Arc::new(crate::events::NoopEmitter))
            .await
            .unwrap();
        let conn = db.conn.lock().await;

        let mut rows = conn
            .query("SELECT name FROM pragma_table_info('memory_entities')", ())
            .await
            .unwrap();
        let mut cols: Vec<String> = Vec::new();
        while let Some(row) = rows.next().await.unwrap() {
            cols.push(row.get::<String>(0).unwrap());
        }
        cols.sort();
        assert_eq!(cols, vec!["entity_id".to_string(), "memory_id".to_string()]);

        let mut rows = conn
            .query("SELECT name FROM sqlite_master WHERE type='index' AND tbl_name='memory_entities' AND name='idx_memory_entities_entity_memory'", ())
            .await
            .unwrap();
        assert!(rows.next().await.unwrap().is_some());

        // Seed a real entity so the second insert can succeed under FK.
        conn.execute(
            "INSERT INTO entities (id, name, entity_type, created_at, updated_at) VALUES ('ent_x', 'X', 'Topic', 0, 0)",
            (),
        )
        .await
        .unwrap();

        // memory_id has no FK (source_id non-unique). Insert succeeds.
        let res = conn
            .execute(
                "INSERT INTO memory_entities (memory_id, entity_id) VALUES ('mem_does_not_exist', 'ent_x')",
                (),
            )
            .await;
        assert!(res.is_ok(), "insert should succeed (no FK on memory_id)");

        // FK on entity_id rejects a bogus entity.
        let res = conn
            .execute(
                "INSERT INTO memory_entities (memory_id, entity_id) VALUES ('mem_y', 'ent_bogus')",
                (),
            )
            .await;
        assert!(
            res.is_err(),
            "insert should fail (FK violation on entity_id)"
        );
    }

    #[tokio::test]
    async fn reassign_memories_space_works() {
        let (db, _td) = test_db().await;

        db.create_space("foo", None, false).await.unwrap();
        db.create_space("bar", None, false).await.unwrap();

        let doc1 = make_memory_doc(
            "mem_move_1",
            "First memory in foo.",
            "knowledge",
            "foo",
            "agent",
        );
        let doc2 = make_memory_doc(
            "mem_move_2",
            "Second memory in foo.",
            "knowledge",
            "foo",
            "agent",
        );
        db.upsert_documents(vec![doc1]).await.unwrap();
        db.upsert_documents(vec![doc2]).await.unwrap();

        let affected = db.reassign_memories_space("foo", "bar").await.unwrap();
        assert!(
            affected >= 2,
            "expected >= 2 rows updated, got {}",
            affected
        );

        // Verify via a direct count query.
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query("SELECT COUNT(*) FROM memories WHERE space = 'bar'", ())
            .await
            .unwrap();
        let row = rows.next().await.unwrap().expect("count row");
        let bar_count: i64 = row.get(0).unwrap();
        assert!(
            bar_count >= 2,
            "expected >= 2 memories in bar, got {}",
            bar_count
        );

        let mut rows2 = conn
            .query("SELECT COUNT(*) FROM memories WHERE space = 'foo'", ())
            .await
            .unwrap();
        let row2 = rows2.next().await.unwrap().expect("count row");
        let foo_count: i64 = row2.get(0).unwrap();
        assert_eq!(foo_count, 0, "foo should have 0 memories after move");
    }

    #[tokio::test]
    async fn reassign_memories_space_cascades_pages_space_and_workspace() {
        let (db, _td) = test_db().await;

        db.create_space("src", None, false).await.unwrap();
        db.create_space("dest", None, false).await.unwrap();

        let doc = make_memory_doc(
            "mem_page_move_1",
            "Memory in src with an associated page.",
            "knowledge",
            "src",
            "agent",
        );
        db.upsert_documents(vec![doc]).await.unwrap();

        let now = chrono::Utc::now().to_rfc3339();
        db.insert_page_with_kind(
            "page_legacy_src",
            "Legacy Src",
            None,
            "legacy page using pages.space as the space axis",
            None,
            Some("src"),
            &["mem_page_move_1"],
            &now,
            "authored",
            "confirmed",
            None,
            None,
        )
        .await
        .unwrap();
        db.insert_page_with_kind(
            "page_workspace_src",
            "Workspace Src",
            None,
            "newer page scoped by pages.workspace (single-axis: space mirrors workspace)",
            None,
            None,
            &["mem_page_move_1"],
            &now,
            "authored",
            "confirmed",
            Some("src"),
            None,
        )
        .await
        .unwrap();

        db.reassign_memories_space("src", "dest").await.unwrap();

        let legacy = db.get_page("page_legacy_src").await.unwrap().unwrap();
        assert_eq!(
            legacy.space.as_deref(),
            Some("dest"),
            "space move must update legacy pages.space values"
        );
        assert_eq!(
            legacy.version, 1,
            "reassigning scope metadata must not advance an active Page content version"
        );

        let scoped = db.get_page("page_workspace_src").await.unwrap().unwrap();
        assert_eq!(
            scoped.space.as_deref(),
            Some("dest"),
            "space move mirrors the scope onto pages.space -- one honest column, no independent category (spec §1)"
        );
        assert_eq!(
            scoped.workspace.as_deref(),
            Some("dest"),
            "space move must update pages.workspace values"
        );
        assert_eq!(
            scoped.version, 1,
            "reassigning scope metadata must not advance an active Page content version"
        );

        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT version FROM memories
                 WHERE source_id = 'mem_page_move_1'
                   AND source != 'episode' AND chunk_index = 0",
                (),
            )
            .await
            .unwrap();
        assert_eq!(
            rows.next().await.unwrap().unwrap().get::<i64>(0).unwrap(),
            2
        );
    }

    #[tokio::test]
    async fn changing_page_evidence_bumps_source_revision_and_resets_citations_once() {
        let (db, _dir) = test_db().await;
        db.upsert_documents(vec![
            make_memory_doc(
                "mem_page_evidence_a",
                "First Page source",
                "fact",
                "work",
                "agent",
            ),
            make_memory_doc(
                "mem_page_evidence_b",
                "Second Page source",
                "fact",
                "work",
                "agent",
            ),
        ])
        .await
        .unwrap();
        let now = chrono::Utc::now().to_rfc3339();
        db.insert_page_with_kind(
            "page_evidence_generation",
            "Evidence Generation",
            None,
            "Page content",
            None,
            Some("work"),
            &["mem_page_evidence_a"],
            &now,
            "authored",
            "confirmed",
            Some("work"),
            None,
        )
        .await
        .unwrap();
        db.set_page_citations_for_test("page_evidence_generation", "[]")
            .await
            .unwrap();

        db.link_page_source(
            "page_evidence_generation",
            "mem_page_evidence_b",
            "test_attach",
        )
        .await
        .unwrap();

        let read_state = || async {
            let conn = db.conn.lock().await;
            let mut rows = conn
                .query(
                    "SELECT version, source_revision, citations, source_memory_ids FROM pages
                     WHERE id = 'page_evidence_generation'",
                    (),
                )
                .await
                .unwrap();
            let row = rows.next().await.unwrap().unwrap();
            (
                row.get::<i64>(0).unwrap(),
                row.get::<i64>(1).unwrap(),
                row.get::<Option<String>>(2).unwrap(),
                serde_json::from_str::<Vec<String>>(&row.get::<String>(3).unwrap()).unwrap(),
            )
        };
        let (version, source_revision, citations, source_ids) = read_state().await;
        assert_eq!(version, 1);
        assert_eq!(source_revision, 1);
        assert_eq!(citations, None, "changed evidence re-enters citation lane");
        assert_eq!(
            source_ids,
            vec![
                "mem_page_evidence_a".to_string(),
                "mem_page_evidence_b".to_string()
            ]
        );

        db.link_page_source(
            "page_evidence_generation",
            "mem_page_evidence_b",
            "test_attach",
        )
        .await
        .unwrap();
        let repeated = read_state().await;
        assert_eq!(
            (repeated.0, repeated.1),
            (1, 1),
            "an idempotent link must not bump either generation"
        );
    }

