    fn extracted_entity(name: &str, entity_type: &str) -> Vec<crate::extract::KgExtractionResult> {
        vec![crate::extract::KgExtractionResult {
            index: 0,
            entities: vec![crate::extract::ExtractedEntity {
                name: name.to_string(),
                entity_type: entity_type.to_string(),
            }],
            observations: Vec::new(),
            relations: Vec::new(),
        }]
    }

    fn extracted_entity_with_observation(
        name: &str,
        entity_type: &str,
        observation: &str,
    ) -> Vec<crate::extract::KgExtractionResult> {
        vec![crate::extract::KgExtractionResult {
            index: 0,
            entities: vec![crate::extract::ExtractedEntity {
                name: name.to_string(),
                entity_type: entity_type.to_string(),
            }],
            observations: vec![crate::extract::ExtractedObservation {
                entity: name.to_string(),
                content: observation.to_string(),
            }],
            relations: Vec::new(),
        }]
    }

    fn extracted_graph(
        from: &str,
        to: &str,
        observation: &str,
    ) -> Vec<crate::extract::KgExtractionResult> {
        vec![crate::extract::KgExtractionResult {
            index: 0,
            entities: vec![
                crate::extract::ExtractedEntity {
                    name: from.to_string(),
                    entity_type: "concept".to_string(),
                },
                crate::extract::ExtractedEntity {
                    name: to.to_string(),
                    entity_type: "concept".to_string(),
                },
            ],
            observations: vec![crate::extract::ExtractedObservation {
                entity: from.to_string(),
                content: observation.to_string(),
            }],
            relations: vec![crate::extract::ExtractedRelation {
                from: from.to_string(),
                to: to.to_string(),
                relation_type: "related_to".to_string(),
                confidence: Some(0.9),
                explanation: Some("test graph relation".to_string()),
                span: None,
            }],
        }]
    }

    #[tokio::test]
    async fn entity_slice_auto_links_without_inference() {
        use std::sync::atomic::{AtomicUsize, Ordering};

        let (db, _dir) = test_db().await;
        let entity_id = db
            .store_entity(
                "Wenlan ambient scheduler",
                "concept",
                None,
                Some("test"),
                Some(1.0),
            )
            .await
            .unwrap();
        db.upsert_documents(vec![make_memory_doc(
            "mem_entity_auto_link_slice",
            "Wenlan ambient scheduler",
            "fact",
            "work",
            "agent",
        )])
        .await
        .unwrap();
        let calls = Arc::new(AtomicUsize::new(0));
        let observed = calls.clone();

        assert_eq!(
            db.run_entity_enrichment_slice_with_auto_link(2.0, move |_| {
                observed.fetch_add(1, Ordering::SeqCst);
                async move { Ok(Vec::new()) }
            })
            .await
            .unwrap(),
            1
        );

        assert_eq!(calls.load(Ordering::SeqCst), 0);
        assert_eq!(
            db.get_memory_entity_id("mem_entity_auto_link_slice")
                .await
                .unwrap()
                .as_deref(),
            Some(entity_id.as_str())
        );
        let steps = db
            .get_enrichment_steps("mem_entity_auto_link_slice")
            .await
            .unwrap();
        let linked = steps
            .iter()
            .find(|step| step.step == "entity_link")
            .expect("entity-link receipt");
        assert_eq!(linked.status, "ok");
        assert_eq!(linked.input_version, Some(1));
    }

    // I3 CHARACTERIZATION (pre-existing M2 parity gap, NOT introduced by M3g).
    //
    // The ambient Entity-enrichment lane the scheduler drives —
    // `run_entity_enrichment_slice_with_auto_link` ->
    // `commit_entity_enrichment_at_version` — writes `relations` through a raw
    // INSERT that neither consumes `relation.span` nor dual-writes to the unified
    // `edges` table. Contrast `create_relation_with_span`, which DOES dual-write a
    // payload-bearing `relates` edge. This lane is byte-identical on origin/main's
    // merge-base (M2 shipped it); the M3g Stage-A diff touches none of it.
    //
    // Why this is SAFE for M3g and reported (not silently fixed) here: a relation
    // with no `edges` row is invisible to the grounding sweep — the sweep looks up
    // `edges` by edge_id and skips a missing row, so it can never false-ground a
    // relation this lane produced. The gap is a COVERAGE limitation on the unified
    // edges store, not an M3g correctness bug, and predates this branch.
    //
    // This test LOCKS IN the current (gap) behavior. When the M2 lane is routed
    // through the payload-bearing writer upstream, this test turns RED — the signal
    // to flip the assertion to expect a `relates` edge carrying the span payload.
    #[tokio::test]
    async fn ambient_entity_sweep_writes_relation_without_edges_dual_write_pre_existing_m2_gap() {
        let (db, _dir) = test_db().await;
        db.upsert_documents(vec![make_memory_doc(
            "mem_i3_entity_sweep",
            "Alice works on ProjectX.",
            "fact",
            "work",
            "folder",
        )])
        .await
        .unwrap();

        let kg = vec![crate::extract::KgExtractionResult {
            index: 0,
            entities: vec![
                crate::extract::ExtractedEntity {
                    name: "Alice".to_string(),
                    entity_type: "person".to_string(),
                },
                crate::extract::ExtractedEntity {
                    name: "ProjectX".to_string(),
                    entity_type: "project".to_string(),
                },
            ],
            observations: Vec::new(),
            relations: vec![crate::extract::ExtractedRelation {
                from: "Alice".to_string(),
                to: "ProjectX".to_string(),
                relation_type: "works_on".to_string(),
                confidence: Some(0.9),
                explanation: None,
                span: Some("Alice works on ProjectX".to_string()),
            }],
        }];

        // Drive the *scheduler's* Entity lane (auto-link enabled). No prior
        // entities exist, so the auto-link vector search matches nothing and the
        // extraction path runs, committing the relation.
        let selected = db
            .run_entity_enrichment_slice_with_auto_link(0.05, move |_content: String| async move {
                Ok(kg)
            })
            .await
            .unwrap();
        assert_eq!(selected, 1, "the sweep processed the seeded memory");

        let conn = db.conn.lock().await;
        let relation_count: i64 = {
            let mut rows = conn
                .query(
                    "SELECT COUNT(*) FROM relations WHERE relation_type = 'works_on'",
                    (),
                )
                .await
                .unwrap();
            rows.next().await.unwrap().unwrap().get(0).unwrap()
        };
        assert_eq!(relation_count, 1, "the ambient sweep wrote the relation");

        let relates_edges: i64 = {
            let mut rows = conn
                .query("SELECT COUNT(*) FROM edges WHERE edge_type = 'relates'", ())
                .await
                .unwrap();
            rows.next().await.unwrap().unwrap().get(0).unwrap()
        };
        assert_eq!(
            relates_edges, 0,
            "PRE-EXISTING M2 GAP: the ambient Entity sweep writes a relation with no \
             edges dual-write. When the lane is routed through the payload-bearing \
             writer upstream, flip this to expect the relates edge + span payload."
        );
    }

    #[tokio::test]
    async fn linked_new_generation_repairs_entity_receipt_without_inference() {
        use std::sync::atomic::{AtomicUsize, Ordering};

        let (db, _dir) = test_db().await;
        let entity_id = db
            .store_entity(
                "Accepted revision entity",
                "concept",
                None,
                Some("test"),
                Some(1.0),
            )
            .await
            .unwrap();
        let mut doc = make_memory_doc(
            "mem_linked_new_generation",
            "Accepted revision entity",
            "fact",
            "work",
            "reconcile",
        );
        doc.entity_id = Some(entity_id.clone());
        db.upsert_documents(vec![doc]).await.unwrap();
        assert!(db
            .record_enrichment_step_at_version(
                "mem_linked_new_generation",
                "entity_extract",
                "skipped",
                None,
                1,
            )
            .await
            .unwrap());
        {
            let conn = db.conn.lock().await;
            conn.execute(
                "INSERT INTO memory_entities (memory_id, entity_id) VALUES (?1, ?2)",
                libsql::params!["mem_linked_new_generation", entity_id.as_str()],
            )
            .await
            .unwrap();
            conn.execute(
                "UPDATE memories SET version=2 WHERE source_id='mem_linked_new_generation'",
                (),
            )
            .await
            .unwrap();
        }
        let calls = Arc::new(AtomicUsize::new(0));
        let observed = calls.clone();

        assert_eq!(
            db.run_entity_enrichment_slice(move |_| {
                observed.fetch_add(1, Ordering::SeqCst);
                async move { Ok(Vec::new()) }
            })
            .await
            .unwrap(),
            1
        );
        assert_eq!(calls.load(Ordering::SeqCst), 0);
        let steps = db
            .get_enrichment_steps("mem_linked_new_generation")
            .await
            .unwrap();
        let entity = steps
            .iter()
            .find(|step| step.step == "entity_extract")
            .expect("repaired entity receipt");
        assert_eq!(entity.status, "ok");
        assert_eq!(entity.input_version, Some(2));
        assert!(db
            .get_page_growth_candidate(3, true)
            .await
            .unwrap()
            .is_some());
        assert_eq!(
            db.run_entity_enrichment_slice(|_| async move { Ok(Vec::new()) })
                .await
                .unwrap(),
            0,
            "a repaired linked generation must be terminal"
        );
    }

    #[tokio::test]
    async fn entity_reenrichment_replaces_only_source_owned_observations() {
        let (db, _dir) = test_db().await;
        {
            let conn = db.conn.lock().await;
            conn.execute(
                "INSERT INTO memories
                     (id, content, source, source_id, title, chunk_index,
                      last_modified, chunk_type, pending_revision, version)
                 VALUES ('c_observation_owner', 'first generation', 'memory',
                         'mem_observation_owner', '', 0, 1, 'text', 0, 1)",
                (),
            )
            .await
            .unwrap();
        }

        assert!(db
            .commit_entity_enrichment_at_version(
                "mem_observation_owner",
                1,
                &extracted_entity_with_observation(
                    "Shared Topic",
                    "concept",
                    "old source-owned observation",
                ),
            )
            .await
            .unwrap());
        let entity_id = db
            .search_entities_by_name("Shared Topic")
            .await
            .unwrap()
            .into_iter()
            .next()
            .unwrap()
            .id;
        db.add_observation(
            &entity_id,
            "manual observation must survive",
            Some("manual"),
            None,
        )
        .await
        .unwrap();
        {
            let conn = db.conn.lock().await;
            conn.execute(
                "UPDATE memories
                 SET content = 'second generation', version = 2
                 WHERE source_id = 'mem_observation_owner'",
                (),
            )
            .await
            .unwrap();
        }

        assert!(db
            .commit_entity_enrichment_at_version(
                "mem_observation_owner",
                2,
                &extracted_entity_with_observation(
                    "Shared Topic",
                    "concept",
                    "new source-owned observation",
                ),
            )
            .await
            .unwrap());

        let conn = db.conn.lock().await;
        let mut owned = conn
            .query(
                "SELECT content FROM observations
                 WHERE entity_id = ?1 AND source_memory_id = 'mem_observation_owner'
                 ORDER BY content",
                libsql::params![entity_id.as_str()],
            )
            .await
            .unwrap();
        let mut owned_contents = Vec::new();
        while let Some(row) = owned.next().await.unwrap() {
            owned_contents.push(row.get::<String>(0).unwrap());
        }
        assert_eq!(owned_contents, vec!["new source-owned observation"]);
        drop(owned);

        let mut manual = conn
            .query(
                "SELECT content FROM observations
                 WHERE entity_id = ?1 AND source_memory_id IS NULL",
                libsql::params![entity_id.as_str()],
            )
            .await
            .unwrap();
        assert_eq!(
            manual
                .next()
                .await
                .unwrap()
                .unwrap()
                .get::<String>(0)
                .unwrap(),
            "manual observation must survive"
        );
        assert!(manual.next().await.unwrap().is_none());
    }

