    /// Task 7 (P3): compute_distill_demotion is gentle, clamped, and recency-overridable.
    #[test]
    fn distill_demotion_is_gentle_and_recency_overridable() {
        const DAY: i64 = 86_400;
        let now = 2_000_000_000_i64;
        // Never distilled -> no demotion.
        assert_eq!(MemoryDB::compute_distill_demotion(None, now), 1.0);
        // Just distilled -> max (but still gentle) demotion, never zero.
        let fresh = MemoryDB::compute_distill_demotion(Some(now), now);
        assert!(
            (0.7..1.0).contains(&fresh),
            "fresh demotion must be gentle, got {fresh}"
        );
        // After the override window (a few days) the demotion has fully decayed back to 1.0.
        assert_eq!(
            MemoryDB::compute_distill_demotion(Some(now - 7 * DAY), now),
            1.0
        );
        // Mid-window: monotonically recovering toward 1.0.
        let d1 = MemoryDB::compute_distill_demotion(Some(now - DAY), now);
        let d3 = MemoryDB::compute_distill_demotion(Some(now - 3 * DAY), now);
        assert!(
            fresh < d1 && d1 < d3 && d3 <= 1.0,
            "demotion must recover with age: {fresh} {d1} {d3}"
        );
        // Clock skew (future stamp) clamps to neutral, never amplifies.
        assert_eq!(
            MemoryDB::compute_distill_demotion(Some(now + DAY), now),
            1.0
        );
    }

    /// Task 3 (P3): stamp_last_distilled_at sets the column on the given source_ids.
    #[tokio::test]
    async fn stamp_last_distilled_at_sets_timestamp() {
        use crate::sources::RawDocument;
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("test.db");
        let emitter: std::sync::Arc<dyn crate::EventEmitter> =
            std::sync::Arc::new(crate::NoopEmitter);
        let db = MemoryDB::new(&db_path, emitter).await.unwrap();
        db.upsert_documents(vec![RawDocument {
            source: "memory".into(),
            source_id: "mem_a".into(),
            title: "mem_a".into(),
            content: "a fact".into(),
            memory_type: Some("fact".into()),
            last_modified: 1_700_000_000,
            ..Default::default()
        }])
        .await
        .unwrap();

        let now = 1_700_000_500_i64;
        db.stamp_last_distilled_at(&["mem_a".to_string()], now)
            .await
            .unwrap();

        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT last_distilled_at FROM memories WHERE source_id = 'mem_a'",
                (),
            )
            .await
            .unwrap();
        let got: Option<i64> = rows.next().await.unwrap().unwrap().get(0).unwrap();
        assert_eq!(got, Some(now));
    }

    /// decision-6 provenance: a folder-ingested document upserted with a file
    /// `content_hash` + `source_agent='folder'` stamps that hash and agent onto
    /// EVERY chunk row of the file, and the chunker's byte offsets persist.
    #[tokio::test]
    async fn provenance_content_hash_stamps_all_document_chunks() {
        let (db, _dir) = test_db().await;

        // Multi-paragraph content large enough to split into >1 chunk under both
        // the char-fallback (512) and token-aware (~512 tok) chunker modes.
        let para = "Wenlan is a local-first personal agent memory layer where \
            agents write what they learn and humans curate the knowledge base. \
            The daemon owns all business logic and data while thin clients talk HTTP. ";
        let content = para.repeat(40);

        let doc = RawDocument {
            source: "memory".into(),
            source_id: "src_a::/notes/wenlan.txt".into(),
            title: "wenlan.txt".into(),
            content,
            source_agent: Some("folder".into()),
            content_hash: Some("abc".into()),
            last_modified: 1_700_000_000,
            ..Default::default()
        };

        let n = db.upsert_documents(vec![doc]).await.unwrap();
        assert!(n >= 2, "content should split into multiple chunks, got {n}");

        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT content_hash, source_agent, byte_start FROM memories \
                 WHERE source = 'memory' AND source_id = 'src_a::/notes/wenlan.txt'",
                (),
            )
            .await
            .unwrap();
        let mut seen = 0;
        while let Some(r) = rows.next().await.unwrap() {
            seen += 1;
            assert_eq!(
                r.get::<Option<String>>(0).unwrap().as_deref(),
                Some("abc"),
                "every chunk row must carry the file content_hash"
            );
            assert_eq!(
                r.get::<Option<String>>(1).unwrap().as_deref(),
                Some("folder"),
                "every chunk row must carry source_agent='folder'"
            );
            assert!(
                r.get::<Option<i64>>(2).unwrap().is_some(),
                "document chunks must persist non-null byte_start"
            );
        }
        assert_eq!(seen, n, "every upserted chunk row should be returned");
    }

    #[tokio::test]
    async fn lint_review_enqueue_rejects_invalid_contracts_and_non_equivalent_collisions() {
        let (db, _dir) = test_db().await;
        let occurrence = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        let review_id = format!("lint_review_{occurrence}");
        let source_ids = vec!["mem_a".to_string()];
        let payload_for = |issue: &str, owners: &[String]| {
            serde_json::json!({
                "action": "lint_repair_review",
                "check_id": "identity.memory_state_integrity",
                "occurrence_digest": occurrence,
                "owner_binding_digest": crate::repair::lint_review_owner_binding_digest(
                    &wenlan_types::repair::RepairDigest::parse(occurrence).unwrap(),
                    owners,
                )
                .unwrap(),
                "issue": issue,
                "choices": ["confirm", "unpin"],
                "suggested_research_queries": []
            })
            .to_string()
        };
        let payload = payload_for("ambiguous state", &source_ids);

        assert!(db
            .insert_refinement_proposal(
                &review_id,
                "lint_repair_review",
                &source_ids,
                Some(&payload),
                1.0,
            )
            .await
            .is_err());
        assert!(db
            .insert_lint_review_if_absent(&review_id, &source_ids, "not-json")
            .await
            .is_err());
        assert!(db
            .insert_lint_review_if_absent(
                "lint_review_bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",
                &source_ids,
                &payload,
            )
            .await
            .is_err());
        assert!(db
            .insert_lint_review_if_absent(
                &review_id,
                &source_ids,
                &payload_for("ambiguous state", &["mem_b".to_string()]),
            )
            .await
            .is_err());

        assert!(db
            .insert_lint_review_if_absent(&review_id, &source_ids, &payload)
            .await
            .unwrap());
        assert!(db
            .insert_lint_review_if_absent(
                &review_id,
                &source_ids,
                &payload_for("different issue", &source_ids),
            )
            .await
            .is_err());

        db.conn
            .lock()
            .await
            .execute(
                "UPDATE refinement_queue
                    SET action = 'relation_conflict'
                  WHERE id = ?1",
                libsql::params![review_id.clone()],
            )
            .await
            .unwrap();
        assert!(db
            .insert_lint_review_if_absent(&review_id, &source_ids, &payload)
            .await
            .is_err());

        db.conn
            .lock()
            .await
            .execute(
                "UPDATE refinement_queue
                    SET action = 'lint_repair_review',
                        source_ids = '[\"mem_b\"]'
                  WHERE id = ?1",
                libsql::params![review_id.clone()],
            )
            .await
            .unwrap();
        assert!(db
            .insert_lint_review_if_absent(&review_id, &source_ids, &payload)
            .await
            .is_err());
    }

    async fn create_repair_open_probe(dir: &std::path::Path, schema_version: u32) {
        std::fs::create_dir_all(dir).unwrap();
        let db_file = dir.join("origin_memory.db");
        let database = libsql::Builder::new_local(db_file.to_str().unwrap())
            .build()
            .await
            .unwrap();
        let connection = database.connect().unwrap();
        connection
            .execute_batch(&format!(
                "PRAGMA user_version = {schema_version}; \
                 CREATE TABLE repair_open_probe (value TEXT NOT NULL);"
            ))
            .await
            .unwrap();
        // A database claiming the current schema version must actually carry
        // the parity counter and its integrity guards -- `open_for_repair`
        // refuses one that does not, because that path skips migrations and
        // then exposes the approved apply endpoint. Stamping the version
        // without them would make this fixture a shape no real database of
        // that version has.
        if schema_version == SCHEMA_VERSION {
            connection
                .execute_batch(PARITY_INPUT_STATE_TABLE_DDL)
                .await
                .unwrap();
            for (_, canonical) in PARITY_GUARD_TRIGGERS {
                connection
                    .execute_batch(&format!("{canonical};"))
                    .await
                    .unwrap();
            }
            // Seeded after the guards, so the fixture also proves the seed the
            // real migration writes is one the guards accept.
            connection
                .execute_batch(
                    "INSERT INTO community_parity_input_state
                         (singleton, generation, relevant_spaces_digest)
                     VALUES (1, 0, '');",
                )
                .await
                .unwrap();
        }
    }

