    /// The parity oracle must be STRUCTURAL, not set-only: a live edge whose
    /// stored endpoint was corrupted in place -- WITHOUT changing its
    /// content-addressed `edge_id` -- keeps the id set identical yet feeds a
    /// wrong endpoint to every reader (`detect_communities` reads `dst_id`
    /// directly). A set-difference oracle would report this clean; the
    /// structural-column diff must flag it as drift.
    #[tokio::test]
    async fn reconcile_detects_corrupt_endpoint() {
        let (db, _dir) = test_db().await;
        let e1 = db
            .create_entity("Alice", "person", Some("space_a"))
            .await
            .unwrap();
        let e2 = db
            .create_entity("Bob", "person", Some("space_a"))
            .await
            .unwrap();
        // A third entity in the SAME space: a real, fence-legal endpoint to
        // silently drift the edge onto (repointing to a non-existent id would
        // instead trip `edges_space_fence`, which is a different guard).
        let e3 = db
            .create_entity("Carol", "person", Some("space_a"))
            .await
            .unwrap();
        db.create_relation(&e1, &e2, "knows", None, None, None, None)
            .await
            .unwrap();
        assert_eq!(db.reconcile_edges_parity().await.unwrap().drift_count, 0);

        // Corrupt the STORED dst endpoint in place, leaving `edge_id` untouched:
        // the legacy relation still implies (e1 -> e2), but the live edge now
        // points at e3 -- a real, same-space, but WRONG endpoint. The id set is
        // unchanged (no missing/extra), yet every reader now sees e1 -> e3.
        {
            let conn = db.conn.lock().await;
            let affected = conn
                .execute(
                    "UPDATE edges SET dst_id = ?1 \
                     WHERE edge_type = 'relates' AND dst_id = ?2 AND valid_until IS NULL",
                    libsql::params![e3.clone(), e2.clone()],
                )
                .await
                .unwrap();
            assert_eq!(affected, 1, "exactly one live relates edge to corrupt");
        }
        let report = db.reconcile_edges_parity().await.unwrap();
        assert!(
            report.corrupt_count >= 1,
            "an endpoint-corrupted row is corrupt, not clean (report={report:?})"
        );
        assert_eq!(
            report.missing_count, 0,
            "the id set is unchanged: not a missing edge"
        );
        assert_eq!(
            report.extra_count, 0,
            "the id set is unchanged: not an extra edge"
        );
        assert!(report.drift_count >= 1);
    }

    /// Stage-(c) wiring proof: `detect_communities` must produce the IDENTICAL
    /// entity->community assignment whether it reads the legacy `relations`
    /// store (cutover OFF) or the `edges` `relates` adjacency (cutover ON with
    /// clean parity). Byte-identical, not merely close.
    #[tokio::test]
    async fn detect_communities_edges_path_matches_legacy() {
        let (db, _dir) = test_db().await;
        // Two disjoint pairs -> two communities.
        let a = db
            .create_entity("A", "person", Some("space_a"))
            .await
            .unwrap();
        let b = db
            .create_entity("B", "person", Some("space_a"))
            .await
            .unwrap();
        let c = db
            .create_entity("C", "person", Some("space_a"))
            .await
            .unwrap();
        let d = db
            .create_entity("D", "person", Some("space_a"))
            .await
            .unwrap();
        db.create_relation(&a, &b, "knows", None, None, None, None)
            .await
            .unwrap();
        db.create_relation(&c, &d, "knows", None, None, None, None)
            .await
            .unwrap();

        async fn community_map(db: &MemoryDB) -> std::collections::BTreeMap<String, i64> {
            let conn = db.conn.lock().await;
            let mut rows = conn
                .query("SELECT id, community_id FROM entities ORDER BY id", ())
                .await
                .unwrap();
            let mut m = std::collections::BTreeMap::new();
            while let Some(row) = rows.next().await.unwrap() {
                m.insert(
                    row.get::<String>(0).unwrap(),
                    row.get::<i64>(1).unwrap_or(-1),
                );
            }
            m
        }

        // Cutover OFF (default) -> legacy relations path.
        db.detect_communities().await.unwrap();
        let legacy_map = community_map(&db).await;

        // Prove parity, enable the consumer -> edges path.
        assert_eq!(db.reconcile_edges_parity().await.unwrap().drift_count, 0);
        db.set_reader_cutover("communities", true).await.unwrap();
        {
            let conn = db.conn.lock().await;
            assert!(MemoryDB::reader_uses_edges(&conn, "communities")
                .await
                .unwrap());
        }
        db.detect_communities().await.unwrap();
        let edges_map = community_map(&db).await;

        assert_eq!(
            legacy_map, edges_map,
            "the edges-backed community detection must be byte-identical to legacy"
        );
        // And it actually found two communities (non-degenerate).
        let distinct: std::collections::BTreeSet<i64> = edges_map.values().copied().collect();
        assert_eq!(
            distinct.len(),
            2,
            "two disjoint pairs must yield two communities"
        );
    }

    /// D6 (M2 review fork-#2 verdict (a)): once the "communities" consumer
    /// flips to reading `edges`, a `lineage='legacy'` edge whose endpoints
    /// are cross-space must NOT contribute to adjacency -- else two spaces'
    /// entities could merge into one community through a legacy link the
    /// fence never validated (the fence exempts `lineage='legacy'` at write
    /// time). The unflipped (legacy `relations`) path is untouched: it still
    /// carries the cross-space link, since D6 is a read-side exclusion
    /// scoped to the flipped `edges` read only. A same-space legacy edge
    /// must still contribute when flipped -- the exclusion is
    /// cross-space-scoped, not all-legacy.
    #[tokio::test]
    async fn detect_communities_flipped_excludes_cross_space_legacy_edge() {
        let (db, _dir) = test_db().await;
        let a = db
            .create_entity("A", "person", Some("space_a"))
            .await
            .unwrap();
        let b = db
            .create_entity("B", "person", Some("space_b"))
            .await
            .unwrap();

        // Legacy `relations` row (the unflipped read source) + its
        // `lineage='legacy'` edge twin, inserted directly via SQL (the fence
        // exempts `lineage='legacy'`) -- mirrors what a real cross-space
        // backfill/dual-write produces for a cross-space `relates` pair.
        {
            let conn = db.conn.lock().await;
            conn.execute(
                "INSERT INTO relations (id, from_entity, to_entity, relation_type, created_at) \
                 VALUES ('rel_cross', ?1, ?2, 'knows', 0)",
                libsql::params![a.clone(), b.clone()],
            )
            .await
            .unwrap();
            MemoryDB::insert_backfilled_edge(
                &conn, "relates", "entity", &a, "entity", &b, "knows", "legacy", "space_a", "test",
            )
            .await
            .unwrap();
        }

        async fn community_map(db: &MemoryDB) -> std::collections::BTreeMap<String, i64> {
            let conn = db.conn.lock().await;
            let mut rows = conn
                .query("SELECT id, community_id FROM entities ORDER BY id", ())
                .await
                .unwrap();
            let mut m = std::collections::BTreeMap::new();
            while let Some(row) = rows.next().await.unwrap() {
                m.insert(
                    row.get::<String>(0).unwrap(),
                    row.get::<i64>(1).unwrap_or(-1),
                );
            }
            m
        }

        // Unflipped (legacy path): behavior unchanged -- the cross-space
        // relation still contributes; A and B land in one community.
        db.detect_communities().await.unwrap();
        let legacy_map = community_map(&db).await;
        assert_eq!(
            legacy_map[&a], legacy_map[&b],
            "legacy path must be unchanged: the cross-space relation still merges A and B"
        );

        // Flip: prove parity, enable the consumer.
        assert_eq!(db.reconcile_edges_parity().await.unwrap().drift_count, 0);
        db.set_reader_cutover("communities", true).await.unwrap();
        {
            let conn = db.conn.lock().await;
            assert!(MemoryDB::reader_uses_edges(&conn, "communities")
                .await
                .unwrap());
        }

        // Flipped (edges path): the cross-space legacy edge must NOT
        // contribute -- A and B must NOT land in one community via it.
        db.detect_communities().await.unwrap();
        let flipped_map = community_map(&db).await;
        assert_ne!(
            flipped_map[&a], flipped_map[&b],
            "flipped read must exclude the cross-space legacy edge: A and B must not merge"
        );

        // A same-space legacy edge DOES still contribute when flipped -- the
        // exclusion is cross-space-scoped, not all-legacy.
        let c = db
            .create_entity("C", "person", Some("space_a"))
            .await
            .unwrap();
        let d = db
            .create_entity("D", "person", Some("space_a"))
            .await
            .unwrap();
        {
            let conn = db.conn.lock().await;
            conn.execute(
                "INSERT INTO relations (id, from_entity, to_entity, relation_type, created_at) \
                 VALUES ('rel_same', ?1, ?2, 'knows', 0)",
                libsql::params![c.clone(), d.clone()],
            )
            .await
            .unwrap();
            MemoryDB::insert_backfilled_edge(
                &conn, "relates", "entity", &c, "entity", &d, "knows", "legacy", "space_a", "test",
            )
            .await
            .unwrap();
        }
        assert_eq!(db.reconcile_edges_parity().await.unwrap().drift_count, 0);
        db.detect_communities().await.unwrap();
        let flipped_map2 = community_map(&db).await;
        assert_eq!(
            flipped_map2[&c], flipped_map2[&d],
            "a same-space legacy edge must still contribute when flipped"
        );
    }

    /// §6.9 restore drill: an online backup is a sound, INDEPENDENT restore
    /// point. Seed (including an EMBEDDED row so the DiskANN vector index carries
    /// real content -- the shadow tables a naive `VACUUM INTO` would reorder),
    /// back up to a separate dir, then REALLY restore: close the source, delete
    /// the original db + WAL/SHM sidecars, copy the snapshot back ONTO the
    /// canonical source path, reopen it there, and confirm integrity + row
    /// counts + a working vector query all survive.
    #[tokio::test]
    async fn online_backup_is_a_restorable_snapshot() {
        let (db, _dir) = test_db().await;
        seed_memory_with_source_id_and_space(&db, "mem_backup", "precious", "space_a").await;
        // An embedded row so `memories_vec_idx` (DiskANN) has real content to
        // carry across backup+restore -- integrity_check alone never exercises a
        // lookup, so a probe query is the functional proof.
        let vec_literal = format!("[{}]", vec!["0.05"; 768].join(","));
        {
            let conn = db.conn.lock().await;
            conn.execute(
                "INSERT INTO memories (id, content, source, source_id, title, chunk_index, \
                    last_modified, chunk_type, source_agent, space, confidence, confirmed, \
                    memory_type, pending_revision, embedding) \
                 VALUES ('mem_vec', 'v', 'memory', 'mem_vec', 't', 0, 1712707200, 'text', NULL, \
                    'space_a', 1.0, 0, 'fact', 0, vector32(?1))",
                libsql::params![vec_literal.clone()],
            )
            .await
            .unwrap();
        }

        // Resolve the live source path (to restore back ONTO it) and snapshot to
        // a SEPARATE directory.
        let source_path = {
            let conn = db.conn.lock().await;
            MemoryDB::main_db_path(&conn).await.unwrap()
        };
        let source_dir = source_path.parent().unwrap().to_path_buf();
        let backup_dir = tempdir().unwrap();
        let dest = backup_dir.path().join("snapshot.db");
        let receipt = db.online_backup(&dest).await.unwrap();
        assert!(
            receipt.integrity_ok,
            "the snapshot must pass integrity_check"
        );
        assert!(receipt.backup_pages > 0, "the snapshot must be non-empty");
        assert_eq!(
            receipt.source_pages, receipt.backup_pages,
            "a physical copy must have the same page count as the source"
        );

        // REALLY restore: close the source connection, delete the original db +
        // WAL/SHM, copy the snapshot onto the canonical source path, reopen.
        drop(db);
        for suffix in ["", "-wal", "-shm"] {
            let mut p = source_path.clone().into_os_string();
            p.push(suffix);
            let p = std::path::PathBuf::from(p);
            if p.exists() {
                std::fs::remove_file(&p).unwrap();
            }
        }
        assert!(
            !source_path.exists(),
            "the original db must be gone before restore"
        );
        std::fs::copy(&dest, &source_path).unwrap();

        let restored = MemoryDB::open_for_repair(&source_dir).await.unwrap();
        let rconn = restored.conn.lock().await;

        // integrity of the restored file.
        let integrity: String = {
            let mut rows = rconn.query("PRAGMA integrity_check", ()).await.unwrap();
            rows.next().await.unwrap().unwrap().get(0).unwrap()
        };
        assert_eq!(integrity, "ok", "restored db integrity must be clean");

        // both seeded rows survived.
        let count: i64 = {
            let mut rows = rconn
                .query(
                    "SELECT COUNT(*) FROM memories WHERE source_id IN ('mem_backup', 'mem_vec')",
                    (),
                )
                .await
                .unwrap();
            rows.next().await.unwrap().unwrap().get(0).unwrap()
        };
        assert_eq!(
            count, 2,
            "the restored snapshot must still hold the pre-backup memories"
        );

        // vector index usable: a DiskANN top-k query executes and returns the
        // embedded row -- proves the vector shadow tables survived the copy.
        let hit: Option<String> = {
            let mut rows = rconn
                .query(
                    "SELECT m.source_id \
                     FROM vector_top_k('memories_vec_idx', vector32(?1), 5) AS vt \
                     JOIN memories m ON m.rowid = vt.id \
                     WHERE m.source_id = 'mem_vec'",
                    libsql::params![vec_literal],
                )
                .await
                .unwrap();
            rows.next()
                .await
                .unwrap()
                .map(|r| r.get::<String>(0).unwrap())
        };
        assert_eq!(
            hit.as_deref(),
            Some("mem_vec"),
            "the DiskANN vector index must be queryable after restore"
        );
    }

    /// §6.9 self-backup guard: passing the LIVE db path as the backup dest must
    /// be rejected BEFORE the dest-cleanup delete -- otherwise `online_backup`
    /// would delete its own source. The source must be byte-untouched.
    #[tokio::test]
    async fn online_backup_refuses_to_overwrite_the_live_db() {
        let (db, _dir) = test_db().await;
        seed_memory_with_source_id_and_space(&db, "mem_live", "keep", "space_a").await;
        let source_path = {
            let conn = db.conn.lock().await;
            MemoryDB::main_db_path(&conn).await.unwrap()
        };
        let before = std::fs::metadata(&source_path).unwrap().len();

        let err = db.online_backup(&source_path).await.unwrap_err();
        assert!(
            format!("{err}").contains("refusing to overwrite the source"),
            "online_backup(live_db) must be rejected, got: {err}"
        );

        // The source is untouched: still present, byte-unchanged, still holds the row.
        assert!(source_path.exists(), "the live db must not be deleted");
        assert_eq!(
            before,
            std::fs::metadata(&source_path).unwrap().len(),
            "the live db file must be byte-unchanged by a rejected self-backup"
        );
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT COUNT(*) FROM memories WHERE source_id = 'mem_live'",
                (),
            )
            .await
            .unwrap();
        let n: i64 = rows.next().await.unwrap().unwrap().get(0).unwrap();
        assert_eq!(n, 1, "the live db row must survive a rejected self-backup");
    }

    /// M4 Gate 1.4 mutex-hold receipt at the authored §6.5 corpus scale.
    /// Seeds 100k memories, 5k pages, and the three-space grounded projection,
    /// then times 20 indexed subgraph reads while keeping projection and
    /// partitioning structurally outside the connection guard.
    #[tokio::test]
    #[ignore]
    async fn m4_grounded_projection_select_mutex_receipt() {
        use crate::community_partition::{
            full_partition, project_grounded_relates, PartitionConfig, ProjectionConfig,
            ProjectionInputEdge,
        };
        use std::time::{Duration, Instant};

        const MEMORIES: usize = 100_000;
        const PAGES: usize = 5_000;
        const SPACES: usize = 3;
        const CLUSTERS_PER_SPACE: usize = 8;
        const NODES_PER_CLUSTER: usize = 256;
        const FIRINGS: usize = 20;

        let (db, _dir) = test_db().await;
        let seed_started = Instant::now();
        {
            let conn = db.conn.lock().await;
            conn.execute("BEGIN", ()).await.unwrap();
            for i in 0..MEMORIES {
                conn.execute(
                    "INSERT INTO memories (id, content, source, source_id, title, chunk_index, \
                        last_modified, chunk_type, source_agent, space, confidence, confirmed, \
                        memory_type, pending_revision) \
                     VALUES (?1, 'c', 'memory', ?1, 't', 0, 1712707200, 'text', NULL, ?2, \
                        1.0, 0, 'fact', 0)",
                    libsql::params![format!("m4_mem_{i}"), format!("space-{}", i % SPACES)],
                )
                .await
                .unwrap();
            }
            for page in 0..PAGES {
                let space = format!("space-{}", page % SPACES);
                conn.execute(
                    "INSERT INTO pages (id, title, content, created_at, last_compiled, \
                        last_modified, space, workspace) \
                     VALUES (?1, 't', 'c', '2024-01-01T00:00:00Z', \
                        '2024-01-01T00:00:00Z', '2024-01-01T00:00:00Z', ?2, ?2)",
                    libsql::params![format!("m4_page_{page}"), space],
                )
                .await
                .unwrap();
            }
            for space in 0..SPACES {
                conn.execute(
                    "INSERT INTO provenance_roots (root_id, identity_version, identity_digest, \
                        root_kind, independence_group_id, status, created_at) \
                     VALUES (?1, 1, ?2, 'generated', ?3, 'active', 1712707200)",
                    libsql::params![
                        format!("m4-root-{space}"),
                        format!("m4-root-digest-{space}"),
                        format!("m4-space-{space}")
                    ],
                )
                .await
                .unwrap();
                for cluster in 0..CLUSTERS_PER_SPACE {
                    for node in 0..NODES_PER_CLUSTER {
                        let entity_id =
                            format!("space-{space}-cluster-{cluster:02}-node-{node:03}");
                        conn.execute(
                            "INSERT INTO entities (id, name, entity_type, space, created_at, updated_at) \
                             VALUES (?1, ?1, 'concept', ?2, 1712707200, 1712707200)",
                            libsql::params![entity_id, format!("space-{space}")],
                        )
                        .await
                        .unwrap();
                    }
                }

                let mut edge_index = 0usize;
                for cluster in 0..CLUSTERS_PER_SPACE {
                    for node in 0..NODES_PER_CLUSTER {
                        for offset in 1..=3 {
                            conn.execute(
                                "INSERT INTO edges (edge_id, src_id, src_kind, dst_id, dst_kind, \
                                    edge_type, lineage, grounded, root_id, space, created_at) \
                                 VALUES (?1, ?2, 'entity', ?3, 'entity', 'relates', 'assertion', \
                                    1, ?4, ?5, 1712707200)",
                                libsql::params![
                                    format!("m4-space-{space}-edge-{edge_index:06}"),
                                    format!("space-{space}-cluster-{cluster:02}-node-{node:03}"),
                                    format!(
                                        "space-{space}-cluster-{cluster:02}-node-{:03}",
                                        (node + offset) % NODES_PER_CLUSTER
                                    ),
                                    format!("m4-root-{space}"),
                                    format!("space-{space}")
                                ],
                            )
                            .await
                            .unwrap();
                            edge_index += 1;
                        }
                    }
                    if cluster + 1 < CLUSTERS_PER_SPACE {
                        conn.execute(
                            "INSERT INTO edges (edge_id, src_id, src_kind, dst_id, dst_kind, \
                                edge_type, lineage, grounded, root_id, space, created_at) \
                             VALUES (?1, ?2, 'entity', ?3, 'entity', 'relates', 'assertion', \
                                1, ?4, ?5, 1712707200)",
                            libsql::params![
                                format!("m4-space-{space}-edge-{edge_index:06}"),
                                format!("space-{space}-cluster-{cluster:02}-node-000"),
                                format!("space-{space}-cluster-{:02}-node-000", cluster + 1),
                                format!("m4-root-{space}"),
                                format!("space-{space}")
                            ],
                        )
                        .await
                        .unwrap();
                        edge_index += 1;
                    }
                }
                assert_eq!(edge_index, 6_151);
            }
            conn.execute("COMMIT", ()).await.unwrap();
            conn.execute("ANALYZE edges", ()).await.unwrap();
        }
        let seed_secs = seed_started.elapsed().as_secs_f64();

        {
            let conn = db.conn.lock().await;
            let mut plan = conn
                .query(
                    "EXPLAIN QUERY PLAN \
                     SELECT edge_id, src_id, dst_id FROM edges \
                     WHERE space = ?1 AND edge_type = 'relates' \
                       AND valid_until IS NULL AND grounded = 1 \
                       AND src_kind = 'entity' AND dst_kind = 'entity'",
                    libsql::params!["space-0"],
                )
                .await
                .unwrap();
            let mut details = Vec::new();
            while let Some(row) = plan.next().await.unwrap() {
                details.push(row.get::<String>(3).unwrap());
            }
            assert!(
                details
                    .iter()
                    .any(|detail| detail.contains("idx_edges_active_grounded_space_type")),
                "Gate 1.4 SELECT must use the partial active-grounded index: {details:?}"
            );
        }

        let mut holds = Vec::with_capacity(FIRINGS);
        let mut last_projection = Vec::new();
        for firing in 0..FIRINGS {
            let space = format!("space-{}", firing % SPACES);
            let hold_started = Instant::now();
            let conn = db.conn.lock().await;
            let mut rows = conn
                .query(
                    "SELECT edge_id, src_id, dst_id FROM edges \
                     WHERE space = ?1 AND edge_type = 'relates' \
                       AND valid_until IS NULL AND grounded = 1 \
                       AND src_kind = 'entity' AND dst_kind = 'entity'",
                    libsql::params![space],
                )
                .await
                .unwrap();
            let mut projection = Vec::with_capacity(6_151);
            while let Some(row) = rows.next().await.unwrap() {
                projection.push(ProjectionInputEdge::new(
                    row.get::<String>(0).unwrap(),
                    row.get::<String>(1).unwrap(),
                    row.get::<String>(2).unwrap(),
                ));
            }
            drop(rows);
            drop(conn);
            holds.push(hold_started.elapsed());
            assert_eq!(projection.len(), 6_151);
            last_projection = projection;
        }

        // Structural bite for the gate-stage path: projection and partition
        // begin only after the connection guard above has been dropped.
        let graph = project_grounded_relates(&last_projection, ProjectionConfig::default());
        let partition =
            full_partition(&graph, PartitionConfig::default()).expect("outside-lock partition");
        assert_eq!(partition.membership().len(), 2_048);

        holds.sort_unstable();
        let p95 = holds[(holds.len() * 95).div_ceil(100) - 1];
        let max = *holds.last().unwrap();
        assert!(
            p95 <= Duration::from_millis(500),
            "Gate 1.4 mutex p95 {p95:?} exceeds 500ms"
        );
        assert!(
            max <= Duration::from_secs(2),
            "Gate 1.4 hard fail: mutex max {max:?} exceeds 2s"
        );
        eprintln!(
            "[m4_db_gate_receipt] memories={MEMORIES} pages={PAGES} spaces={SPACES} \
             edges={} participants={} firings={FIRINGS} seed_secs={seed_secs:.3} \
             mutex_p95_ms={:.3} mutex_max_ms={:.3}",
            SPACES * 6_151,
            SPACES * CLUSTERS_PER_SPACE * NODES_PER_CLUSTER,
            p95.as_secs_f64() * 1_000.0,
            max.as_secs_f64() * 1_000.0,
        );
    }

    /// §6.5-scale acceptance (100k memories / 5k pages). Manual-only (needs
    /// minutes + hundreds of MB); run with:
    ///   RUSTC_WRAPPER= cargo test -p wenlan-core --lib \
    ///     db::tests::bench_reconcile_parity_at_scale -- --ignored --nocapture
    /// Seeds 100k memories, 5k pages, 100k page->memory `page_sources` (one
    /// cite each), backfills, then times reconcile + the gate check and asserts
    /// drift 0 at scale.
    #[tokio::test]
    #[ignore]
    async fn bench_reconcile_parity_at_scale() {
        use std::time::Instant;
        const MEMORIES: usize = 100_000;
        const PAGES: usize = 5_000;
        const CITES_PER_PAGE: usize = MEMORIES / PAGES; // 20

        let (db, _dir) = test_db().await;

        let t_seed = Instant::now();
        {
            let conn = db.conn.lock().await;
            conn.execute("BEGIN", ()).await.unwrap();
            for i in 0..MEMORIES {
                conn.execute(
                    "INSERT INTO memories (id, content, source, source_id, title, chunk_index, \
                        last_modified, chunk_type, source_agent, space, confidence, confirmed, \
                        memory_type, pending_revision) \
                     VALUES (?1, 'c', 'memory', ?1, 't', 0, 1712707200, 'text', NULL, 'space_a', 1.0, 0, 'fact', 0)",
                    libsql::params![format!("mem_{i}")],
                )
                .await
                .unwrap();
            }
            for p in 0..PAGES {
                conn.execute(
                    "INSERT INTO pages (id, title, content, created_at, last_compiled, last_modified, space, workspace) \
                     VALUES (?1, 't', 'c', '2024-01-01T00:00:00Z', '2024-01-01T00:00:00Z', '2024-01-01T00:00:00Z', 'space_a', 'space_a')",
                    libsql::params![format!("page_{p}")],
                )
                .await
                .unwrap();
                for k in 0..CITES_PER_PAGE {
                    let mem = p * CITES_PER_PAGE + k;
                    conn.execute(
                        "INSERT INTO page_sources (page_id, memory_source_id, linked_at, link_reason) \
                         VALUES (?1, ?2, 1712707200, 'bench')",
                        libsql::params![format!("page_{p}"), format!("mem_{mem}")],
                    )
                    .await
                    .unwrap();
                }
            }
            conn.execute("COMMIT", ()).await.unwrap();
        }
        let seed_secs = t_seed.elapsed().as_secs_f64();

        let t_backfill = Instant::now();
        rerun_migration_81(&db).await;
        let backfill_secs = t_backfill.elapsed().as_secs_f64();

        let t_reconcile = Instant::now();
        let report = db.reconcile_edges_parity().await.unwrap();
        let reconcile_secs = t_reconcile.elapsed().as_secs_f64();

        db.set_reader_cutover("communities", true).await.unwrap();
        let t_gate = Instant::now();
        let flip = {
            let conn = db.conn.lock().await;
            MemoryDB::reader_uses_edges(&conn, "communities")
                .await
                .unwrap()
        };
        let gate_ms = t_gate.elapsed().as_secs_f64() * 1000.0;

        eprintln!(
            "[bench §6.5] memories={MEMORIES} pages={PAGES} cites={}",
            MEMORIES
        );
        eprintln!("[bench §6.5] seed={seed_secs:.1}s backfill={backfill_secs:.1}s reconcile={reconcile_secs:.2}s gate={gate_ms:.2}ms");
        eprintln!(
            "[bench §6.5] expected_active={} actual_active={} drift={}",
            report.expected_active, report.actual_active, report.drift_count
        );
        assert_eq!(report.drift_count, 0, "parity must hold at §6.5 scale");
        assert_eq!(
            report.expected_active, MEMORIES,
            "one cites edge per memory"
        );
        assert!(flip, "gate opens on a clean, current watermark (communities has no edges but the predicate still holds)");
    }

    /// M3g Gate 2.2 (scale demo) + Gate 3 (foreground-latency ceiling) at §6.5
    /// scale. Manual-only (needs minutes + hundreds of MB, but NO GPU — the
    /// entailment provider is a stub). Run with:
    ///   RUSTC_WRAPPER= cargo test -p wenlan-core --lib \
    ///     db::tests::edge_grounding_scale_and_latency_bench -- --ignored --nocapture
    ///
    /// Seeds the M2 §6.5 corpus (100k folder memories / 5k pages / 100k page
    /// cites) via raw batched SQL, then a `relates` backlog of BACKLOG
    /// folder-sourced grounded=0 edges (payload=NULL, entailment-only) through the
    /// REAL relation path, and drives `run_edge_grounding_tick` with an always-
    /// entail stub. Asserts, per `docs/plans/2026-07-25-m3g-gate-criteria.md`:
    ///   Gate 2.2 — every tick within bounds (≤50 scanned, ≤25 entailment calls),
    ///     promotion monotone (no `grounded=1 → 0`), a drained re-run promotes 0
    ///     (idempotent);
    ///   Gate 3  — per-tick cumulative DB-mutex hold p95 ≤ 500ms over ≥20 full
    ///     ticks, no single tick > 2s.
    /// The structural "no LLM inside a transaction" guard is the companion
    /// hermetic test `edge_grounding::tests::sweep_holds_no_db_mutex_across_entailment`.
    #[tokio::test]
    #[ignore]
    async fn edge_grounding_scale_and_latency_bench() {
        use std::time::Instant;
        const MEMORIES: usize = 100_000;
        const PAGES: usize = 5_000;
        const CITES_PER_PAGE: usize = MEMORIES / PAGES; // 20
        const BACKLOG: usize = 750; // 30 full ticks of 25 — well past the 20-tick floor

        let (db, _dir) = test_db().await;

        // --- seed the §6.5 corpus (raw batched SQL, one BEGIN/COMMIT) ----------
        let t_seed = Instant::now();
        {
            let conn = db.conn.lock().await;
            conn.execute("BEGIN", ()).await.unwrap();
            for i in 0..MEMORIES {
                conn.execute(
                    "INSERT INTO memories (id, content, source, source_id, title, chunk_index, \
                        last_modified, chunk_type, source_agent, space, confidence, confirmed, \
                        memory_type, pending_revision) \
                     VALUES (?1, ?2, 'memory', ?1, 't', 0, 1712707200, 'text', 'folder', 'space_a', 1.0, 1, 'fact', 0)",
                    libsql::params![format!("mem_{i}"), format!("Folder document {i}.")],
                )
                .await
                .unwrap();
            }
            for p in 0..PAGES {
                conn.execute(
                    "INSERT INTO pages (id, title, content, created_at, last_compiled, last_modified, space, workspace) \
                     VALUES (?1, 't', 'c', '2024-01-01T00:00:00Z', '2024-01-01T00:00:00Z', '2024-01-01T00:00:00Z', 'space_a', 'space_a')",
                    libsql::params![format!("page_{p}")],
                )
                .await
                .unwrap();
                for k in 0..CITES_PER_PAGE {
                    let mem = p * CITES_PER_PAGE + k;
                    conn.execute(
                        "INSERT INTO page_sources (page_id, memory_source_id, linked_at, link_reason) \
                         VALUES (?1, ?2, 1712707200, 'bench')",
                        libsql::params![format!("page_{p}"), format!("mem_{mem}")],
                    )
                    .await
                    .unwrap();
                }
            }
            conn.execute("COMMIT", ()).await.unwrap();
        }
        let seed_secs = t_seed.elapsed().as_secs_f64();

        // --- seed the relates backlog through the REAL relation path -----------
        // Each: a folder-sourced grounded=0 `relates` edge, payload=NULL
        // (entailment-only), whose source memory (mem_i) carries live content.
        let t_backlog = Instant::now();
        for i in 0..BACKLOG {
            let from = db
                .create_entity(&format!("bench_from_{i}"), "concept", Some("space_a"))
                .await
                .unwrap();
            let to = db
                .create_entity(&format!("bench_to_{i}"), "concept", Some("space_a"))
                .await
                .unwrap();
            let mem_id = format!("mem_{i}");
            db.create_relation_with_span(
                &from,
                &to,
                "works_on",
                Some("post_ingest"),
                None,
                None,
                Some(&mem_id),
                None, // span_quote → payload NULL → entailment-only backlog
                None,
                None,
                None,
            )
            .await
            .unwrap();
        }
        let backlog_secs = t_backlog.elapsed().as_secs_f64();

        // Guard the load-bearing `+m.source` access-path fix (Gate 3, §3.3) by
        // EXPLAIN-ing the PRODUCTION scan verbatim — the same
        // `MemoryDB::EDGE_GROUNDING_CANDIDATE_SCAN_SQL` the sweep runs, not a
        // hand-copy — so stripping the `+` from production reddens THIS assert by
        // cause, before the p95 gate below reddens by symptom. The memories LEFT
        // JOIN must ride the selective `idx_memories_source_id`, never
        // `idx_memories_source (source=?)` (a whole-'memory'-table scan per
        // relation, ~1.1s/tick at 100k).
        {
            let conn = db.conn.lock().await;
            let plan_sql = format!(
                "EXPLAIN QUERY PLAN {}",
                MemoryDB::EDGE_GROUNDING_CANDIDATE_SCAN_SQL
            );
            let mut rows = conn
                .query(&plan_sql, libsql::params![0i64, 50i64])
                .await
                .unwrap();
            let mut plan = String::new();
            while let Some(row) = rows.next().await.unwrap() {
                plan.push_str(&row.get::<String>(3).unwrap_or_default());
                plan.push('\n');
            }
            drop(rows);
            drop(conn);
            assert!(
                plan.contains("idx_memories_source_id"),
                "Gate 3 access-path regression: memories join is not using \
                 idx_memories_source_id (the `+m.source` fix). Plan:\n{plan}"
            );
            assert!(
                !plan.contains("idx_memories_source (source"),
                "Gate 3 access-path regression: memories join fell back to the \
                 full-table idx_memories_source (source=?) scan. Plan:\n{plan}"
            );
        }

        // --- drive ticks: always-entail stub, measure per-tick mutex hold ------
        let llm: std::sync::Arc<dyn crate::llm_provider::LlmProvider> = std::sync::Arc::new(
            crate::llm_provider::CannedLlmProvider::new(r#"{"score": 1.0}"#),
        );
        let prompts = crate::prompts::PromptRegistry::default();

        let mut holds_ms: Vec<f64> = Vec::new();
        let mut full_ticks = 0usize;
        let mut cum_promoted = 0usize;
        let mut cum_scanned = 0usize;
        let mut ticks = 0usize;
        loop {
            let r = crate::edge_grounding::run_edge_grounding_tick(&db, &llm, &prompts)
                .await
                .unwrap();
            ticks += 1;
            // Gate 2.2 (b): per-tick bounds.
            assert!(r.scanned <= 50, "tick {ticks}: scanned {} > 50", r.scanned);
            assert!(
                r.entailment_calls <= 25,
                "tick {ticks}: entailment_calls {} > 25",
                r.entailment_calls
            );
            cum_promoted += r.promoted;
            cum_scanned += r.scanned;
            // Gate 2.2 (c) — "promotion never regresses" — is the DB-truth
            // grounded_before == grounded_after check after the drain (a
            // cumulative-counter comparison here would be tautological for a
            // monotone += counter and could not detect a grounded=1→0 revert).
            if r.promoted > 0 {
                holds_ms.push(r.db_mutex_hold.as_secs_f64() * 1000.0);
                if r.promoted == 25 {
                    full_ticks += 1;
                }
            }
            if !r.progressed {
                break;
            }
            assert!(ticks < 200, "drain did not terminate");
        }

        // Gate 2.2 (d): a further tick past the drained backlog promotes 0.
        let drained = crate::edge_grounding::run_edge_grounding_tick(&db, &llm, &prompts)
            .await
            .unwrap();
        assert_eq!(
            drained.promoted, 0,
            "drained backlog promotes 0 (idempotent)"
        );
        assert_eq!(drained.scanned, 0, "cursor past end: nothing left to scan");

        // Gate 2.2 (c) reinforced — no `grounded=1 → 0`: reset the cursor to 0 and
        // re-run. Every backlog edge is grounded=1 now, so the free grounded!=0
        // skip fires for all of them: 0 promoted, 0 entailment calls, grounded=1
        // count unchanged (the `AND grounded=0` flip guard holds).
        let grounded_before = count_grounded_relates(&db).await;
        db.set_app_metadata(
            crate::edge_grounding::EDGE_GROUNDING_CURSOR_KEY,
            &serde_json::to_string(&crate::edge_grounding::GroundingState::default()).unwrap(),
        )
        .await
        .unwrap();
        let rerun = crate::edge_grounding::run_edge_grounding_tick(&db, &llm, &prompts)
            .await
            .unwrap();
        assert_eq!(rerun.promoted, 0, "re-run over grounded=1 promotes 0");
        assert_eq!(
            rerun.entailment_calls, 0,
            "re-run spends no entailment on already-grounded edges"
        );
        let grounded_after = count_grounded_relates(&db).await;
        assert_eq!(
            grounded_before, grounded_after,
            "no grounded=1 → 0 revert across a re-run"
        );

        // --- Gate 3: p95 + max over the full ticks -----------------------------
        assert!(
            full_ticks >= 20,
            "need >=20 full ticks for a p95; got {full_ticks} (raise BACKLOG)"
        );
        let mut sorted = holds_ms.clone();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
        let p95_idx = ((sorted.len() as f64 * 0.95).ceil() as usize)
            .saturating_sub(1)
            .min(sorted.len() - 1);
        let p95 = sorted[p95_idx];
        let max = *sorted.last().unwrap();

        eprintln!("[m3g bench] corpus: memories={MEMORIES} pages={PAGES} backlog={BACKLOG}");
        eprintln!("[m3g bench] seed={seed_secs:.1}s backlog_seed={backlog_secs:.1}s");
        eprintln!(
            "[m3g bench] ticks={ticks} full_ticks={full_ticks} promoted={cum_promoted} scanned={cum_scanned} promoted/scanned={:.3}",
            cum_promoted as f64 / cum_scanned.max(1) as f64
        );
        eprintln!(
            "[m3g bench] db_mutex_hold over {} promoting ticks: p95={p95:.1}ms max={max:.1}ms",
            holds_ms.len()
        );

        // Gate 3 ceilings.
        assert!(
            max <= 2000.0,
            "Gate 3 hard-fail: a tick held the mutex {max:.1}ms > 2s"
        );
        assert!(
            p95 <= 500.0,
            "Gate 3: p95 mutex hold {p95:.1}ms > 500ms ceiling"
        );
    }

    async fn count_grounded_relates(db: &MemoryDB) -> i64 {
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT COUNT(*) FROM edges WHERE edge_type='relates' AND grounded=1",
                (),
            )
            .await
            .unwrap();
        rows.next().await.unwrap().unwrap().get::<i64>(0).unwrap()
    }

    /// §6.5-scale acceptance for the M3 PR-2 entity<->page reader cutover
    /// (100k memories / 5k pages / 10k entities). Manual-only (needs
    /// minutes + hundreds of MB); run with:
    ///   RUSTC_WRAPPER= cargo test -p wenlan-core --lib \
    ///     db::tests::bench_reconcile_entity_page_parity_at_scale -- --ignored --nocapture
    /// Mirrors `bench_reconcile_parity_at_scale`: memories/pages are seeded
    /// via raw batched SQL in one BEGIN/COMMIT, no embeddings (same
    /// technique, same style). Entities go through the REAL dual-write path
    /// (`store_entity`) instead -- the point is proving the shadow-page
    /// invariant holds at scale, which raw SQL can't exercise. Proves three
    /// things at scale rather than on a toy DB: (a) `reconcile_entity_page_
    /// parity` stays exact -- drift 0 clean, drift 10 after perturbing 10
    /// shadows; (b) the flipped (cutover-ON) read of `list_entities_scoped`/
    /// `get_entity_detail_scoped` is byte-identical to legacy (cutover-OFF),
    /// with both timings printed for the PR body; (c) the flipped queries
    /// still reach the shadow through an index once the planner has real
    /// cardinality to reason about -- stage c's EXPLAIN test runs on an
    /// empty DB, this is the one that counts.
    #[tokio::test]
    #[ignore]
    async fn bench_reconcile_entity_page_parity_at_scale() {
        use std::time::Instant;
        const MEMORIES: usize = 100_000;
        const PAGES: usize = 5_000;
        const CITES_PER_PAGE: usize = MEMORIES / PAGES; // 20
        const ENTITIES: usize = 10_000;
        const PERTURB: usize = 10;
        const DETAIL_SAMPLE: usize = 1_000;
        const SPACE: &str = "space_a";

        // Deterministic pseudo-random sample (hash-order) of `count` ids --
        // avoids adding a `rand` dev-dependency for bench-only code.
        fn sample_ids(ids: &[String], count: usize) -> Vec<String> {
            use std::collections::hash_map::DefaultHasher;
            use std::hash::{Hash, Hasher};
            let mut scored: Vec<(u64, &String)> = ids
                .iter()
                .map(|id| {
                    let mut hasher = DefaultHasher::new();
                    id.hash(&mut hasher);
                    (hasher.finish(), id)
                })
                .collect();
            scored.sort_unstable_by_key(|(h, _)| *h);
            scored
                .into_iter()
                .take(count)
                .map(|(_, id)| id.clone())
                .collect()
        }

        let (db, _dir) = test_db().await;

        // ---- seed 100k memories + 5k pages (mirrors
        // bench_reconcile_parity_at_scale exactly) ----
        let t_seed_mp = Instant::now();
        {
            let conn = db.conn.lock().await;
            conn.execute("BEGIN", ()).await.unwrap();
            for i in 0..MEMORIES {
                conn.execute(
                    "INSERT INTO memories (id, content, source, source_id, title, chunk_index, \
                        last_modified, chunk_type, source_agent, space, confidence, confirmed, \
                        memory_type, pending_revision) \
                     VALUES (?1, 'c', 'memory', ?1, 't', 0, 1712707200, 'text', NULL, 'space_a', 1.0, 0, 'fact', 0)",
                    libsql::params![format!("mem_{i}")],
                )
                .await
                .unwrap();
            }
            for p in 0..PAGES {
                conn.execute(
                    "INSERT INTO pages (id, title, content, created_at, last_compiled, last_modified, space, workspace) \
                     VALUES (?1, 't', 'c', '2024-01-01T00:00:00Z', '2024-01-01T00:00:00Z', '2024-01-01T00:00:00Z', 'space_a', 'space_a')",
                    libsql::params![format!("page_{p}")],
                )
                .await
                .unwrap();
                for k in 0..CITES_PER_PAGE {
                    let mem = p * CITES_PER_PAGE + k;
                    conn.execute(
                        "INSERT INTO page_sources (page_id, memory_source_id, linked_at, link_reason) \
                         VALUES (?1, ?2, 1712707200, 'bench')",
                        libsql::params![format!("page_{p}"), format!("mem_{mem}")],
                    )
                    .await
                    .unwrap();
                }
            }
            conn.execute("COMMIT", ()).await.unwrap();
        }
        let seed_mp_secs = t_seed_mp.elapsed().as_secs_f64();
        // Phase-localization: print as soon as this phase lands, not batched
        // with the next one -- a kill during entity seeding must still leave
        // evidence that memories/pages seeded clean.
        eprintln!("[bench §6.5 entity] memories={MEMORIES} pages={PAGES} entities={ENTITIES}");
        eprintln!("[bench §6.5 entity] seed_mem_pages={seed_mp_secs:.1}s");

        // ---- seed 10k entities through the REAL dual-write path; every
        // call gets its own shadow page + entity_page_map row ----
        let t_seed_entities = Instant::now();
        let mut entity_ids: Vec<String> = Vec::with_capacity(ENTITIES);
        for i in 0..ENTITIES {
            let id = db
                .store_entity(
                    &format!("Bench Entity {i}"),
                    "person",
                    Some(SPACE),
                    None,
                    Some(0.7),
                )
                .await
                .unwrap();
            entity_ids.push(id);
        }
        let seed_entities_secs = t_seed_entities.elapsed().as_secs_f64();
        eprintln!(
            "[bench §6.5 entity] seed_entities={seed_entities_secs:.1}s ({:.1} entities/sec)",
            ENTITIES as f64 / seed_entities_secs
        );

        // ---- M3 stage F: the adapter round-trips entity_id <-> page_id for
        // every seeded entity, at the same scale the parity oracle is proven
        // at below ----
        {
            let conn = db.conn.lock().await;
            for id in &entity_ids {
                let page_id = entity_page_adapter::page_id_for_entity(&conn, id)
                    .await
                    .unwrap()
                    .unwrap_or_else(|| panic!("{id} must have a mapped page_id at scale"));
                let round_tripped = entity_page_adapter::entity_id_for_page(&conn, &page_id)
                    .await
                    .unwrap();
                assert_eq!(
                    round_tripped.as_deref(),
                    Some(id.as_str()),
                    "adapter bijection must round-trip at scale for {id}"
                );
            }
        }

        // ---- reconcile: clean parity must hold at scale ----
        let t_reconcile = Instant::now();
        let report = db.reconcile_entity_page_parity().await.unwrap();
        let reconcile_secs = t_reconcile.elapsed().as_secs_f64();
        eprintln!(
            "[bench §6.5 entity] reconcile={reconcile_secs:.2}s ({:.0} entities/sec) expected_active={} actual_active={} drift={}",
            report.expected_active as f64 / reconcile_secs,
            report.expected_active,
            report.actual_active,
            report.drift_count
        );
        assert_eq!(report.drift_count, 0, "parity must hold at §6.5 scale");
        assert_eq!(
            report.expected_active, ENTITIES,
            "one entities row per seeded entity"
        );
        assert_eq!(
            report.actual_active, ENTITIES,
            "one live shadow page per seeded entity"
        );
        {
            let conn = db.conn.lock().await;
            let (proven_epoch, drift) = entity_page_parity_watermark_row(&conn).await.unwrap();
            assert_eq!(drift, Some(0), "watermark must record clean drift");
            assert!(proven_epoch.is_some(), "watermark must be stamped");
        }

        // ---- flipped-read benchmark at scale: cutover OFF (legacy) vs ON
        // (hybrid), on the SAME seeded DB, under the clean watermark just
        // proven above ----
        let scope = ReadScope::Space(SPACE.to_string());
        let detail_ids = sample_ids(&entity_ids, DETAIL_SAMPLE);

        db.set_entity_reader_cutover(MemoryDB::SCOPED_ENTITIES_CONSUMER, false)
            .await
            .unwrap();
        let t_list_off = Instant::now();
        let list_off = db.list_entities_scoped(None, &scope).await.unwrap();
        let list_off_secs = t_list_off.elapsed().as_secs_f64();
        let t_detail_off = Instant::now();
        let mut detail_off = Vec::with_capacity(detail_ids.len());
        for id in &detail_ids {
            detail_off.push(db.get_entity_detail_scoped(id, &scope).await.unwrap());
        }
        let detail_off_secs = t_detail_off.elapsed().as_secs_f64();
        eprintln!(
            "[bench §6.5 entity] OFF leg done: list={list_off_secs:.3}s detail={detail_off_secs:.3}s"
        );

        db.set_entity_reader_cutover(MemoryDB::SCOPED_ENTITIES_CONSUMER, true)
            .await
            .unwrap();
        {
            let conn = db.conn.lock().await;
            assert!(
                MemoryDB::reader_uses_entity_pages(&conn, MemoryDB::SCOPED_ENTITIES_CONSUMER)
                    .await
                    .unwrap(),
                "sanity: a clean, current watermark must open the gate at scale"
            );
        }
        let t_list_on = Instant::now();
        let list_on = db.list_entities_scoped(None, &scope).await.unwrap();
        let list_on_secs = t_list_on.elapsed().as_secs_f64();
        let t_detail_on = Instant::now();
        let mut detail_on = Vec::with_capacity(detail_ids.len());
        for id in &detail_ids {
            detail_on.push(db.get_entity_detail_scoped(id, &scope).await.unwrap());
        }
        let detail_on_secs = t_detail_on.elapsed().as_secs_f64();

        assert_eq!(
            list_off.len(),
            ENTITIES,
            "sanity: full listing covers every seeded entity"
        );
        assert_eq!(
            format!("{list_off:?}"),
            format!("{list_on:?}"),
            "flipped list_entities_scoped must be byte-identical to legacy at scale"
        );
        assert_eq!(
            format!("{detail_off:?}"),
            format!("{detail_on:?}"),
            "flipped get_entity_detail_scoped must be byte-identical to legacy at scale"
        );
        eprintln!(
            "[bench §6.5 entity] list_entities_scoped (full listing, n={ENTITIES}): off={list_off_secs:.3}s on={list_on_secs:.3}s"
        );
        eprintln!(
            "[bench §6.5 entity] get_entity_detail_scoped (n={DETAIL_SAMPLE}): off={detail_off_secs:.3}s on={detail_on_secs:.3}s"
        );

        // ---- EXPLAIN QUERY PLAN at scale: the flipped queries must reach
        // the shadow through an index, not a bare `SCAN pages` -- the
        // stage-c EXPLAIN test runs on an empty DB where the planner can
        // choose differently; this is the one that counts ----
        {
            let conn = db.conn.lock().await;
            let list_plan = query_plan_detail(
                &conn,
                &format!(
                    "SELECT e.id, p.title, p.entity_type, e.space, e.source_agent, p.confidence, \
                            p.entity_confirmed, e.created_at, e.updated_at \
                     FROM entities e \
                     JOIN entity_page_map m ON m.entity_id = e.id \
                     JOIN pages p ON p.id = m.page_id AND p.kind = 'entity' AND p.status = 'active' \
                     WHERE e.space = '{SPACE}' ORDER BY e.updated_at DESC, e.id ASC"
                ),
            )
            .await;
            for line in list_plan.split(" | ") {
                let upper = line.to_uppercase();
                if upper.contains(" P ") || upper.contains("PAGES") {
                    assert!(
                        upper.contains("USING"),
                        "pages access must use the entity_page_map UNIQUE index or the \
                         pages PK, not a bare scan, at scale: {line} (full plan: {list_plan})"
                    );
                }
            }
            assert!(
                list_plan.to_uppercase().contains("USING"),
                "the flipped list_entities_scoped query must use at least one index at scale: {list_plan}"
            );

            let sample_id = &detail_ids[0];
            let detail_plan = query_plan_detail(
                &conn,
                &format!(
                    "SELECT e.id, p.title, p.entity_type, e.space, e.source_agent, p.confidence, \
                            p.entity_confirmed, e.created_at, e.updated_at \
                     FROM entities e \
                     JOIN entity_page_map m ON m.entity_id = e.id \
                     JOIN pages p ON p.id = m.page_id AND p.kind = 'entity' AND p.status = 'active' \
                     WHERE e.id = '{sample_id}' AND e.space = '{SPACE}' LIMIT 1"
                ),
            )
            .await;
            for line in detail_plan.split(" | ") {
                let upper = line.to_uppercase();
                if upper.contains(" P ") || upper.contains("PAGES") {
                    assert!(
                        upper.contains("USING"),
                        "pages access must use the entity_page_map UNIQUE index or the \
                         pages PK, not a bare scan, at scale: {line} (full plan: {detail_plan})"
                    );
                }
            }
            assert!(
                detail_plan.to_uppercase().contains("USING"),
                "the flipped get_entity_detail_scoped query must use at least one index at scale: {detail_plan}"
            );
            eprintln!("[bench §6.5 entity] list plan: {list_plan}");
            eprintln!("[bench §6.5 entity] detail plan: {detail_plan}");
        }

        // ---- perturb 10 shadows and re-reconcile: the oracle stays exact
        // at scale, not just on toy DBs ----
        let perturbed: Vec<String> = entity_ids.iter().take(PERTURB).cloned().collect();
        {
            let conn = db.conn.lock().await;
            for id in &perturbed {
                conn.execute(
                    "UPDATE pages SET entity_type = 'organization' \
                     WHERE id = (SELECT page_id FROM entity_page_map WHERE entity_id = ?1)",
                    libsql::params![id.as_str()],
                )
                .await
                .unwrap();
            }
        }
        let t_reconcile_dirty = Instant::now();
        let dirty_report = db.reconcile_entity_page_parity().await.unwrap();
        let reconcile_dirty_secs = t_reconcile_dirty.elapsed().as_secs_f64();
        eprintln!(
            "[bench §6.5 entity] reconcile_after_perturb={reconcile_dirty_secs:.2}s (clean was {reconcile_secs:.2}s) drift={}",
            dirty_report.drift_count
        );
        assert_eq!(
            dirty_report.drift_count, PERTURB,
            "exactly the {PERTURB} perturbed shadows must be flagged corrupt, not more or fewer"
        );
    }

    /// M3 stage F acceptance-box proof: with the "scoped_entities" cutover
    /// gate OFF vs ON, `list_entities_scoped`/`get_entity_detail_scoped`
    /// results serialize to byte-identical JSON -- the actual wire shape,
    /// not just Rust `Debug` output -- proving the adapter's entity_id<->
    /// page_id translation makes no app-visible shape change. Small-scale,
    /// non-ignored sibling of `bench_reconcile_entity_page_parity_at_scale`'s
    /// ON/OFF comparison above.
    #[tokio::test]
    async fn scoped_entities_cutover_flip_is_wire_invariant() {
        const SPACE: &str = "wire_invariance_space";
        let (db, _dir) = test_db().await;
        let mut entity_ids: Vec<String> = Vec::new();
        for i in 0..5 {
            let id = db
                .store_entity(
                    &format!("Wire Invariance Entity {i}"),
                    "person",
                    Some(SPACE),
                    Some("test"),
                    Some(0.8),
                )
                .await
                .unwrap();
            entity_ids.push(id);
        }
        db.create_relation(
            &entity_ids[0],
            &entity_ids[1],
            "related_to",
            None,
            None,
            None,
            None,
        )
        .await
        .unwrap();
        {
            let conn = db.conn.lock().await;
            conn.execute(
                "INSERT INTO observations (id, entity_id, content, source_agent, confidence, confirmed, created_at) \
                 VALUES ('wire_invariance_obs', ?1, 'observed', NULL, 0.9, 1, unixepoch())",
                libsql::params![entity_ids[0].clone()],
            )
            .await
            .unwrap();
        }

        let scope = ReadScope::Space(SPACE.to_string());

        db.set_entity_reader_cutover(MemoryDB::SCOPED_ENTITIES_CONSUMER, false)
            .await
            .unwrap();
        let list_off = db.list_entities_scoped(None, &scope).await.unwrap();
        let mut detail_off = Vec::with_capacity(entity_ids.len());
        for id in &entity_ids {
            detail_off.push(db.get_entity_detail_scoped(id, &scope).await.unwrap());
        }

        db.set_entity_reader_cutover(MemoryDB::SCOPED_ENTITIES_CONSUMER, true)
            .await
            .unwrap();
        assert_eq!(
            db.reconcile_entity_page_parity().await.unwrap().drift_count,
            0,
            "seed must reconcile clean before the gate can open"
        );
        {
            let conn = db.conn.lock().await;
            assert!(
                MemoryDB::reader_uses_entity_pages(&conn, MemoryDB::SCOPED_ENTITIES_CONSUMER)
                    .await
                    .unwrap(),
                "sanity: a clean, current watermark must open the gate"
            );
        }
        let list_on = db.list_entities_scoped(None, &scope).await.unwrap();
        let mut detail_on = Vec::with_capacity(entity_ids.len());
        for id in &entity_ids {
            detail_on.push(db.get_entity_detail_scoped(id, &scope).await.unwrap());
        }

        assert_eq!(list_off.len(), 5, "sanity: all seeded entities are listed");
        assert_eq!(
            list_off.iter().map(|e| e.id.clone()).collect::<Vec<_>>(),
            list_on.iter().map(|e| e.id.clone()).collect::<Vec<_>>(),
            "sanity: same entity_ids on both arms"
        );
        assert_eq!(
            serde_json::to_value(&list_off).unwrap(),
            serde_json::to_value(&list_on).unwrap(),
            "list_entities_scoped wire shape must be byte-identical across the cutover flip"
        );
        assert_eq!(
            serde_json::to_value(&detail_off).unwrap(),
            serde_json::to_value(&detail_on).unwrap(),
            "get_entity_detail_scoped wire shape must be byte-identical across the cutover flip"
        );
    }

    #[tokio::test]
    async fn migration_81_creates_edges_and_provenance_schema() {
        let (db, _dir) = test_db().await;
        let conn = db.conn.lock().await;
        for table in [
            "edges",
            "provenance_roots",
            "provenance_root_minhash_bands",
            "edges_migration_state",
        ] {
            let mut rows = conn
                .query(
                    "SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name=?1",
                    libsql::params![table],
                )
                .await
                .unwrap();
            let present: i64 = rows.next().await.unwrap().unwrap().get(0).unwrap();
            assert_eq!(present, 1, "{table} table should exist after migration 81");
        }
        let mut rows = conn
            .query(
                "SELECT COUNT(*) FROM sqlite_master WHERE type='trigger' AND name='edges_space_fence'",
                (),
            )
            .await
            .unwrap();
        let present: i64 = rows.next().await.unwrap().unwrap().get(0).unwrap();
        assert_eq!(present, 1, "edges_space_fence trigger should exist");

        let uv: i64 = {
            let mut rows = conn.query("PRAGMA user_version", ()).await.unwrap();
            rows.next().await.unwrap().unwrap().get(0).unwrap()
        };
        assert_eq!(uv as u32, crate::db::SCHEMA_VERSION);
    }

    #[tokio::test]
    async fn migration_81_migration_state_row_records_report() {
        let (db, _dir) = test_db().await;
        let conn = db.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT stage, completed_at, report_json FROM edges_migration_state WHERE id = 1",
                (),
            )
            .await
            .unwrap();
        let row = rows
            .next()
            .await
            .unwrap()
            .expect("durable migration state row must exist");
        let stage: String = row.get(0).unwrap();
        let completed_at: Option<i64> = row.get(1).unwrap();
        let report_json: String = row.get(2).unwrap();
        assert_eq!(stage, "backfilled");
        assert!(completed_at.is_some());
        let report: serde_json::Value = serde_json::from_str(&report_json).unwrap();
        assert!(report.get("relations").is_some());
        assert!(report.get("page_sources").is_some());
        assert!(report.get("page_evidence").is_some());
        assert!(report.get("page_links").is_some());
        assert!(report.get("pages_citations").is_some());
        assert!(report.get("cross_space_audit").is_some());
    }

    #[tokio::test]
    async fn migration_81_page_evidence_backfill_counts_multichunk_memory_once() {
        // A memory is stored as one row PER CHUNK sharing a `source_id`. A
        // memory-kind `page_evidence` row citing it must count as ONE
        // classifiable citation, not once per chunk. Regression for the
        // `LEFT JOIN memories` fan-out that inflated the migration report's
        // classifiable count N-fold for an N-chunk memory (the edge itself was
        // always deduped by `ON CONFLICT DO NOTHING`; only the count lied).
        let (db, _dir) = test_db().await;
        seed_memory_with_source_id_and_space(&db, "mem_multi", "chunk zero", "space_a").await;
        {
            let conn = db.conn.lock().await;
            // Second chunk of the SAME source_id (distinct primary-key id).
            conn.execute(
                "INSERT INTO memories (id, content, source, source_id, title, chunk_index, \
                                        last_modified, chunk_type, source_agent, space, confidence, \
                                        confirmed, memory_type, pending_revision) \
                 VALUES ('mem_multi_c1', 'chunk one', 'memory', 'mem_multi', 'test', 1, 1712707200, 'text', NULL, 'space_a', 1.0, 0, 'fact', 0)",
                (),
            )
            .await
            .unwrap();
            insert_raw_page_for_m81_test(&conn, "page_1", "space_a").await;
            conn.execute(
                "INSERT INTO page_evidence (page_id, source_kind, locator, title, linked_at, link_reason) \
                 VALUES ('page_1', 'memory', 'mem_multi', NULL, 1712707200, NULL)",
                (),
            )
            .await
            .unwrap();
        }
        rerun_migration_81(&db).await;

        let conn = db.conn.lock().await;
        // Exactly one edge (dedup was never the bug).
        let edge_present = edge_row(&conn, "cites", "page_1", "mem_multi").await;
        assert!(edge_present.is_some(), "the single cites edge must exist");
        // And the report counts the citation once, not once per chunk.
        let report_json: String = {
            let mut rows = conn
                .query(
                    "SELECT report_json FROM edges_migration_state WHERE id = 1",
                    (),
                )
                .await
                .unwrap();
            rows.next().await.unwrap().unwrap().get(0).unwrap()
        };
        let report: serde_json::Value = serde_json::from_str(&report_json).unwrap();
        let classifiable = report["page_evidence"]["classifiable"].as_i64().unwrap();
        assert_eq!(
            classifiable, 1,
            "a 2-chunk memory cited once must count as 1 classifiable, not 2 (LEFT JOIN fan-out)"
        );
    }

